-- Part 3 of 4. Run the parts in order.
-- =====================================================================
-- Akeso reference data seed
-- 30 diseases, 74 symptoms, 49 medicines,
-- 97 drug-drug interaction pairs, 12 multi-drug rules.
--
-- Researched from StatPearls (NCBI Bookshelf), WHO, CDC, DOH Philippines,
-- PSMID/PCP, GINA, GOLD, ADA, AHA/ESC, NICE and FDA labels on DailyMed.
-- Every clinical reference URL was opened and checked when this file was
-- made. Textbook ("mother book") references carry no URL on purpose.
--
-- Educational reference content for a student platform, not a substitute
-- for current product labeling or clinical judgment.
--
-- Safe to run more than once: rows with these ids are updated, and their
-- child rows (lists, links, references) are replaced.
-- Requires database/migrations/001_medication_safety_reference.sql.
-- =====================================================================


BEGIN;

-- ==================================================================== DISEASES

CREATE TEMP TABLE _seed_diseases ON COMMIT DROP AS SELECT id, name, scientific_name, description, body_system_id, severity, urgency, urgency_criteria, contagious, pathophysiology, clinicopathologic_correlation, onset_progression, follow_up_monitoring, source_attribution, is_published FROM public.diseases WITH NO DATA;
UPDATE public.diseases AS x SET name = t.name, scientific_name = t.scientific_name, description = t.description, body_system_id = t.body_system_id, severity = t.severity, urgency = t.urgency, urgency_criteria = t.urgency_criteria, contagious = t.contagious, pathophysiology = t.pathophysiology, clinicopathologic_correlation = t.clinicopathologic_correlation, onset_progression = t.onset_progression, follow_up_monitoring = t.follow_up_monitoring, source_attribution = t.source_attribution, is_published = t.is_published, updated_at = now()
  FROM _seed_diseases AS t WHERE x.id = t.id;
  SELECT id, name, scientific_name, description, body_system_id, severity, urgency, urgency_criteria, contagious, pathophysiology, clinicopathologic_correlation, onset_progression, follow_up_monitoring, source_attribution, is_published FROM _seed_diseases AS t
  WHERE NOT EXISTS (SELECT 1 FROM public.diseases AS x WHERE x.id = t.id);












-- ------------------------------------- disease <-> symptom (drives the Symptom Checker)


-- ------------------------------------------- disease <-> medicine (safety in that disease)


COMMIT;
