INSERT INTO _seed_diseases (id, name, scientific_name, description, body_system_id, severity, urgency, urgency_criteria, contagious, pathophysiology, clinicopathologic_correlation, onset_progression, follow_up_monitoring, source_attribution, is_published) VALUES
    ('dengue', 'Dengue', 'Dengue virus (DENV-1 to DENV-4) infection', 'Dengue is an acute mosquito-borne viral infection caused by four antigenically distinct dengue virus serotypes and transmitted mainly by Aedes aegypti and Aedes albopictus. It is endemic in the Philippines, with transmission rising during the rainy season. Most infections are asymptomatic or self-limited, but a minority progress to severe dengue with plasma leakage, shock, bleeding or organ impairment. Case fatality falls below 1% with early recognition and appropriate fluid management.', (SELECT id FROM public.body_systems WHERE name = 'Multisystem (Systemic Infection)' ORDER BY id LIMIT 1), 'Severe', 'SEE_DOCTOR_SOON', 'Acute febrile illness compatible with dengue without warning signs warrants prompt clinical review with CBC. Any warning sign (severe abdominal pain, persistent vomiting, mucosal bleeding, lethargy/restlessness, fluid accumulation, rising hematocrit with falling platelets) or signs of shock, severe bleeding or organ impairment place the presentation in the EMERGENCY tier.', false, 'Dengue virus inoculated by an infected Aedes mosquito replicates in dendritic cells, monocytes and macrophages, producing viremia and a strong innate immune and cytokine response. The secreted nonstructural protein NS1 disrupts the endothelial glycocalyx and activates Toll-like receptor 4 signaling. The result is a transient but marked increase in capillary permeability, with plasma leakage rather than direct destruction of endothelial cells. In a secondary infection with a different serotype, subneutralizing antibodies can enhance viral entry into Fc receptor-bearing cells (antibody-dependent enhancement), which increases the risk of severe disease. Thrombocytopenia and coagulation abnormalities add to the bleeding tendency.', 'Plasma leakage produces hemoconcentration (rising hematocrit), pleural effusion, ascites and, when severe, hypovolemic shock. Leakage peaks around defervescence, so a patient may worsen as the fever settles. Thrombocytopenia and capillary fragility account for petechiae, a positive tourniquet test and mucosal bleeding.', 'Incubation is about 4-10 days after the mosquito bite. The febrile phase has abrupt high fever with headache, retro-orbital pain, myalgia and arthralgia. The critical phase follows around defervescence (about days 4-6), when capillary permeability and the risk of plasma leakage are greatest. In the recovery phase hemodynamics stabilize and extravasated fluid is reabsorbed, with a risk of fluid overload if IV fluids are continued.', 'Serial CBC with hematocrit and platelet count from baseline, repeated closely through the critical phase. Vital signs, urine output, oral intake and warning signs are reviewed daily. After the critical phase, IV fluids are reduced and signs of fluid overload monitored. Discharge criteria include being afebrile for at least 24 hours with a stable hematocrit and no ongoing IV fluid requirement.', 'StatPearls: Dengue Fever (2026); WHO fact sheet Dengue and severe dengue; DOH Philippines 4S campaign; Harrison''s Principles of Internal Medicine, 21st ed.', true),
    ('typhoid_fever', 'Typhoid Fever', 'Salmonella enterica serovar Typhi infection (enteric fever)', 'Typhoid fever is a systemic infection caused by the exclusively human pathogen Salmonella enterica serovar Typhi. It is acquired by the fecal-oral route through contaminated food or water, including food handled by chronic carriers. It causes prolonged fever with abdominal symptoms and can be complicated by intestinal perforation, hemorrhage and encephalopathy. Globally about 9 million people are affected and about 110,000 die each year, with antimicrobial resistance a growing problem in Asia.', (SELECT id FROM public.body_systems WHERE name = 'Multisystem (Systemic Infection)' ORDER BY id LIMIT 1), 'Moderate', 'SEE_DOCTOR_SOON', 'A prolonged or stepwise-rising fever with abdominal symptoms in someone exposed to unsafe water or food warrants prompt evaluation with blood culture. The EMERGENCY tier applies to severe abdominal pain or peritonism (possible perforation), gastrointestinal bleeding, delirium or other altered mental status, or hemodynamic instability, typically in the 2nd-3rd week.', true, 'Ingested S. Typhi that survive gastric acid invade the distal ileal mucosa and the lymphoid tissue of Peyer patches. The bacteria are taken up by macrophages and dendritic cells, in which they survive intracellularly. A transient primary bacteremia seeds the reticuloendothelial system (liver, spleen, bone marrow) and the gallbladder, and a sustained secondary bacteremia follows. Hyperplasia of Peyer patches and later necrosis, partly endotoxin-mediated, lead to ulceration, bleeding and perforation. Persistent gallbladder colonization, particularly with gallstones, underlies chronic carriage.', 'Sustained bacteremia and cytokine release produce the stepwise, persistent fever, malaise and headache. Involvement of the reticuloendothelial system explains hepatosplenomegaly. Ileal Peyer patch hyperplasia causes abdominal pain and altered bowel habit, and ulceration of these patches causes GI hemorrhage and perforation in the 2nd-3rd week. Rose spots are small cutaneous emboli of bacteria.', 'Incubation is 6-30 days. In the first week fever rises stepwise to 38-40 C, often peaking in the afternoon, with malaise, headache, anorexia and abdominal discomfort. Relative bradycardia and rose spots (under 25% of patients) may occur. By weeks 2-3 abdominal symptoms (constipation or diarrhea) and hepatosplenomegaly (29-50%) become established. Complications usually arise 2-3 weeks after onset. About 1-4% of patients become chronic carriers, shedding for at least 12 months.', 'Clinical response to antibiotics (defervescence, oral intake) and close observation for complications in the 2nd-3rd week (abdominal signs, GI bleeding, mental status). Relapse is monitored after treatment. Stool cultures are used to document clearance or identify chronic carriage, which matters particularly for food handlers.', 'StatPearls: Typhoid Fever (2024); WHO fact sheet Typhoid; CDC Typhoid and Paratyphoid Fever clinical overview; Harrison''s Principles of Internal Medicine, 21st ed.', true),
    ('leptospirosis', 'Leptospirosis', 'Leptospira spp. infection (severe icteric form: Weil disease)', 'Leptospirosis is a zoonotic spirochetal infection acquired through contact of broken skin or mucous membranes with water or soil contaminated by the urine of infected animals, chiefly rodents. In the Philippines it rises sharply after typhoons and floods during the rainy season. Most cases are a self-limited febrile illness, but severe disease (Weil disease) combines jaundice, acute kidney injury and hemorrhage, and pulmonary hemorrhage is the leading cause of death.', (SELECT id FROM public.body_systems WHERE name = 'Multisystem (Systemic Infection)' ORDER BY id LIMIT 1), 'Severe', 'SEEK_URGENT_CARE', 'Acute fever with myalgia after floodwater, mud or animal-urine exposure warrants same-day evaluation and early antibiotics. The EMERGENCY tier applies to jaundice, oliguria, dyspnea or hemoptysis (pulmonary hemorrhage), bleeding, altered sensorium or meningeal signs, or unstable vital signs.', false, 'Pathogenic Leptospira penetrate abraded skin or intact mucous membranes (conjunctiva, oral mucosa) and spread through the lymphatics and bloodstream to all organs. They cause widespread endothelial injury and small-vessel vasculitis with capillary leakage and hemorrhage. The kidneys and liver are the main target organs. Renal involvement is a tubulointerstitial nephritis with tubular dysfunction, and hepatic involvement produces cholestatic jaundice. As antibodies appear, organisms are cleared from the blood but can persist in the renal tubules and are shed in urine. Lung capillary injury can cause pulmonary hemorrhage.', 'Diffuse capillary injury explains conjunctival suffusion, myalgia (notably calf and lower-back muscles) and bleeding. Tubular dysfunction produces acute kidney injury, often nonoliguric at first, with potassium wasting. Cholestatic liver involvement produces jaundice. Alveolar capillary damage produces hemoptysis and respiratory failure.', 'Incubation is usually 5-14 days (range 2-30 days). The acute (leptospiremic) phase begins abruptly with fever, headache, myalgia and conjunctival suffusion and lasts several days. It may be followed by a brief afebrile interval and then an immune phase, which can include aseptic meningitis. A minority progress to severe disease with jaundice, renal failure, hemorrhage and pulmonary hemorrhagic syndrome (case fatality can exceed 50%).', 'Serial serum creatinine, potassium, urine output and urinalysis. Bilirubin and liver enzymes, CBC with platelet count, and bleeding parameters are also followed. Respiratory status is monitored with oxygen saturation, ABG and chest radiograph for early pulmonary hemorrhage. Patients are observed for a Jarisch-Herxheimer reaction after antibiotics start. Renal function is followed until recovery.', 'StatPearls: Leptospirosis (2024); CDC Leptospirosis clinical overview; CDC Yellow Book 2024 Leptospirosis; PhilHealth Leptospirosis Policy Statements (based on the 2010 Philippine Leptospirosis Task Force CPG); Harrison''s Principles of Internal Medicine, 21st ed.', true),
    ('tuberculosis', 'Pulmonary Tuberculosis', 'Mycobacterium tuberculosis pulmonary infection', 'Pulmonary tuberculosis is a chronic granulomatous infection of the lungs caused by Mycobacterium tuberculosis and spread by airborne droplet nuclei. It is the world''s leading infectious cause of death. The Philippines is one of the 30 high-burden countries and accounts for about 6.8% of global new cases. TB is preventable and curable with a standardized multidrug regimen, which the DOH National TB Control Program provides free through DOTS facilities.', (SELECT id FROM public.body_systems WHERE name = 'Respiratory System' ORDER BY id LIMIT 1), 'Severe', 'SEE_DOCTOR_SOON', 'Cough lasting 2 weeks or more, especially with fever, night sweats or weight loss, warrants prompt evaluation with chest radiograph and rapid molecular sputum testing. The EMERGENCY tier applies to massive hemoptysis, respiratory distress, signs of TB meningitis, or drug-induced hepatitis during treatment.', true, 'Inhaled bacilli are ingested by alveolar macrophages, and primed T cells coordinate a granuloma of macrophages, multinucleated giant cells, dendritic cells and fibroblasts. The primary focus and its draining lymph nodes form the Ghon complex, which may heal and calcify. Most infections are contained as latent infection. About 5% progress to active disease within 2 years, and later reactivation is the commonest route to active disease. In active disease, granulomas undergo caseous necrosis, erode into airways and form cavities, mainly in the apical-posterior upper lobe segments where oxygen tension is high. Cavities hold large bacillary loads and drive transmission.', 'Cytokine release (notably TNF-alpha) from chronic granulomatous inflammation produces fever, night sweats, anorexia and weight loss. Caseation and cavitation into bronchi cause productive cough. Erosion of vessels in cavity walls causes hemoptysis. Upper-lobe infiltrates and cavities on chest radiograph reflect the apical predilection of reactivation disease.', 'Primary infection is usually asymptomatic, and about 90% of infected people develop latent infection. Active pulmonary disease develops insidiously over weeks to months with chronic cough, low-grade fever, night sweats, fatigue and weight loss. Asymptomatic yet infectious disease is recognized on screening. Untreated, the disease progresses with cavitation, hemoptysis and respiratory compromise.', 'Sputum smear and/or culture at the end of the intensive phase (month 2) and during continuation to confirm conversion. Culture positivity at 2 months with cavitation prompts an extended continuation phase. Monthly clinical review covers adherence, weight (for dose adjustment) and adverse effects. Liver function tests are done at baseline and if symptoms appear or risk factors exist. Visual acuity and color vision are checked during ethambutol therapy. HIV status and diabetes are screened.', 'StatPearls: Tuberculosis Overview (2024); WHO fact sheet Tuberculosis; DOH Philippines National TB Control Program and NTP Manual of Procedures 6th ed.; Harrison''s Principles of Internal Medicine, 21st ed.', true),
    ('malaria', 'Malaria (Plasmodium falciparum / vivax)', 'Plasmodium falciparum / Plasmodium vivax infection', 'Malaria is a parasitic infection of red blood cells caused by Plasmodium species and transmitted by female Anopheles mosquitoes. P. falciparum causes the most severe disease, while P. vivax can relapse from dormant liver stages. In the Philippines most provinces are malaria-free, and remaining transmission is concentrated in Palawan, historically about 71% P. falciparum and 26% P. vivax, with zoonotic P. knowlesi also documented. Prompt diagnosis and artemisinin-based combination therapy are central to treatment and elimination.', (SELECT id FROM public.body_systems WHERE name = 'Multisystem (Systemic Infection)' ORDER BY id LIMIT 1), 'Severe', 'SEEK_URGENT_CARE', 'Any fever in someone living in or returning from a malaria-endemic area (in the Philippines, mainly Palawan) warrants same-day parasitological testing, because falciparum malaria can deteriorate within hours. The EMERGENCY tier applies to impaired consciousness, seizures, respiratory distress, jaundice, dark urine, severe anemia, prostration, hypoglycemia, renal failure, or parasitemia of 5% or more.', false, 'Sporozoites injected by an Anopheles mosquito reach the liver within about an hour and multiply to release merozoites. The merozoites invade erythrocytes, digest hemoglobin and mature into schizonts, and schizont rupture releases new merozoites and pyrogenic material, producing febrile paroxysms. Erythrocytes infected with P. falciparum adhere to the vascular endothelium (cytoadherence) and are sequestered in the microcirculation of the brain, kidneys and other organs. Sequestration, together with endothelial activation by free heme and the host inflammatory response, drives organ dysfunction. Hemolysis of infected and uninfected red cells causes anemia. P. vivax (and P. ovale) form hypnozoites in the liver, which cause relapses months to years later.', 'Synchronous schizont rupture causes the classic paroxysm of rigors, then high fever, then drenching sweats, recurring every 48 hours in P. vivax. Hemolysis produces anemia, jaundice and dark urine, and splenic clearance of parasitized cells causes splenomegaly. Microvascular sequestration of P. falciparum underlies cerebral malaria (confusion, seizures, coma), acute kidney injury and pulmonary edema.', 'Incubation is about 8-11 days for P. falciparum and 8-17 days for P. vivax (longer for P. malariae). Early symptoms are nonspecific: fever, chills, headache, myalgia and malaise. Paroxysms may become periodic, though falciparum fever is often irregular. Untreated falciparum infection can progress rapidly to severe malaria. Vivax infection can relapse from hypnozoites unless radical cure is given.', 'Repeat blood smears to confirm parasite clearance, daily in hospitalized falciparum or knowlesi cases. If initial smears are negative but suspicion remains, smears are repeated every 12-24 hours for a total of 3 sets. Severe cases are monitored for glucose, hemoglobin, renal function, acid-base status and consciousness. After IV artesunate, weekly CBC and hemolysis markers are checked for up to 4 weeks for delayed hemolysis. Vivax patients are followed for relapse.', 'StatPearls: Malaria (2023); WHO fact sheet Malaria; CDC Treatment of Uncomplicated Malaria and Treatment of Severe Malaria (updated Aug 2026); Luchavez et al., Emerg Infect Dis 2008; DOH Malaria Control and Elimination Program; Harrison''s Principles of Internal Medicine, 21st ed.', true),
    ('community_acquired_pneumonia', 'Community-Acquired Pneumonia', 'Community-acquired pneumonia (CAP); lower respiratory tract infection of the lung parenchyma', 'Community-acquired pneumonia is an acute infection of the lung parenchyma acquired outside the hospital, confirmed by a new infiltrate on chest imaging in a patient with compatible respiratory symptoms. Streptococcus pneumoniae remains the leading bacterial cause, with Haemophilus influenzae, Staphylococcus aureus, atypical organisms (Mycoplasma, Chlamydia, Legionella) and respiratory viruses (influenza, SARS-CoV-2, rhinovirus) also important. Philippine guidelines (PSMID/PCP 2020) stratify adults into low-, moderate- and high-risk CAP to guide site of care and empiric antibiotics. The syndrome itself is not classed as contagious, although some causative pathogens (e.g., influenza, SARS-CoV-2) spread person to person.', (SELECT id FROM public.body_systems WHERE name = 'Respiratory System' ORDER BY id LIMIT 1), 'Moderate', 'SEEK_URGENT_CARE', 'Any suspected pneumonia warrants prompt same-day assessment and risk stratification. Respiratory rate >=30/min, heart rate >=125/min, SBP <90 or DBP <=60 mmHg, temperature <36 or >40 C, altered mental status or CURB-65 >=2 indicate hospital-level care; sepsis, septic shock or need for ventilatory support places the presentation in the EMERGENCY tier.', false, 'Pathogens colonizing the nasopharynx reach the lower airways mainly by microaspiration, less often by inhalation of aerosols or hematogenous spread. Pneumonia develops when the inoculum or virulence of the organism overwhelms local defenses such as mucociliary clearance, cough, alveolar macrophages and secretory immunity. Recruitment of neutrophils and release of inflammatory mediators (e.g., IL-1, TNF) fill the alveoli with exudate, producing consolidation. The resulting ventilation-perfusion mismatch and shunt cause hypoxemia, while the systemic inflammatory response produces fever and, in severe cases, sepsis and organ dysfunction.', 'Alveolar exudate and consolidation account for productive cough, crackles, bronchial breath sounds, dullness to percussion and the infiltrate on chest radiograph. Inflammation extending to the parietal pleura causes pleuritic chest pain, and parapneumonic effusion or empyema may follow. Hypoxemia from shunting drives tachypnea and dyspnea; systemic cytokine release explains fever, chills, tachycardia and, in older adults, confusion.', 'Typically acute, developing over hours to a few days, often after or during a viral upper respiratory infection. With appropriate therapy, fever and tachycardia usually settle within 48-72 hours, while cough, fatigue and radiographic changes can take several weeks to resolve. Deterioration within the first days may signal sepsis, empyema, lung abscess, necrotizing pneumonia or respiratory failure.', 'Vital signs, oxygen saturation and mental status are monitored closely, with clinical stability (afebrile >=48 hours, normal vital signs and oxygen saturation, tolerating oral intake, baseline mental status) reassessed at 48-72 hours to guide oral step-down and stopping antibiotics after a minimum course. Failure to improve prompts review for resistant organisms, complications (effusion, empyema, abscess) or alternative diagnoses such as tuberculosis. Routine repeat chest imaging during treatment is not needed in patients who are improving; PSMID 2020 addresses post-treatment imaging at 6-8 weeks in selected patients.', 'PSMID/PCP Philippine CPG on Adult CAP 2020; StatPearls (Regunath & Oba, 2024); ATS/IDSA CAP guideline 2019; ATS CAP guideline 2025; Harrison''s Principles of Internal Medicine 21st ed.', true),
    ('influenza', 'Influenza', 'Seasonal influenza (influenza A and B virus infection, family Orthomyxoviridae)', 'Influenza is an acute viral respiratory infection caused by influenza A and B viruses, characterized by abrupt fever, cough, headache, myalgia, sore throat and rhinorrhea. Most people recover within about a week without specific treatment, but it causes an estimated 290,000-650,000 respiratory deaths worldwide each year, concentrated in older adults, young children, pregnant women and people with chronic disease. In tropical countries such as the Philippines it circulates year-round with irregular outbreaks rather than a single winter season.', (SELECT id FROM public.body_systems WHERE name = 'Respiratory System' ORDER BY id LIMIT 1), 'Moderate', 'SELF_CARE', 'Uncomplicated influenza in healthy adults is usually self-limited and managed supportively. High-risk persons (age >=65, pregnancy, chronic cardiopulmonary, renal, metabolic disease, immunosuppression) move to SEE_DOCTOR_SOON because antivirals work best within 48 hours; dyspnea, chest pain, confusion, persistent dizziness or relapse of fever and cough move to SEEK_URGENT_CARE or EMERGENCY.', true, 'Influenza viruses bind sialic acid receptors on respiratory epithelium via hemagglutinin, enter the cell and replicate, with neuraminidase releasing new virions from the cell surface. Infection of the upper airway and trachea causes epithelial necrosis, loss of cilia and local inflammation. Cytokine release (interferons, IL-6, TNF) produces the prominent systemic features. Epithelial damage and impaired mucociliary clearance predispose to secondary bacterial pneumonia, and in severe cases viral infection of the lower respiratory tract causes primary viral pneumonia and ARDS. Frequent point mutations (antigenic drift) and, for influenza A, reassortment (antigenic shift) allow repeated infections and require annual vaccine updates.', 'Systemic cytokine release accounts for the abrupt high fever, chills, myalgia, headache and profound malaise that distinguish influenza from the common cold. Tracheobronchial epithelial injury produces a dry, persistent cough and substernal discomfort that may outlast the fever. Loss of mucociliary defenses explains the characteristic pattern of initial improvement followed by recurrent fever and productive cough when secondary bacterial pneumonia develops.', 'Incubation is about 2 days (range 1-4 days). Onset is abrupt, with fever and systemic symptoms dominating the first 3 days; most cases resolve in 3-7 days, although cough and fatigue may persist for more than 2 weeks, especially in older adults. Complications such as pneumonia usually appear within the first week. Transmission can begin before symptom onset and continues for roughly 5-7 days.', 'Respiratory rate, oxygen saturation and hydration are monitored, especially in high-risk patients. Failure to improve after 3-5 days of antiviral therapy, or recrudescence of fever with productive cough, prompts evaluation for bacterial coinfection (chest radiograph, cultures). Exacerbation of underlying heart failure, COPD, asthma or diabetes is watched for during and after the illness.', 'WHO fact sheet on seasonal influenza (2025); CDC Influenza Antiviral Medications: Summary for Clinicians; CDC Clinical Signs and Symptoms of Influenza; IDSA 2018 influenza guideline; StatPearls (Boktor & Hafner, 2023); Harrison''s 21st ed.', true),
    ('covid19', 'COVID-19', 'Coronavirus disease 2019 (SARS-CoV-2 infection, genus Betacoronavirus)', 'COVID-19 is an infectious disease caused by SARS-CoV-2, spread mainly through the air via infectious respiratory particles, especially in close contact and poorly ventilated indoor spaces. Illness ranges from asymptomatic infection and mild upper respiratory symptoms to pneumonia, ARDS, thromboembolic disease and multiorgan failure. Older age is the strongest risk factor for severe disease, and a proportion of patients develop post-COVID-19 condition with persistent fatigue and cognitive symptoms.', (SELECT id FROM public.body_systems WHERE name = 'Respiratory System' ORDER BY id LIMIT 1), 'Moderate', 'SELF_CARE', 'Most non-severe infections in vaccinated, low-risk adults are managed supportively. Adults at high risk of severe disease (older age, chronic disease, immunosuppression, pregnancy, unvaccinated) fall under SEE_DOCTOR_SOON because nirmatrelvir-ritonavir must start within 5 days of onset; dyspnea, low oxygen saturation, persistent chest pain, confusion or drowsiness place the presentation in the EMERGENCY tier.', true, 'The spike protein binds angiotensin-converting enzyme 2 (ACE2) on respiratory epithelium, and the host protease TMPRSS2 primes the spike to allow membrane fusion and cell entry. Early disease is driven by viral replication and direct cytopathic injury in the upper and lower airways. In severe disease a later dysregulated immune response with high levels of IL-6, TNF-alpha and other cytokines causes diffuse alveolar damage, increased vascular permeability and pulmonary edema. Endothelial injury and activation of coagulation create a hypercoagulable state that predisposes to venous and arterial thrombosis.', 'Viral replication in the upper airway and olfactory epithelium produces sore throat, rhinorrhea and loss of smell or taste. Alveolar injury and inflammatory exudate produce dyspnea, hypoxemia and bilateral ground-glass opacities, typically worsening in the second week when the host inflammatory phase dominates. The hypercoagulable state correlates with elevated D-dimer and complications such as pulmonary embolism, myocardial infarction and stroke.', 'Symptoms usually begin 3-6 days after exposure (StatPearls reports a median incubation of about 5 days for earlier variants; Omicron lineages have shorter incubation) and commonly last up to 10 days. A minority progress to hypoxemic pneumonia, usually about one week into the illness. Post-COVID-19 condition, with fatigue, breathlessness and memory problems persisting for months, develops in a subset of patients.', 'Symptom trajectory and oxygen saturation are monitored, particularly during days 5-10 when deterioration is most likely. Hospitalized patients are followed with oxygen requirements, inflammatory markers (CRP), D-dimer, renal and liver function and for thromboembolic complications. Patients with persistent symptoms beyond the acute phase are assessed for post-COVID-19 condition.', 'WHO COVID-19 fact sheet (2025); WHO Therapeutics and COVID-19 living guideline (2025); StatPearls (Cascella et al., 2023); Harrison''s 21st ed.', true),
    ('measles', 'Measles', 'Measles (rubeola); measles virus, genus Morbillivirus, family Paramyxoviridae', 'Measles is a highly contagious viral illness in which one case can generate up to 18 secondary infections among susceptible people. It presents with high fever and the ''3 Cs'' (cough, coryza, conjunctivitis), followed by Koplik spots and a maculopapular rash that spreads from the face downward. Complications include pneumonia, diarrhea, otitis media, encephalitis, blindness and the late, fatal subacute sclerosing panencephalitis (SSPE). The Philippines experienced a large outbreak in 2018-2019 linked to falling immunization coverage and vaccine hesitancy.', (SELECT id FROM public.body_systems WHERE name = 'Multisystem (Systemic Infection)' ORDER BY id LIMIT 1), 'Moderate', 'SEE_DOCTOR_SOON', 'Fever with rash plus cough, coryza or conjunctivitis warrants prompt clinical assessment for confirmation, vitamin A, isolation and public health notification, with advance notice to the facility to prevent waiting-room spread. Breathing difficulty, seizures, altered consciousness, dehydration, or illness in infants, pregnant women, malnourished or immunocompromised persons place it in SEEK_URGENT_CARE or EMERGENCY.', true, 'Measles virus enters through the respiratory tract and infects immune cells (lymphocytes and dendritic cells) that carry it to regional lymph nodes. Viremia disseminates the virus to the skin, respiratory tract, conjunctiva, gastrointestinal tract and other organs. The virus suppresses innate interferon responses during the prodrome, and infection depletes pre-existing memory lymphocytes (''immune amnesia''), leaving patients vulnerable to secondary infections for months. The rash coincides with the appearance of the cell-mediated immune response against infected endothelial cells in the skin.', 'Infection of respiratory and conjunctival epithelium explains the cough, coryza and conjunctivitis of the prodrome, while Koplik spots are an enanthem of the buccal mucosa. The immune-mediated attack on infected dermal capillary endothelium produces the maculopapular rash that appears as antibodies develop. Measles-induced immunosuppression explains the frequency of secondary bacterial pneumonia, otitis media and diarrhea, and vitamin A depletion links the infection to corneal damage and blindness in malnourished children.', 'Incubation is about 10-14 days (range 6-21 days). A 2-4 day prodrome of fever, cough, coryza and conjunctivitis is followed by Koplik spots 1-2 days before the rash. The rash appears around 14 days after exposure at the hairline and face, spreads down to the trunk and extremities over about 3 days and fades in the same order. Patients are infectious from 4 days before to 4 days after rash onset. SSPE can appear 7-10 years after the acute illness.', 'Hydration, nutrition, respiratory status and neurologic status are monitored during the acute illness, with attention to pneumonia, otitis media, diarrhea and encephalitis. Vitamin A is given as two doses 24 hours apart, with a third dose weeks later if there are eye signs of deficiency. Contacts are traced for post-exposure prophylaxis, and airborne isolation is maintained until 4 days after rash onset.', 'WHO measles fact sheet (2026); CDC Clinical Overview of Measles; StatPearls (Kondamudi et al., 2025); WHO Philippines measles outbreak Q&A (2019); Harrison''s 21st ed.', true),
    ('acute_gastroenteritis', 'Acute Infectious Gastroenteritis (Acute Diarrhea)', 'Acute infectious gastroenteritis / acute infectious diarrhea', 'Acute infectious gastroenteritis is inflammation of the stomach and intestines caused by viruses, bacteria or parasites, presenting as three or more loose or liquid stools per day, often with vomiting and abdominal cramps. Viruses, especially norovirus and in children rotavirus, cause most cases, while bacteria such as Salmonella, Campylobacter, Shigella, E. coli and Vibrio cholerae cause more severe or dysenteric illness. Spread is fecal-oral through contaminated water and food or person-to-person contact. Dehydration is the main complication, and diarrheal disease remains a leading cause of death in young children worldwide.', (SELECT id FROM public.body_systems WHERE name = 'Digestive System' ORDER BY id LIMIT 1), 'Mild', 'SELF_CARE', 'Acute watery diarrhea without dehydration is usually self-limited and managed with oral rehydration. Bloody or mucoid stools, fever, severe abdominal pain, persistent vomiting, age >65 or immunosuppression move to SEE_DOCTOR_SOON or SEEK_URGENT_CARE; severe dehydration (lethargy, sunken eyes, inability to drink, markedly reduced urine output, hypotension) or profuse rice-water stools suggesting cholera are EMERGENCY.', true, 'Enteric pathogens cause diarrhea by several mechanisms. Enterotoxin-producing organisms such as Vibrio cholerae and enterotoxigenic E. coli stimulate intestinal chloride and water secretion without damaging the mucosa, producing large-volume watery stools. Viruses such as rotavirus and norovirus injure small-intestinal villi, causing malabsorption and osmotic and secretory diarrhea. Invasive and cytotoxin-producing bacteria such as Shigella, Campylobacter and enteroinvasive E. coli invade the colonic epithelium, producing inflammation, ulceration and dysentery with blood and mucus. Shiga toxin-producing E. coli can damage endothelium systemically and cause hemolytic uremic syndrome.', 'Secretory, toxin-mediated disease produces profuse watery stools with little fever and rapid dehydration, while mucosal invasion produces fever, tenesmus, small-volume bloody or mucoid stools and abdominal tenderness. Volume and electrolyte losses explain thirst, dizziness, oliguria, tachycardia and, when severe, hypotension and altered sensorium. Norovirus and other small-bowel viral infections commonly present with prominent vomiting and cramping.', 'Incubation ranges from a few hours for preformed toxins to several days for invasive bacteria and parasites; cholera incubates 12 hours to 5 days. Viral gastroenteritis typically begins suddenly and resolves in 1-3 days in healthy adults. Bacterial diarrhea may last longer, and diarrhea persisting 14 days or more is classified as persistent and prompts evaluation for parasites and noninfectious causes.', 'Hydration status (thirst, mucous membranes, skin turgor, urine output, orthostatic vital signs, mental status) is reassessed during rehydration. Serum electrolytes and renal function are checked in severe dehydration. After bloody diarrhea, particularly with confirmed STEC, CBC, platelets and creatinine are monitored for hemolytic uremic syndrome; persistent symptoms prompt stool studies.', 'WHO diarrhoeal disease fact sheet (2024); WHO cholera fact sheet (2024); IDSA 2017 infectious diarrhea guideline; StatPearls Viral Gastroenteritis (2025) and Bacterial Gastroenteritis (archived, 2023); Harrison''s 21st ed.', true),
    ('urinary_tract_infection', 'Urinary Tract Infection (Cystitis / Pyelonephritis)', 'Acute bacterial cystitis (lower UTI) / acute pyelonephritis (upper UTI)', 'Urinary tract infection (UTI) is bacterial infection of the urinary tract, ranging from infection of the bladder (cystitis, lower UTI) to infection of the renal pelvis and parenchyma (pyelonephritis, upper UTI). It is classified as uncomplicated when it occurs in patients without structural urinary tract abnormalities or significant comorbidity, and complicated otherwise (e.g., catheters, obstruction, diabetes, pregnancy, male sex in many classifications). Escherichia coli causes most community-acquired UTIs. UTI is one of the most common bacterial infections in adult women.', (SELECT id FROM public.body_systems WHERE name = 'Urinary System' ORDER BY id LIMIT 1), 'Moderate', 'SEE_DOCTOR_SOON', 'Lower-tract symptoms (dysuria, frequency, urgency, suprapubic discomfort) without fever correspond to SEE_DOCTOR_SOON. Fever, chills, flank pain or costovertebral angle tenderness, or vomiting suggest pyelonephritis (SEEK_URGENT_CARE), while hypotension, confusion or other signs of sepsis place the presentation in the EMERGENCY tier.', false, 'Most UTIs arise by ascending infection: uropathogens from the bowel flora colonize the periurethral area and ascend the urethra into the bladder. Uropathogenic E. coli adhere to uroepithelium via fimbriae (adhesins), which allows the organisms to resist clearance by urine flow. Invasion of the bladder mucosa provokes an acute inflammatory response with neutrophil recruitment, producing pyuria and irritative voiding symptoms. Ascent through the ureters to the renal pelvis and parenchyma produces pyelonephritis with systemic inflammation, and bacteria may enter the bloodstream (urosepsis). Host factors that impair urine flow or bladder emptying (obstruction, stones, catheters, incomplete voiding) increase susceptibility.', 'Inflammation of the bladder and urethral mucosa explains dysuria, frequency, urgency and suprapubic discomfort, and mucosal injury accounts for hematuria. Neutrophil influx is detected as pyuria and leukocyte esterase, while nitrate reduction by Enterobacterales produces a positive nitrite test. Renal parenchymal infection causes flank pain and costovertebral angle tenderness, and the systemic cytokine response produces fever, chills, nausea and vomiting.', 'Cystitis typically develops over hours to a day or two with dysuria and frequency. Pyelonephritis may follow cystitis symptoms or present directly with fever, flank pain and nausea over one to several days. With appropriate antibiotics, symptoms usually improve within about 48 hours; untreated or complicated upper-tract infection may progress to renal abscess, emphysematous pyelonephritis, acute kidney injury or sepsis.', 'Clinical response is expected within about 48 hours of antibiotic therapy; persistence or worsening prompts urine culture review and reassessment for pyelonephritis, resistant organisms or complicating factors. Outpatient pyelonephritis is re-evaluated within 24-48 hours. Imaging (ultrasound or CT) is considered when there is no improvement, suspected obstruction or abscess. Recurrent UTI (commonly defined as 2 or more in 6 months or 3 or more in 12 months) prompts evaluation of risk factors and preventive strategies.', 'StatPearls (Uncomplicated Urinary Tract Infections; Acute Pyelonephritis), NICE NG109, CDC Clinical Overview of UTIs, Harrison''s Principles of Internal Medicine', true),
    ('peptic_ulcer_disease', 'Peptic Ulcer Disease', 'Peptic ulcer (gastric ulcer and duodenal ulcer)', 'Peptic ulcer disease (PUD) is a break in the gastric or duodenal mucosa that extends through the muscularis mucosae. The two dominant causes are Helicobacter pylori infection and nonsteroidal anti-inflammatory drug (NSAID) use, including low-dose aspirin. It typically presents with dull or burning epigastric pain, but may be silent until a complication such as bleeding or perforation occurs. Eradication of H. pylori and withdrawal of NSAIDs markedly reduce recurrence.', (SELECT id FROM public.body_systems WHERE name = 'Digestive System' ORDER BY id LIMIT 1), 'Moderate', 'SEE_DOCTOR_SOON', 'Uncomplicated dyspepsia or epigastric pain corresponds to SEE_DOCTOR_SOON, with alarm features (unintentional weight loss, progressive dysphagia, persistent vomiting, iron-deficiency anemia) warranting prompt endoscopic evaluation. Hematemesis, melena, syncope, tachycardia or sudden severe abdominal pain (possible bleeding or perforation) place the presentation in the EMERGENCY tier.', false, 'Ulcers result from an imbalance between aggressive factors (gastric acid, pepsin) and mucosal defenses (mucus-bicarbonate layer, prostaglandins, mucosal blood flow, epithelial renewal). H. pylori colonizes the gastric mucosa and causes chronic active gastritis; antral-predominant infection can increase gastrin and acid output and impair duodenal bicarbonate secretion, favoring duodenal ulcers. NSAIDs inhibit cyclooxygenase-1-dependent prostaglandin synthesis, reducing mucus, bicarbonate and mucosal blood flow, in addition to causing direct topical injury. Less common causes include acid hypersecretion (Zollinger-Ellison syndrome), other ulcerogenic drugs and severe physiological stress. Deep ulcers can erode vessels (bleeding), penetrate the full wall (perforation) or cause scarring and edema at the pylorus (gastric outlet obstruction).', 'Acid contact with the ulcer base produces burning epigastric pain; duodenal ulcer pain classically occurs 2-3 hours after meals and at night, whereas gastric ulcer pain may be provoked by eating. Erosion into a submucosal artery produces hematemesis or melena and, with significant blood loss, dizziness and tachycardia, while chronic occult loss causes iron-deficiency anemia and fatigue. Full-thickness perforation releases gastric contents into the peritoneum, producing sudden severe generalized abdominal pain and peritonitis; pyloric scarring causes early satiety and vomiting.', 'Symptoms are usually chronic or recurrent over weeks to months, often episodic with symptom-free intervals. NSAID-associated ulcers are frequently painless and may present first with bleeding. Without removal of the cause, ulcers tend to recur; complications (bleeding, perforation, obstruction) can occur abruptly at any stage.', 'Confirmation of H. pylori eradication is recommended in all treated patients, using urea breath test, stool antigen or biopsy performed at least 4 weeks after completion of antibiotics and after proton pump inhibitors have been held for at least 2 weeks (ACG 2024). Symptoms, need for ongoing NSAID or antiplatelet therapy, and hemoglobin in bleeding ulcers are reviewed. Selected gastric ulcers undergo repeat endoscopy to document healing and exclude malignancy.', 'StatPearls (Peptic Ulcer Disease), ACG Clinical Guideline on Treatment of H. pylori (2024), NIDDK, Sleisenger and Fordtran''s Gastrointestinal and Liver Disease', true),
    ('hypertension', 'Essential Hypertension', 'Primary (essential) arterial hypertension', 'Essential (primary) hypertension is persistently elevated arterial blood pressure without an identifiable secondary cause, accounting for the large majority of hypertension cases. WHO and the 2020 Philippine guidelines define hypertension as office blood pressure of 140/90 mm Hg or higher on repeated measurement, while the ACC/AHA uses 130/80 mm Hg. Most cases are asymptomatic and detected incidentally, so symptom-based recognition is unreliable; headache, dizziness or blurred vision occur mainly with severe elevation. It is a major modifiable risk factor for stroke, coronary heart disease, heart failure and chronic kidney disease.', (SELECT id FROM public.body_systems WHERE name = 'Cardiovascular System' ORDER BY id LIMIT 1), 'Moderate', 'SEE_DOCTOR_SOON', 'Elevated readings without symptoms correspond to SEE_DOCTOR_SOON for confirmation and management. Severe elevation (typically above 180/120 mm Hg) with symptoms of acute target-organ injury (chest pain, dyspnea, neurological deficit, confusion, visual disturbance) indicates a hypertensive emergency and places the presentation in the EMERGENCY tier.', false, 'Essential hypertension is multifactorial, arising from interaction of genetic susceptibility with environmental factors such as high sodium intake, obesity and physical inactivity. Increased renal sodium retention expands intravascular volume, while inappropriate activity of the renin-angiotensin-aldosterone system promotes vasoconstriction and further sodium retention. Heightened sympathetic nervous system activity raises heart rate, cardiac output and vascular tone. Over time, vascular remodeling and endothelial dysfunction increase total peripheral resistance, which sustains the elevated pressure. Chronic pressure load causes target-organ damage including left ventricular hypertrophy, arteriolosclerosis, nephrosclerosis and retinopathy.', 'Because the pressure rise is gradual and autoregulation adapts, most patients have no symptoms until target organs are damaged. Increased afterload leads to left ventricular hypertrophy (detected on ECG or echocardiography) and eventually heart failure, while arteriolar injury produces retinopathy, albuminuria and declining eGFR. Abrupt severe elevation can overwhelm cerebral autoregulation (encephalopathy with headache, confusion and visual disturbance) or precipitate acute pulmonary edema and myocardial ischemia.', 'Typically develops gradually in mid to later adulthood, with prevalence rising steeply with age. It is a lifelong condition that is controlled rather than cured; untreated, it progressively damages the heart, brain, kidneys and retina over years, and acute hypertensive crises may occur at any stage.', 'Diagnosis is confirmed by repeated office readings on separate occasions, ideally supplemented by home or ambulatory monitoring. After starting or changing therapy, blood pressure is reassessed at intervals (response to a regimen is typically judged over several weeks) until target is reached, then periodically. Electrolytes and creatinine/eGFR are checked after initiating RAAS blockers or diuretics, and target-organ status (urine albumin, ECG, lipids, glucose) is reviewed periodically.', 'StatPearls (Essential Hypertension; Antihypertensive Medications; Hypertensive Crisis), WHO Hypertension fact sheet, 2020 Philippine Clinical Practice Guidelines for Hypertension, Harrison''s Principles of Internal Medicine', true),
    ('type2_diabetes', 'Type 2 Diabetes Mellitus', 'Diabetes mellitus type 2', 'Type 2 diabetes mellitus is a chronic metabolic disorder of hyperglycemia caused by insulin resistance combined with progressive pancreatic beta-cell dysfunction. It is the most common form of diabetes (over 90% of cases) and is strongly associated with overweight, physical inactivity and family history. It often develops silently over years and may be diagnosed on screening or after complications appear. Long-term hyperglycemia damages small and large blood vessels, causing retinopathy, nephropathy, neuropathy and cardiovascular disease.', (SELECT id FROM public.body_systems WHERE name = 'Endocrine System' ORDER BY id LIMIT 1), 'Moderate', 'SEE_DOCTOR_SOON', 'Symptomatic hyperglycemia (polyuria, polydipsia, weight loss) or abnormal screening glucose corresponds to SEE_DOCTOR_SOON. Confusion, drowsiness, severe dehydration, persistent vomiting, rapid breathing or very high glucose (possible hyperosmolar hyperglycemic state or ketoacidosis), or severe hypoglycemia on treatment place the presentation in the EMERGENCY tier.', false, 'Insulin resistance in muscle, liver and adipose tissue reduces peripheral glucose uptake and fails to suppress hepatic glucose production. Beta cells initially compensate by increasing insulin secretion, but progressive beta-cell dysfunction and loss lead to relative insulin deficiency and overt hyperglycemia. Contributing mechanisms include adipose tissue inflammation and increased free fatty acids, reduced incretin (GLP-1) effect, dysregulated glucagon secretion and increased renal glucose reabsorption. Residual insulin secretion usually suppresses ketogenesis, so ketoacidosis is less common than in type 1 diabetes, but marked hyperglycemia can cause a hyperosmolar hyperglycemic state. Chronic hyperglycemia drives microvascular and macrovascular injury.', 'When blood glucose exceeds the renal threshold, glycosuria causes osmotic diuresis (polyuria) and consequent dehydration and thirst (polydipsia). Loss of glucose calories and catabolism can produce weight loss and fatigue, and osmotic changes in the lens cause fluctuating blurred vision. Hyperglycemia impairs immune function and wound healing, increasing infections such as UTI and candidiasis. Severe hyperosmolality leads to confusion and reduced consciousness in the hyperosmolar hyperglycemic state.', 'Insidious onset, typically in adulthood, often preceded by years of prediabetes; many patients are asymptomatic at diagnosis. The disease is progressive, with declining beta-cell function commonly requiring intensification of therapy over time. Microvascular and macrovascular complications accumulate with duration and degree of hyperglycemia.', 'HbA1c every 3-6 months (at least twice yearly when at target, more often after therapy changes). Blood pressure at each visit; lipid profile periodically. Urine albumin-to-creatinine ratio and eGFR at least annually. Dilated retinal examination at diagnosis and periodically thereafter, and comprehensive foot examination at least annually. Self-monitoring of glucose is used especially with insulin or sulfonylurea therapy.', 'StatPearls (Type 2 Diabetes), WHO Diabetes fact sheet, CDC Type 2 Diabetes, ADA Standards of Care in Diabetes 2026, Williams Textbook of Endocrinology', true),
    ('asthma', 'Bronchial Asthma', 'Asthma bronchiale', 'Asthma is a chronic inflammatory disease of the airways characterized by variable, often reversible expiratory airflow limitation and bronchial hyperresponsiveness. It presents with episodic wheeze, shortness of breath, chest tightness and cough that vary over time and in intensity, often worse at night, with exercise or with viral infections. It affects all ages, cannot be cured, but is well controlled in most people with inhaled corticosteroid-containing treatment. Severe exacerbations can be fatal.', (SELECT id FROM public.body_systems WHERE name = 'Respiratory System' ORDER BY id LIMIT 1), 'Moderate', 'SEE_DOCTOR_SOON', 'Intermittent wheeze, cough or chest tightness responding to reliever therapy corresponds to SEE_DOCTOR_SOON for diagnosis and controller therapy. An exacerbation with inability to speak in full sentences, respiratory rate above 30/min, heart rate above 120/min, SpO2 below 90%, PEF 50% of predicted or less, drowsiness, confusion or a silent chest places the presentation in the EMERGENCY tier.', false, 'In type 2 (allergic/eosinophilic) asthma, allergen exposure in sensitized individuals triggers IgE-mediated mast cell degranulation with release of histamine, leukotrienes and other mediators, causing early-phase bronchoconstriction. Th2 lymphocytes produce IL-4, IL-5 and IL-13, which promote IgE synthesis, eosinophil recruitment and survival, and mucus hypersecretion, driving the late-phase inflammatory response. Airway hyperresponsiveness results from increased smooth muscle mass and contractility, mediator release and neural mechanisms, so that non-specific triggers (cold air, exercise, smoke) provoke bronchoconstriction. Chronic inflammation leads to airway remodeling with basement membrane thickening, smooth muscle hypertrophy and subepithelial fibrosis, which can cause fixed airflow obstruction. Non-type 2 (T2-low) phenotypes also exist, with neutrophilic or paucigranulocytic inflammation.', 'Bronchial smooth muscle constriction, mucosal edema and mucus plugging narrow the airways, producing expiratory wheeze, dyspnea and chest tightness, with reduced FEV1 and FEV1/FVC on spirometry. Reversibility of this narrowing with a bronchodilator (an FEV1 increase of 12% or more and 200 mL or more) reflects its largely functional basis. Circadian variation in airway tone and inflammation explains nocturnal cough and symptoms. In severe exacerbations, airflow becomes so limited that breath sounds diminish (silent chest) and hypoxemia and hypercapnia produce drowsiness or confusion.', 'Often begins in childhood but can start at any age, including adult-onset and occupational asthma. The course is variable, with periods of good control interrupted by exacerbations commonly triggered by viral respiratory infections, allergens, smoke, pollution or poor adherence to controller therapy. Poorly controlled long-standing asthma may progress to persistent airflow limitation due to remodeling.', 'Review 1-3 months after starting treatment and then every 3-12 months, assessing symptom control, exacerbation risk factors, lung function (spirometry or PEF), inhaler technique, adherence and side effects (GINA). After an exacerbation, follow-up within 2-7 days for adults and adolescents. Every patient should have a written asthma action plan; treatment is stepped up or down according to control.', 'GINA 2025 Summary Guide, StatPearls (Asthma; Pathophysiology of Asthma), WHO Asthma fact sheet, Harrison''s Principles of Internal Medicine', true),
    ('copd', 'Chronic Obstructive Pulmonary Disease', 'Chronic obstructive pulmonary disease (emphysema and chronic bronchitis phenotypes)', 'COPD is a common, preventable and treatable lung disease characterized by persistent and usually progressive airflow limitation caused by small airway disease (obstructive bronchiolitis) and emphysema. It presents with chronic dyspnea, cough and sputum and is punctuated by acute exacerbations. WHO ranks COPD as the third leading cause of death worldwide, with most deaths in low- and middle-income countries where household air pollution from biomass fuel is an important cause alongside tobacco smoking.', (SELECT id FROM public.body_systems WHERE name = 'Respiratory System' ORDER BY id LIMIT 1), 'Severe', 'SEE_DOCTOR_SOON', 'Stable disease with progressive exertional dyspnea and chronic cough warrants scheduled evaluation with spirometry. An acute exacerbation with dyspnea at rest, cyanosis, falling oxygen saturation, confusion or drowsiness (possible hypercapnia), or use of accessory muscles is reference EMERGENCY.', false, 'Chronic inhalation of noxious particles and gases (mainly tobacco smoke, biomass fuel smoke and occupational dusts) triggers a dysregulated inflammatory response with recruitment of neutrophils, macrophages and lymphocytes. These cells release proteases and cytokines that destroy alveolar walls (emphysema) and cause inflammation, fibrosis and mucus plugging of small airways (chronic bronchiolitis). Loss of elastic recoil and airway narrowing produce expiratory airflow limitation, air trapping and dynamic hyperinflation. Ventilation-perfusion mismatch impairs gas exchange, leading to hypoxemia and, in advanced disease, hypercapnia. Chronic hypoxic pulmonary vasoconstriction can cause pulmonary hypertension and right heart failure (cor pulmonale). Alpha-1 antitrypsin deficiency is an inherited host factor that increases protease-mediated lung destruction.', 'Expiratory airflow limitation and air trapping explain exertional dyspnea, wheeze, prolonged expiration and the barrel-shaped, hyperresonant chest with diminished breath sounds. Mucus gland hypertrophy and goblet cell hyperplasia account for chronic productive cough. Chronic hypoxemia can produce secondary polycythemia and, via pulmonary hypertension, peripheral edema from right heart failure.', 'Insidious onset, usually after age 40 with a long exposure history; breathlessness typically develops gradually and is initially noticed only on exertion. The course is chronic and progressive, with episodic acute exacerbations (often triggered by respiratory infections) that accelerate decline and carry significant mortality.', 'Periodic review of symptom burden (e.g., mMRC or CAT scores), exacerbation frequency, inhaler technique and adherence, smoking status, and oxygen saturation. Spirometry is repeated periodically to track decline; blood eosinophil count informs inhaled corticosteroid decisions. Arterial blood gases are assessed when long-term oxygen is considered (PaO2 at or below 55 mmHg or SpO2 at or below 88%). Early review follows any hospitalized exacerbation.', 'StatPearls: Chronic Obstructive Pulmonary Disease (Kanchustambham & Brown, 2026); WHO COPD fact sheet (2026); GOLD Global Strategy report; NICE NG114; Cochrane review CD003566; Harrison''s Principles of Internal Medicine, 21st ed.', true),
    ('acute_coronary_syndrome', 'Acute Coronary Syndrome (incl. Myocardial Infarction)', 'Acute coronary syndrome (ST-elevation myocardial infarction, non-ST-elevation myocardial infarction, unstable angina)', 'Acute coronary syndrome (ACS) is the spectrum of acute myocardial ischemia comprising ST-elevation myocardial infarction (STEMI), non-ST-elevation myocardial infarction (NSTEMI) and unstable angina. NSTEMI is distinguished from unstable angina by elevated cardiac troponin indicating myocardial necrosis. Ischemic heart disease caused about 9 million deaths worldwide in 2021, roughly 13% of all deaths, and rapid reperfusion is the key determinant of outcome in STEMI.', (SELECT id FROM public.body_systems WHERE name = 'Cardiovascular System' ORDER BY id LIMIT 1), 'Critical', 'EMERGENCY', 'Any suspected acute coronary syndrome is reference EMERGENCY: substernal chest pressure lasting 10 minutes or more, especially with radiation to the arm, jaw or neck, diaphoresis, dyspnea, nausea or lightheadedness, requires an ECG within 10 minutes of first medical contact. Atypical presentations (isolated dyspnea, epigastric pain, fatigue) in women, older adults and people with diabetes carry the same urgency.', false, 'Most ACS (type 1 MI) results from rupture or erosion of an atherosclerotic coronary plaque, which exposes thrombogenic material and triggers platelet aggregation and thrombus formation. Complete, persistent occlusion of an epicardial artery produces transmural ischemia and ST elevation (STEMI), whereas partial or intermittent occlusion causes subendocardial ischemia (NSTEMI or unstable angina). Ischemia progresses from reversible dysfunction to myocyte necrosis within minutes to hours, spreading from subendocardium to epicardium. Type 2 MI reflects oxygen supply-demand mismatch (e.g., tachyarrhythmia, anemia, hypotension) without plaque rupture. Non-atherosclerotic causes include coronary vasospasm, spontaneous coronary artery dissection and coronary embolism.', 'Myocardial ischemia stimulates cardiac visceral afferents, producing poorly localized substernal pressure referred to the arm, jaw or neck. Sympathetic activation causes diaphoresis, pallor and tachycardia, and vagal stimulation (notably in inferior infarction) causes nausea and bradycardia. Ischemic left ventricular dysfunction raises filling pressures and causes dyspnea and pulmonary crackles; necrosis releases troponin, and electrical instability produces arrhythmias.', 'Sudden onset of chest discomfort, often at rest or with minimal exertion, lasting 10 minutes or more and not relieved by rest; it may follow a period of crescendo angina. Without reperfusion, infarct size increases over hours, and early complications include ventricular arrhythmias, heart failure, cardiogenic shock and, later, mechanical complications.', 'Continuous ECG monitoring for arrhythmias and serial high-sensitivity troponin in the acute phase; echocardiography to assess left ventricular ejection fraction and mechanical complications. After discharge, monitoring covers adherence to dual antiplatelet therapy and bleeding, lipid panel reassessment weeks after statin initiation, blood pressure, glycemic control, renal function and potassium on RAAS inhibitors, and participation in cardiac rehabilitation.', 'StatPearls: Acute Coronary Syndrome (Jain et al., 2026); 2025 ACC/AHA/ACEP/NAEMSP/SCAI ACS Guideline (Circulation 2025); WHO Heart attack fact sheet (2026); Harrison''s Principles of Internal Medicine, 21st ed.', true),
    ('heart_failure', 'Heart Failure', 'Heart failure (HFrEF, HFmrEF, HFpEF; congestive heart failure)', 'Heart failure is a complex clinical syndrome resulting from any structural or functional impairment of ventricular filling or ejection of blood. It is classified by left ventricular ejection fraction into HF with reduced (40% or less), mildly reduced (41-49%) and preserved (50% or more) ejection fraction, and staged A to D by the ACC/AHA. It affects roughly 26 million people worldwide and carries high rates of hospitalization and mortality.', (SELECT id FROM public.body_systems WHERE name = 'Cardiovascular System' ORDER BY id LIMIT 1), 'Severe', 'SEEK_URGENT_CARE', 'New or worsening dyspnea, orthopnea, edema or rapid weight gain warrants urgent evaluation. Breathlessness at rest, pink frothy sputum, hypoxemia, chest pain, syncope, hypotension or signs of poor perfusion (cold extremities, confusion, oliguria) indicate acute decompensation or cardiogenic shock and are reference EMERGENCY.', false, 'An initial myocardial insult (ischemia, pressure or volume overload, cardiomyopathy) reduces cardiac output or raises filling pressures. Compensatory activation of the sympathetic nervous system and renin-angiotensin-aldosterone system initially maintains perfusion but, when sustained, causes sodium and water retention, vasoconstriction, myocyte hypertrophy, apoptosis, fibrosis and progressive ventricular remodeling. Natriuretic peptide counter-regulation becomes insufficient. Elevated left-sided filling pressures cause pulmonary congestion, while right-sided failure produces systemic venous congestion, and reduced renal perfusion contributes to cardiorenal dysfunction. Guideline-directed therapies act by blocking these neurohormonal pathways.', 'Raised pulmonary venous pressure causes exertional dyspnea, orthopnea, paroxysmal nocturnal dyspnea and basal crackles. Systemic venous congestion produces jugular venous distension, hepatojugular reflux, hepatic congestion, anorexia and dependent edema. Reduced forward output and neurohormonal activation cause fatigue, tachycardia, cool extremities and diaphoresis, and an S3 gallop reflects rapid ventricular filling into a noncompliant, volume-overloaded ventricle.', 'Chronic heart failure typically develops gradually with progressive exertional intolerance, punctuated by episodes of acute decompensation (often triggered by ischemia, arrhythmia, infection, uncontrolled hypertension, nonadherence or sodium-retaining drugs). Acute de novo heart failure can follow myocardial infarction or myocarditis. The course is generally progressive, with 5-year mortality around 40% after diagnosis.', 'Symptoms and NYHA class, daily body weight, blood pressure, heart rate and volume status at each visit. Serum electrolytes (especially potassium) and renal function after starting or up-titrating ACE inhibitor/ARB/ARNI, MRA, SGLT2 inhibitor or diuretics. Natriuretic peptides for prognosis and assessment; repeat echocardiography after optimization of guideline-directed therapy to reassess LVEF and eligibility for ICD or CRT. Early follow-up (within about 1-2 weeks) after a hospitalization.', 'StatPearls: Heart Failure (Congestive Heart Failure) (Shams, Malik, Chhabra, 2025); 2022 AHA/ACC/HFSA Guideline for the Management of Heart Failure; Harrison''s Principles of Internal Medicine, 21st ed.', true),
    ('ischemic_stroke', 'Acute Ischemic Stroke', 'Cerebral infarction (acute ischemic stroke)', 'Acute ischemic stroke is the sudden onset of a focal neurological deficit in a vascular territory of the brain, retina or spinal cord caused by arterial occlusion and infarction. It accounts for the majority of strokes and is a leading cause of death and long-term disability. Outcomes depend on how quickly blood flow is restored, summarized by the principle that time is brain.', (SELECT id FROM public.body_systems WHERE name = 'Nervous System' ORDER BY id LIMIT 1), 'Critical', 'EMERGENCY', 'Any sudden focal neurological deficit (facial droop, arm or leg weakness, speech disturbance, vision loss, imbalance) is reference EMERGENCY because thrombolysis and thrombectomy are time-dependent; the time last known well determines eligibility. Transient deficits that resolve (possible TIA) carry the same urgency because of high early stroke risk.', false, 'Occlusion of a cerebral artery by in-situ thrombosis on atherosclerotic plaque, embolism from the heart or a proximal artery, or small penetrating-artery disease abruptly reduces regional cerebral blood flow. Where flow falls below roughly 10-12 mL/100 g/min, energy failure causes rapid irreversible necrosis (the infarct core). Surrounding hypoperfused but still viable tissue (the ischemic penumbra) can be salvaged by timely reperfusion. Energy failure triggers excitotoxic glutamate release, calcium influx, free-radical injury and cytotoxic edema. The TOAST classification divides causes into large-artery atherosclerosis, cardioembolism, small-vessel (lacunar) occlusion, and other or undetermined etiology.', 'Deficits map to the affected vascular territory: middle cerebral artery infarction causes contralateral face and arm weakness and sensory loss with aphasia (dominant hemisphere) or neglect (nondominant). Posterior circulation infarction causes vertigo, ataxia, diplopia, visual field loss and crossed signs, while lacunar infarcts produce pure motor or pure sensory syndromes without cortical signs. Cerebral edema peaking at 3-5 days can cause deterioration in consciousness.', 'Sudden onset, often maximal at onset or evolving over minutes to hours; symptoms may be noticed on waking. Neurological status can fluctuate or worsen in the first days from infarct extension, hemorrhagic transformation or edema, followed by variable recovery over weeks to months with rehabilitation.', 'Serial NIHSS neurological assessments, blood pressure (at or below 180/105 mmHg for 24 hours after thrombolysis), glucose (140-180 mg/dL), temperature and swallow screening in the acute phase; follow-up brain imaging after reperfusion therapy. Long-term follow-up covers blood pressure, lipid and glucose control, adherence to antithrombotic therapy, cardiac rhythm monitoring for occult atrial fibrillation, screening for post-stroke depression, and rehabilitation progress.', 'StatPearls: Ischemic Stroke (Lui, Khan Suheb, Patti, 2026); 2026 AHA/ASA Guideline for the Early Management of Patients With Acute Ischemic Stroke; Harrison''s Principles of Internal Medicine, 21st ed.', true),
    ('migraine', 'Migraine', 'Migraine (with or without aura)', 'Migraine is a common, genetically influenced primary headache disorder characterized by recurrent attacks of moderate-to-severe, often unilateral, pulsating headache lasting 4-72 hours, accompanied by nausea and/or photophobia and phonophobia. About a quarter of patients experience transient focal neurological aura. Migraine affects women more than men and is among the leading causes of disability worldwide.', (SELECT id FROM public.body_systems WHERE name = 'Nervous System' ORDER BY id LIMIT 1), 'Moderate', 'SEE_DOCTOR_SOON', 'Recurrent headaches fitting the typical migraine pattern warrant scheduled evaluation for diagnosis and management. Red flags make the presentation reference EMERGENCY: sudden thunderclap or worst-ever headache, new focal deficits or aura lasting more than 60 minutes, fever with neck stiffness, confusion, new headache after age 50 or in immunosuppression, or an attack persisting beyond 72 hours.', false, 'Migraine reflects a hyperexcitable brain with abnormal sensory processing. Aura is attributed to cortical spreading depression, a slowly propagating wave of neuronal and glial depolarization followed by suppressed activity. Activation of the trigeminovascular system releases vasoactive neuropeptides, principally calcitonin gene-related peptide (CGRP), substance P and serotonin-related mediators, producing neurogenic inflammation of meningeal vessels. Peripheral and then central sensitization of trigeminal pathways amplify pain and cause allodynia. Hypothalamic and brainstem involvement is thought to underlie the premonitory phase.', 'Spreading depression over the occipital cortex produces the characteristic visual aura that expands over minutes. Sensitized trigeminovascular afferents explain pulsating pain worsened by routine physical activity, while central sensitization produces photophobia, phonophobia and cutaneous allodynia. Brainstem and hypothalamic activation account for nausea, vomiting, yawning and mood change.', 'Usually begins in adolescence or early adulthood, with peak prevalence in the fourth decade. Attacks may progress through prodrome (hours to 1-2 days), aura (5-60 minutes), headache (4-72 hours untreated) and postdrome. Frequency varies; episodic migraine can transform into chronic migraine, and frequent use of acute medication can lead to medication-overuse headache.', 'Headache diary recording attack frequency, severity, triggers, disability and acute-medication days per month. Monitoring for medication overuse (triptans on 10 or more days per month, simple analgesics on 15 or more days per month). Response to preventive therapy is typically assessed after a trial of about 2-3 months; blood pressure and heart rate are monitored on beta-blocker prophylaxis.', 'StatPearls: Migraine Headache (Pescador Ruschel & De Jesus, 2024); StatPearls: Migraine Medications (Lew & Punnapuzha, 2023); ICHD-3 (International Headache Society); WHO Migraine and other headache disorders fact sheet (2025); Harrison''s Principles of Internal Medicine, 21st ed.', true),
    ('chikungunya', 'Chikungunya', 'Chikungunya virus (CHIKV) infection', 'Chikungunya is an acute mosquito-borne viral illness caused by chikungunya virus, an alphavirus transmitted mainly by Aedes aegypti and Aedes albopictus, the same vectors that spread dengue. It is characterized by abrupt fever and debilitating, usually symmetric polyarthralgia. Most patients recover fully, but joint pain can persist for weeks, months or years. Deaths are rare. In the Philippines, DOH surveillance reported 2,928 cases and no deaths in 2023 up to early December, with cases rising during the rainy season.', (SELECT id FROM public.body_systems WHERE name = 'Multisystem (Systemic Infection)' ORDER BY id LIMIT 1), 'Moderate', 'SEE_DOCTOR_SOON', 'Acute fever with severe joint pain compatible with chikungunya warrants prompt clinical review with laboratory testing, largely because dengue must be excluded before NSAIDs are used. Neurologic signs, chest pain or breathlessness suggesting myocarditis, visual symptoms, dengue warning signs (bleeding, severe abdominal pain, persistent vomiting) or illness in a newborn exposed around delivery place the presentation in a higher urgency tier.', false, 'After inoculation by an infected Aedes mosquito, the virus replicates in epithelial cells, fibroblasts and monocyte-derived macrophages, producing high-level viremia and an intense inflammatory response. The virus reaches joint and muscle tissue, where persistent infection of monocyte-derived macrophages is hypothesized to underlie chronic arthritis and polyarthralgia.', 'Inflammation of joints and periarticular tissues produces severe bilateral, symmetric polyarthralgia favoring distal joints (hands, wrists, ankles, knees), often with joint swelling. A maculopapular rash typically appears around day 3 of fever. Lymphopenia and mild thrombocytopenia may be seen, but marked thrombocytopenia and bleeding point more toward dengue.', 'Incubation is typically 3-7 days (WHO: onset usually 4-8 days after the infective bite). The acute phase begins with sudden high fever, severe polyarthralgia and myalgia, followed by rash, and usually lasts 1-3 weeks. A chronic phase with persistent or relapsing rheumatic symptoms is reported in 26-40% of confirmed cases at 3-6 months. Older adults and people with preexisting joint disease have greater morbidity, and newborns infected around delivery are at risk of severe disease.', 'Clinical review of fever, hydration and joint symptoms during the acute phase, with CBC and dengue testing until dengue is excluded. Patients with joint symptoms persisting beyond the acute phase are reassessed for chronic inflammatory arthritis, which may need rheumatology follow-up. New neurologic, cardiac or ocular symptoms prompt specialist evaluation.', 'StatPearls: Chikungunya Fever (2026); WHO fact sheet Chikungunya (2025); DOH surveillance via Philippine News Agency (2023); Harrison''s Principles of Internal Medicine, 21st ed.', true),
    ('hepatitis_b', 'Hepatitis B (Acute and Chronic)', 'Hepatitis B virus (HBV) infection', 'Hepatitis B is a liver infection caused by hepatitis B virus, a blood-borne DNA virus transmitted perinatally, through blood exposure and through sexual contact. Acute infection is often asymptomatic; symptomatic cases present with jaundice, dark urine, fatigue, nausea and abdominal pain. The risk of chronic infection depends strongly on age at infection: about 90-95% of infants infected at birth become chronically infected, compared with fewer than 5% of adults. Chronic infection can progress to cirrhosis and hepatocellular carcinoma. The WHO Western Pacific Region carries the highest burden, and WHO has estimated about 7.3 million Filipinos live with chronic hepatitis B.', (SELECT id FROM public.body_systems WHERE name = 'Digestive System' ORDER BY id LIMIT 1), 'Severe', 'SEE_DOCTOR_SOON', 'Jaundice, dark urine or a positive HBsAg result warrants prompt clinical evaluation with liver tests and HBV serology. Confusion or drowsiness, bleeding or bruising, vomiting blood or black stools, or rapidly increasing abdominal swelling suggest acute liver failure or decompensated cirrhosis and place the presentation in the EMERGENCY tier.', true, 'HBV infects hepatocytes, and liver injury is mainly immune-mediated: cytotoxic T cells attack infected hepatocytes rather than the virus directly destroying them. The virus persists as covalently closed circular DNA (cccDNA) in hepatocyte nuclei, which resists complete clearance and allows chronic infection and later reactivation. Immune complexes can cause extrahepatic disease such as polyarteritis nodosa and glomerulonephritis (membranous or membranoproliferative).', 'Hepatocellular injury raises transaminases and impairs bilirubin handling, producing jaundice and dark urine; hepatic inflammation and capsular stretch cause right upper quadrant pain. A serum sickness-like prodrome with fever, rash and arthralgia reflects immune complex formation and typically resolves as jaundice appears. Repeated cycles of inflammation in chronic infection drive fibrosis, cirrhosis (ascites, variceal bleeding, encephalopathy) and hepatocellular carcinoma.', 'Average incubation is about 60 days to abnormal ALT (range 40-90) and about 90 days to symptom onset (range 60-150). Adults aged 30 and older are more likely to have symptoms during acute infection, and about 95% of infected adults recover completely. Chronic infection passes through immune-tolerant, immune-active, inactive carrier and reactivation phases. About 15-25% of people with chronic infection develop chronic liver disease, including cirrhosis, liver failure or liver cancer.', 'Acute infection is followed with liver tests and serology until HBsAg clears and anti-HBs appears. Chronic infection is monitored with ALT, HBeAg status and HBV DNA to identify the immune-active phase needing treatment. Patients on tenofovir or entecavir need long-term follow-up, as most require lifelong therapy. Ultrasound surveillance for hepatocellular carcinoma is recommended in at-risk patients, and the risk of reactivation is considered before immunosuppressive therapy.', 'WHO fact sheet Hepatitis B (2026); StatPearls: Hepatitis B; CDC Clinical Overview of Hepatitis B; WHO Philippines (2017); Harrison''s Principles of Internal Medicine, 21st ed.', true),
    ('hepatitis_a', 'Hepatitis A', 'Hepatitis A virus (HAV) infection', 'Hepatitis A is an acute, self-limited liver infection caused by hepatitis A virus and spread mainly by the fecal-oral route through contaminated food or water or close contact. Illness ranges from mild to severe, with fever, loss of appetite, nausea, abdominal discomfort, dark urine and jaundice. Most children under 6 years are asymptomatic, while older children and adults usually have symptoms, often with jaundice. It does not cause chronic infection, but rare cases progress to acute liver failure, more often in older people and those with chronic liver disease.', (SELECT id FROM public.body_systems WHERE name = 'Digestive System' ORDER BY id LIMIT 1), 'Moderate', 'SEE_DOCTOR_SOON', 'Jaundice, dark urine or pale stools after a prodromal febrile illness warrant prompt evaluation with liver tests and viral hepatitis serology. Confusion or drowsiness, bleeding or bruising, persistent vomiting preventing oral intake, or illness in an older adult or someone with chronic liver disease raise concern for acute liver failure and place the presentation in a higher urgency tier.', true, 'Ingested HAV reaches the liver and replicates in hepatocytes and is shed in bile into the stool. Hepatocellular injury is not caused mainly by direct viral destruction of liver cells but by the adaptive immune response, particularly T-cell-mediated immunity, that clears the virus.', 'Immune-mediated hepatocyte injury produces marked transaminase elevation (often 10-100 times normal) and impaired bilirubin excretion, causing jaundice, dark urine and pale or clay-colored stools. Cholestasis can cause pruritus, and hepatic inflammation produces right upper quadrant discomfort.', 'Incubation is usually 14-28 days (CDC: average 28 days, range 15-50). A prodrome of fever, malaise, anorexia, nausea and right upper quadrant pain is followed by jaundice, dark urine and pale stools; the icteric phase lasts a median of about 2 weeks. Most patients recover fully. About 10-15% of symptomatic people have a prolonged or relapsing course for up to 6 months, a cholestatic variant can cause prolonged jaundice and itching, and fulminant hepatitis occurs in fewer than 1% of adults.', 'Liver function tests are followed until transaminases and bilirubin normalize. Prothrombin time/INR and mental status are monitored in patients with severe illness for signs of acute liver failure. Recurrence of symptoms within 6 months suggests relapsing hepatitis A. Close contacts are identified for post-exposure prophylaxis within 2 weeks of exposure.', 'WHO fact sheet Hepatitis A (2026); StatPearls: Hepatitis A (2024); CDC Clinical Overview of Hepatitis A; Harrison''s Principles of Internal Medicine, 21st ed.', true),
    ('cholera', 'Cholera', 'Vibrio cholerae O1/O139 infection', 'Cholera is an acute diarrheal infection caused by ingestion of food or water contaminated with toxigenic Vibrio cholerae serogroup O1 or O139. Most infected people are asymptomatic or have mild to moderate diarrhea, but a minority develop severe acute watery diarrhea with life-threatening dehydration that can be fatal within hours if untreated. Most cases are managed with oral rehydration solution. In the Philippines, cholera outbreaks are linked to unsafe water sources and poor hygiene; in 2022 Eastern Visayas reported 87 laboratory-confirmed cases and 32 suspected cholera deaths.', (SELECT id FROM public.body_systems WHERE name = 'Digestive System' ORDER BY id LIMIT 1), 'Severe', 'SEEK_URGENT_CARE', 'Acute profuse watery diarrhea, especially in an outbreak setting or after exposure to unsafe water, warrants same-day assessment of dehydration and early rehydration, because untreated cholera can kill within hours. Lethargy or unconsciousness, inability to drink, absent or weak pulse, low blood pressure or no urine output indicate severe dehydration or shock and place the presentation in the EMERGENCY tier.', true, 'After surviving gastric acid, V. cholerae colonizes the small intestine and secretes cholera toxin. The toxin''s A subunit permanently activates adenylate cyclase in enterocytes, raising cyclic AMP, which drives chloride secretion through CFTR and inhibits sodium chloride absorption. Water follows into the lumen, producing large-volume isotonic secretory diarrhea without mucosal invasion. Sodium-glucose cotransport remains intact, which is the physiological basis of oral rehydration solution.', 'Loss of large volumes of isotonic, bicarbonate- and potassium-rich stool produces the characteristic ''rice-water'' stools, hypovolemia (sunken eyes, dry mouth, thirst, reduced skin turgor, oliguria), metabolic acidosis and hypokalemia. Muscle cramps are secondary to electrolyte imbalance. Because the mucosa is not invaded, fever is usually absent and stools lack blood. Uncorrected hypovolemia leads to shock and prerenal acute kidney injury.', 'Symptoms begin 12 hours to 5 days after ingestion. Infected people, including those without symptoms, shed the organism in feces for 1-10 days. Watery diarrhea with nausea and vomiting can progress within hours to severe dehydration and hypovolemic shock. With prompt rehydration, most patients recover within a few days.', 'Dehydration status is reassessed frequently, with ongoing stool and vomit losses replaced by ORS or IV fluids. Urine output, mental status and pulse are monitored, and serum electrolytes and renal function are checked in moderate to severe cases. Stool culture supports confirmation and antimicrobial susceptibility testing, and confirmed cases are reported to public health authorities for outbreak response.', 'WHO fact sheet Cholera (2024); CDC Yellow Book: Cholera; Philippine Clinical Practice Guideline for Acute Infectious Diarrhea (pocket guide); DOH Eastern Visayas via Philippine News Agency (2022); Harrison''s Principles of Internal Medicine, 21st ed.', true),
    ('rabies', 'Rabies', 'Rabies virus (genus Lyssavirus, family Rhabdoviridae) encephalomyelitis', 'Rabies is an acute, progressive viral encephalomyelitis caused by rabies virus and related lyssaviruses, transmitted in the saliva of infected mammals through bites, scratches or contact with mucous membranes or broken skin. Dogs account for up to 99% of human cases worldwide, and about 40% of cases occur in children under 15. Once symptoms appear the disease is almost universally fatal, but it is preventable with prompt post-exposure prophylaxis. In the Philippines rabies causes the deaths of at least 200 Filipinos each year, and PEP is delivered through a network of government Animal Bite Treatment Centers under the National Rabies Prevention and Control Program.', (SELECT id FROM public.body_systems WHERE name = 'Nervous System' ORDER BY id LIMIT 1), 'Critical', 'EMERGENCY', 'Any bite, scratch or saliva contact from a dog, cat or other potentially rabid mammal is a time-critical exposure: wound washing and post-exposure prophylaxis (PEP) assessment at an Animal Bite Treatment Center or emergency department are indicated the same day, because PEP is nearly 100% effective only when given before the virus reaches the central nervous system. Once neurological signs (hydrophobia, aerophobia, hypersalivation, agitation, paralysis) appear, rabies is almost universally fatal and the presentation is in the EMERGENCY tier for palliative and supportive care.', false, 'After inoculation the virus multiplies locally in muscle and enters peripheral nerves at the neuromuscular junction via nicotinic acetylcholine receptors. It travels centripetally by retrograde axoplasmic flow to the dorsal root ganglia and spinal cord and then to the brain, where replication increases exponentially in the setting of an inadequate interferon response. The virus then spreads centrifugally along nerves to peripheral tissues, including the salivary glands, where it is shed in saliva. Progressive inflammation of the brain and spinal cord produces the neurological syndrome and death.', 'Involvement of the dorsal root ganglion supplying the bite site explains early pain and paresthesia at a healed wound. Brainstem involvement produces violent pharyngeal muscle spasms triggered by attempts to swallow water or by air currents (hydrophobia, aerophobia). Viral spread to the salivary glands combined with inability to swallow produces hypersalivation and drooling. Limbic and cortical encephalitis produce anxiety, agitation, hallucinations and delirium, while autonomic involvement causes autonomic instability. In paralytic rabies, ascending flaccid paralysis begins in the exposed limb.', 'The incubation period is typically 2-3 months but ranges from about one week to one year. A prodrome of fever, malaise, myalgia, headache and pain, tingling or burning at the wound site is followed by the neurological phase. About 80% of patients develop furious (encephalitic) rabies with hyperactivity, agitation, hallucinations and hydrophobia; about 20% develop paralytic rabies with ascending paralysis starting in the exposed limb. Coma develops within about 10 days of neurological onset, and death typically follows within 2-3 days of coma, usually from cardiorespiratory arrest.', 'For exposed persons, the WHO exposure category is documented, the full vaccine schedule is completed on the scheduled days, and rabies immunoglobulin is given within 7 days of the first vaccine dose when indicated. Immunocompromised patients receive an additional vaccine dose. Previously vaccinated persons receive a shortened booster course without immunoglobulin. Patients with clinical rabies receive comprehensive palliative care, with sedation, analgesia, hydration and management of secretions.', 'StatPearls: Rabies (Swinkels, Koury, Warrington; updated 2025); WHO fact sheet Rabies; DOH Philippines Rabies Prevention and Control Program; Amparo et al., PLOS ONE 2018 (Animal Bite Treatment Centers); Harrison''s Principles of Internal Medicine, 21st ed.', true),
    ('schistosomiasis', 'Schistosomiasis (Schistosoma japonicum)', 'Schistosomiasis japonica (intestinal and hepatosplenic schistosomiasis due to Schistosoma japonicum)', 'Schistosomiasis japonica is a chronic parasitic disease caused by the blood fluke Schistosoma japonicum, acquired when larval cercariae released by infected freshwater snails penetrate the skin during contact with infested water. S. japonicum occurs in China, Indonesia and the Philippines, where 28 of 81 provinces are endemic, mainly in Eastern Visayas (Samar and Leyte), Mindanao and parts of Luzon such as Oriental Mindoro and Sorsogon. The DOH Schistosomiasis Control and Elimination Program estimates about 12.4 million Filipinos at risk. Disease results mainly from the host reaction to eggs, producing intestinal symptoms and, in advanced cases, liver fibrosis with portal hypertension. In Davao del Norte and Davao de Oro, surveys in 2024 found low prevalence (about 0.8% in school-aged children and 0.4% in adults), consistent with good morbidity control under mass drug administration rather than elimination.', (SELECT id FROM public.body_systems WHERE name = 'Digestive System' ORDER BY id LIMIT 1), 'Moderate', 'SEE_DOCTOR_SOON', 'Chronic abdominal pain, diarrhea or blood in the stool in a person with freshwater exposure in an endemic area warrants non-urgent clinical review with stool examination. Vomiting blood, black or bloody stools with dizziness (possible variceal bleeding from portal hypertension), rapidly increasing abdominal distension, or new seizures or focal neurological deficits place the presentation in the EMERGENCY tier.', false, 'In endemic areas the snail Oncomelania hupensis quadrasi releases cercariae that penetrate human skin in freshwater. The larvae (schistosomula) migrate through the circulation, mature in the portal venous system and pair, and S. japonicum adults reside in the mesenteric veins, where females release eggs. Many eggs cross the intestinal wall and are passed in stool, but a large proportion are swept to the liver or remain trapped in tissues. Trapped eggs provoke granulomatous inflammation; in the liver this leads to periportal fibrosis and presinusoidal portal hypertension, with splenomegaly, collateral veins and ascites. S. japonicum is zoonotic, with carabao, cattle, dogs, pigs and rats among the many mammalian reservoir hosts that sustain transmission.', 'Egg-induced inflammation of the intestinal wall causes abdominal pain, diarrhea and blood in the stool. Periportal fibrosis with presinusoidal portal hypertension produces hepatosplenomegaly, ascites and portosystemic collaterals, which can bleed. Chronic blood loss and inflammation contribute to anemia, and in children to stunting and reduced learning ability. Acute schistosomiasis (Katayama syndrome), an immune reaction around the time of early egg laying, produces fever, rash, headache, myalgia, respiratory symptoms and eosinophilia. Ectopic egg deposition in the brain or spinal cord rarely causes granulomatous central nervous system lesions.', 'Acute schistosomiasis (Katayama syndrome) may appear about 14-84 days after exposure, usually in previously unexposed persons. Chronic infection develops over months to years with intermittent abdominal pain, diarrhea and blood in the stool. With heavy or prolonged infection, hepatosplenic disease with liver fibrosis, portal hypertension and ascites develops over years. Reinfection is common where water contact continues, so disease often reflects cumulative exposure.', 'Repeat stool examination about 1-2 months after praziquantel to confirm cure, with retreatment if eggs persist. Abdominal ultrasound assesses periportal fibrosis, hepatomegaly and splenomegaly in chronic disease. Patients with portal hypertension are followed for signs of variceal bleeding and ascites. In endemic communities, repeated treatment through mass drug administration is often required because of reinfection.', 'WHO fact sheet Schistosomiasis; CDC Clinical Overview of Schistosomiasis and Clinical Care of Schistosomiasis; Tabilin et al., Trop Med Infect Dis 2025 (Schistosomiasis in the Philippines); Belizario et al., Parasitol Int 2024 (Davao de Oro and Davao del Norte); DOH Philippines Schistosomiasis Control and Elimination Program; Harrison''s Principles of Internal Medicine, 21st ed.', true),
    ('pertussis', 'Pertussis (Whooping Cough)', 'Bordetella pertussis infection', 'Pertussis (whooping cough) is a highly contagious respiratory infection caused by the gram-negative coccobacillus Bordetella pertussis, spread by respiratory droplets with humans as the only reservoir. It is characterized by prolonged paroxysmal coughing with an inspiratory whoop and post-tussive vomiting. Young infants have the highest risk of severe disease, apnea and death. The Philippines experienced a pertussis surge in 2024: DOH data for January 1 to March 16, 2024 recorded 568 cases and 40 deaths, with 62.7% of cases in infants below six months and 67.6% of all cases unvaccinated or of unknown vaccination status.', (SELECT id FROM public.body_systems WHERE name = 'Respiratory System' ORDER BY id LIMIT 1), 'Severe', 'SEE_DOCTOR_SOON', 'Coughing fits, an inspiratory whoop or vomiting after coughing, especially with a pertussis contact or incomplete vaccination, warrant prompt clinical review for testing and early antibiotics. Infants under 6 months, and any patient with apnea, cyanosis, severe hypoxia, respiratory distress, poor feeding, seizures or pneumonia, are in the EMERGENCY tier and usually require hospitalization.', true, 'B. pertussis attaches to ciliated respiratory epithelium using adhesins such as filamentous hemagglutinin and pertactin. Tracheal cytotoxin damages ciliated cells and impairs mucociliary clearance, while pertussis toxin disrupts immune signaling and causes lymphocytosis. The organism remains on the respiratory mucosa rather than invading the bloodstream, and the toxin-mediated damage and impaired clearance produce the prolonged, paroxysmal cough. Marked leukocytosis is associated with pulmonary hypertension in severe infant disease.', 'Loss of ciliary clearance and airway irritation produce clusters of rapid coughs without time to inhale, followed by a forced inspiration against a narrowed glottis (the whoop) and often vomiting. Young infants may not generate a whoop and instead present with apnea and cyanosis. Pertussis toxin-driven lymphocytosis and hyperleukocytosis contribute to pulmonary hypertension. Forceful coughing can cause rib fractures, subconjunctival hemorrhage, syncope and urinary incontinence, and hypoxia can lead to seizures and encephalopathy.', 'The incubation period is about 7-10 days. The catarrhal stage (1-2 weeks) resembles a common cold with coryza, low-grade fever and a mild, occasional cough. The paroxysmal stage follows with numerous rapid coughs, the inspiratory whoop and post-tussive vomiting; paroxysms can reach about 15 per day, are more frequent at night and last about 2-3 weeks or longer. In the convalescent stage the cough subsides gradually over weeks, and paroxysms may recur with later respiratory infections. Adolescents and adults often have milder illness without a whoop.', 'Hospitalized infants are monitored for apnea, hypoxia and bradycardia, with attention to feeding, hydration and weight. White blood cell counts are followed in severe infant disease because extreme leukocytosis is associated with pulmonary hypertension. Close contacts are assessed for antibiotic post-exposure prophylaxis within 21 days of the index patient''s cough onset, and vaccination status of the patient and household is reviewed and updated.', 'StatPearls: Pertussis (Vijayan, Daley; updated 2026); CDC Clinical Features of Pertussis and Treatment of Pertussis; PIDSP Childhood Immunization Schedule 2026; PIDS Research Paper 2022-04 (EPI assessment); Philippine News Agency report of DOH surveillance data (March 2024); Nelson Textbook of Pediatrics, 22nd ed.', true),
    ('hfmd', 'Hand, Foot and Mouth Disease', 'Enteroviral vesicular stomatitis with exanthem (coxsackievirus A16, coxsackievirus A6, enterovirus A71)', 'Hand, foot and mouth disease (HFMD) is a common, highly contagious enteroviral infection that mainly affects infants and children younger than 5 years, although adolescents and adults can also be infected. It presents with fever, painful mouth sores and a vesicular rash on the palms, soles and buttocks. Most cases are mild and resolve in 7-10 days, but enterovirus A71 can cause rare neurologic and cardiopulmonary complications. The Philippines reported a sharp rise in cases in early 2025, with DOH recording 7,598 cases from January 1 to February 22, 2025, nearly three times the number for the same period in 2024.', (SELECT id FROM public.body_systems WHERE name = 'Integumentary System' ORDER BY id LIMIT 1), 'Mild', 'SEE_DOCTOR_SOON', 'Typical HFMD in a child who is drinking adequately is mild and self-limited, but clinical review is warranted to confirm the diagnosis, and DOH advises consultation at a health center once symptoms appear. Review is also indicated for poor oral intake with concern for dehydration, fever lasting more than 3 days, or symptoms not improving after 10 days (CDC). Neurologic signs (lethargy, severe headache, neck stiffness, limb weakness, seizures) or breathing difficulty suggest enterovirus A71-associated meningitis, encephalitis or cardiopulmonary involvement and place the presentation in the EMERGENCY tier.', true, 'The enteroviruses that cause HFMD are acquired by oral ingestion of virus shed from the gastrointestinal or upper respiratory tract of an infected person, or from vesicle fluid and oral secretions. The virus replicates in the oropharyngeal and intestinal mucosa and regional lymphoid tissue, then spreads by viremia to the oral mucosa and skin, where infection of epithelial cells produces vesicles surrounded by erythema. Coxsackievirus A16 is the most common cause; coxsackievirus A6 has emerged as another major cause worldwide, and enterovirus A71 is associated with most severe neurologic disease.', 'Oral vesicles rupture to form painful superficial ulcers with a grey-yellow base and erythematous rim, which cause odynophagia, reduced intake and a risk of dehydration. Skin lesions on the hands, feet, buttocks and legs are vesicles on an erythematous base that are usually non-pruritic and heal without scarring. Neurotropic enterovirus A71 accounts for aseptic meningitis, encephalitis and polio-like flaccid paralysis in a small minority of patients.', 'Incubation is about 3-6 days. Illness begins with fever, reduced appetite, sore throat and malaise, followed 1-2 days later by small red spots on the tongue and inner mouth that blister and become painful. A rash then appears on the palms and soles and may involve the buttocks, legs and arms. Most children recover within 7-10 days. Nail shedding (onychomadesis) may follow weeks later in rare cases.', 'Oral intake, urine output and hydration are monitored during the painful ulcer phase. Children are observed for neurologic signs (lethargy, irritability, limb weakness, seizures) and respiratory distress, particularly during outbreaks involving enterovirus A71. DOH advises home isolation for 7-10 days or until the fever resolves, with absence from school or work.', 'StatPearls: Hand, Foot, and Mouth Disease (2023); CDC HFMD Symptoms and Complications and About HFMD; WHO Western Pacific health topic on HFMD; DOH statement via Philippine News Agency (March 2025); Nelson Textbook of Pediatrics, 22nd ed.', true),
    ('varicella', 'Chickenpox (Varicella)', 'Primary varicella-zoster virus (human alphaherpesvirus 3) infection', 'Chickenpox (varicella) is a highly contagious disease caused by primary infection with varicella-zoster virus (VZV). It presents with fever, malaise and an itchy rash that evolves from macules to papules to vesicles and crusts, appearing in successive crops so that lesions at all stages are seen together. It is usually mild in children but more severe in adolescents, adults, pregnant women, neonates and immunocompromised people. About 90% of susceptible household contacts develop the disease after exposure, and a two-dose varicella vaccine prevents most infections. The virus then remains latent in sensory ganglia and can reactivate later as herpes zoster (shingles).', (SELECT id FROM public.body_systems WHERE name = 'Integumentary System' ORDER BY id LIMIT 1), 'Moderate', 'SEE_DOCTOR_SOON', 'Uncomplicated chickenpox in a healthy child is usually self-limited, but prompt clinical review is warranted because oral antivirals work best when started within 24 hours of rash onset in adolescents over 12 years, adults and children with chronic skin or lung disease or on steroid or long-term salicylate therapy (CDC, StatPearls). Exposure or illness in a pregnant woman, newborn or immunocompromised person needs same-day assessment for antiviral therapy or VariZIG. Breathing difficulty, red hot painful skin around blisters, confusion, unsteady gait, seizures or bleeding into lesions suggest pneumonia, bacterial superinfection, encephalitis or disseminated disease and place the presentation in the EMERGENCY tier.', true, 'VZV enters through the respiratory mucosa or conjunctiva by inhalation of aerosols from vesicular fluid or respiratory secretions, or by direct contact with skin lesions. After replication in regional lymphoid tissue, a primary viremia is followed by a secondary viremia that carries virus to the skin, where infection of epidermal cells produces ballooning degeneration and intraepidermal vesicles. The virus then establishes latency in dorsal root and cranial nerve ganglia.', 'Successive waves of viremia produce crops of pruritic lesions evolving from macules and papules to 1-3 mm clear vesicles on a red base (''dewdrop on a rose petal'') and then to crusts, so lesions at all stages coexist. Scratching and broken skin predispose to secondary bacterial skin and soft-tissue infection, the most common complication in children. Viral spread to the lungs causes varicella pneumonia, the most common serious complication in adults, and central nervous system involvement causes cerebellar ataxia or encephalitis.', 'Incubation averages 14-16 days (range 10-21 days). Adults may have 1-2 days of fever and malaise before the rash, while in children the rash is often the first sign. Prodromal symptoms can include muscle aches, nausea, decreased appetite and headache. New crops appear over several days, and lesions progress quickly from macules to vesicles to crusts. The person is contagious from 1-2 days before rash onset until all lesions have crusted, usually about 5 days after the spots appear.', 'Lesions are monitored for signs of bacterial superinfection (spreading redness, warmth, pain, pus). Respiratory symptoms, especially in adults, pregnant women and smokers, prompt assessment for pneumonia. Neurologic status is watched for ataxia or altered consciousness. The patient is excluded from school or work and kept away from newborns, pregnant women and immunocompromised people until all lesions have crusted.', 'StatPearls: Varicella-Zoster Virus (Chickenpox) (2025); CDC Clinical Overview of Chickenpox and Clinical Guidance for People at Risk for Severe Varicella; NHS Chickenpox; Nelson Textbook of Pediatrics, 22nd ed.', true),
    ('hiv_infection', 'HIV Infection', 'Human immunodeficiency virus (HIV-1, HIV-2) infection', 'HIV infection is a chronic retroviral infection that progressively depletes CD4+ T lymphocytes and, without treatment, can progress over years to acquired immunodeficiency syndrome (AIDS). HIV is transmitted through blood, semen, pre-ejaculate, rectal and vaginal fluids and breast milk, by sexual contact, shared injecting equipment and from mother to child. There is no cure, but lifelong antiretroviral therapy (ART) controls the virus, restores immune function and prevents transmission: people on ART with an undetectable viral load do not transmit HIV sexually. About 41 million people were living with HIV worldwide at the end of 2025. The Philippines has the fastest-growing HIV epidemic in the Asia-Pacific region, with cases rising from about 4,400 in 2010 to 29,600 in 2024 and about one third of new cases in early 2025 among people aged 15-24.', (SELECT id FROM public.body_systems WHERE name = 'Immune & Lymphatic System' ORDER BY id LIMIT 1), 'Severe', 'SEE_DOCTOR_SOON', 'A possible exposure, symptoms compatible with acute retroviral syndrome, or chronic features such as persistent lymphadenopathy, unexplained weight loss, oral thrush or chronic diarrhea warrant prompt HIV testing and linkage to care, because ART is started as soon as possible after diagnosis regardless of CD4 count. Recent exposure within the PEP window calls for same-day assessment. Features of an opportunistic infection or advanced HIV disease (severe breathlessness, fever with severe headache or confusion, seizures or focal weakness, hemoptysis, profuse diarrhea with dehydration, or signs of sepsis) place the presentation in the EMERGENCY tier.', true, 'HIV binds CD4 on T-helper lymphocytes and uses the chemokine coreceptors CCR5 or CXCR4 to fuse with the cell membrane. Reverse transcriptase converts viral RNA into DNA, which integrase inserts into the host genome, establishing lifelong latent infection. Ongoing viral replication and immune activation cause progressive loss of CD4+ T cells. When the CD4 count falls below about 200 cells/mm3, cell-mediated immunity fails and opportunistic infections and cancers develop.', 'High-level viremia in early infection produces a mononucleosis-like acute retroviral syndrome with fever, lymphadenopathy, pharyngitis, rash and mucocutaneous ulcers. Chronic immune activation causes persistent generalized lymphadenopathy. Falling CD4 counts explain the stepwise appearance of opportunistic infections: Pneumocystis pneumonia below 200 cells/mm3, cryptococcal meningitis and toxoplasmosis below 100, and disseminated Mycobacterium avium complex below 50. Tuberculosis can occur at any CD4 count and is the leading cause of death among people with HIV.', 'Up to about 90% of newly infected people develop acute retroviral syndrome within the first 4 weeks, with fever, fatigue, myalgia, rash, headache, sore throat, lymphadenopathy and night sweats that usually resolve within about 18 days. A prolonged chronic phase follows, often asymptomatic, with possible persistent generalized lymphadenopathy, oral candidiasis and oral hairy leukoplakia. Without ART, progression to AIDS (CD4 below 200 cells/mm3 or an AIDS-defining illness) typically occurs after many years, with wasting, chronic diarrhea and opportunistic infections.', 'HIV viral load is monitored after ART initiation to confirm and maintain viral suppression, and CD4 counts guide opportunistic-infection prophylaxis. Every visit includes adherence support and screening for tuberculosis symptoms. Baseline and periodic tests include hepatitis B and C serology, renal and liver function, and screening for sexually transmitted infections. Patients with a severe opportunistic infection are monitored for immune reconstitution inflammatory syndrome after ART is started.', 'StatPearls: HIV and AIDS (2026); WHO fact sheets HIV and AIDS (2026) and Tuberculosis; WHO news release on dolutegravir as preferred first- and second-line treatment (2019); WHO TB Knowledge Sharing Platform on ART adjustment with rifampicin; WHO Philippines/UNAIDS statement on the Philippine HIV surge (2025); DOH via Philippine News Agency (TLD as first-line, 2026); DOH-designated HIV treatment hubs (AIDS Data Hub); Harrison''s Principles of Internal Medicine, 21st ed.', true);
INSERT INTO public.diseases (id, name, scientific_name, description, body_system_id, severity, urgency, urgency_criteria, contagious, pathophysiology, clinicopathologic_correlation, onset_progression, follow_up_monitoring, source_attribution, is_published)
INSERT INTO public.disease_causes (disease_id, position, content) VALUES
    ('dengue', 0, 'Infection with dengue virus serotypes DENV-1, DENV-2, DENV-3 or DENV-4 (flavivirus)'),
    ('dengue', 1, 'Transmission by bite of infected Aedes aegypti (principal vector) or Aedes albopictus mosquitoes'),
    ('dengue', 2, 'Aedes breeding in stored water and water-holding containers near homes'),
    ('typhoid_fever', 0, 'Salmonella enterica serovar Typhi (Paratyphi A, B and C cause the clinically similar paratyphoid fever)'),
