    ('dengue', 0, 'CBC with platelet count and hematocrit at baseline and serially (leukopenia, thrombocytopenia, hemoconcentration)'),
    ('dengue', 1, 'Dengue NS1 antigen (typically positive in the first 4-7 days of illness)'),
    ('dengue', 2, 'Dengue RT-PCR (typically positive in the first 5 days)'),
    ('dengue', 3, 'Dengue IgM serology (detectable from about day 4 of illness)'),
    ('dengue', 4, 'Tourniquet test (10 or more petechiae per 2.5 cm square supports the diagnosis)'),
    ('typhoid_fever', 0, 'Blood culture, the first-line test: 100% specific, about 50-66% sensitive in endemic areas, highest yield in the first week. Multiple, larger-volume samples are preferred'),
    ('typhoid_fever', 1, 'Bone marrow culture: most sensitive (80-96%), even after antibiotics, but invasive and reserved for selected cases'),
    ('typhoid_fever', 2, 'Widal test: widely available but of low sensitivity and specificity, so results are interpreted with caution'),
    ('typhoid_fever', 3, 'Stool culture: not suitable for diagnosing acute typhoid. Used to detect convalescent shedding or chronic carriage'),
    ('typhoid_fever', 4, 'Antimicrobial susceptibility testing of isolates, given widespread fluoroquinolone non-susceptibility and MDR/XDR strains'),
    ('typhoid_fever', 5, 'CBC and liver function tests as supportive, nonspecific investigations'),
    ('leptospirosis', 0, 'Leptospira PCR on blood during the first week of illness (urine after the first week)'),
    ('leptospirosis', 1, 'Microscopic agglutination test (MAT), the reference serologic test, ideally on paired sera'),
    ('leptospirosis', 2, 'Leptospira-specific IgM ELISA or rapid diagnostic test'),
    ('leptospirosis', 3, 'Culture (reference standard, but slow)'),
    ('leptospirosis', 4, 'Supporting tests: CBC, urinalysis, serum creatinine and electrolytes, liver function tests, bleeding parameters'),
    ('leptospirosis', 5, 'Chest radiograph, ABG and ECG in moderate-severe disease'),
    ('tuberculosis', 0, 'Chest radiograph (upper-lobe infiltrates, cavitation, lymphadenopathy or effusion; findings nonspecific)'),
    ('tuberculosis', 1, 'Rapid molecular test on sputum (Xpert MTB/RIF or Ultra), which also detects rifampicin resistance'),
    ('tuberculosis', 2, 'Sputum AFB smear microscopy (sensitivity about 34-80%)'),
    ('tuberculosis', 3, 'Mycobacterial culture with drug-susceptibility testing (reference standard; results in 2-8 weeks)'),
    ('tuberculosis', 4, 'Tuberculin skin test or IGRA to detect infection (neither distinguishes latent from active TB)'),
    ('tuberculosis', 5, 'HIV test, blood glucose, and baseline liver function before treatment'),
    ('malaria', 0, 'Giemsa-stained thick and thin blood smears, the gold standard for diagnosis, species identification and percent parasitemia. Repeated every 12-24 h for 3 sets if initially negative and suspicion remains'),
    ('malaria', 1, 'Malaria rapid diagnostic test (RDT)'),
    ('malaria', 2, 'PCR for low-level parasitemia and species confirmation (including P. knowlesi)'),
    ('malaria', 3, 'CBC (anemia, thrombocytopenia), blood glucose, creatinine, bilirubin, and lactate or blood gas in suspected severe malaria'),
    ('malaria', 4, 'G6PD testing (quantitative) before primaquine or tafenoquine for P. vivax radical cure'),
    ('community_acquired_pneumonia', 0, 'Chest radiograph (PA and lateral) to confirm infiltrate and detect effusion or cavitation'),
    ('community_acquired_pneumonia', 1, 'Pulse oximetry or arterial blood gas'),
    ('community_acquired_pneumonia', 2, 'Complete blood count, serum electrolytes, BUN/creatinine and liver function tests'),
    ('community_acquired_pneumonia', 3, 'Blood cultures and sputum Gram stain/culture in moderate- to high-risk CAP (not routinely in low-risk CAP)'),
    ('community_acquired_pneumonia', 4, 'Influenza nucleic acid testing during periods of high influenza activity; SARS-CoV-2 testing'),
    ('community_acquired_pneumonia', 5, 'Legionella and pneumococcal urinary antigen in high-risk/severe CAP'),
    ('community_acquired_pneumonia', 6, 'Sputum AFB smear/GeneXpert when tuberculosis is a consideration'),
    ('community_acquired_pneumonia', 7, 'Severity scoring (CURB-65, PSI, or PSMID risk categories) to guide site of care'),
    ('influenza', 0, 'Clinical diagnosis is often sufficient during periods of known influenza activity'),
    ('influenza', 1, 'Rapid molecular assay (preferred over rapid antigen tests) in outpatients when results will change management'),
    ('influenza', 2, 'RT-PCR or other molecular assay of respiratory specimens in hospitalized patients'),
    ('influenza', 3, 'Chest radiograph when pneumonia is suspected'),
    ('influenza', 4, 'Pulse oximetry; CBC and blood cultures if secondary bacterial infection is suspected'),
    ('influenza', 5, 'SARS-CoV-2 testing, as clinical features overlap'),
    ('covid19', 0, 'RT-PCR of nasopharyngeal or other respiratory specimens (diagnostic standard)'),
    ('covid19', 1, 'Rapid antigen test (faster, lower sensitivity)'),
    ('covid19', 2, 'Pulse oximetry'),
    ('covid19', 3, 'Chest radiograph or CT in moderate-severe disease (bilateral ground-glass opacities)'),
    ('covid19', 4, 'CBC (lymphopenia), CRP, D-dimer, renal and liver function tests, troponin in hospitalized patients'),
    ('covid19', 5, 'Serology is not used to diagnose acute infection'),
    ('measles', 0, 'Measles RT-PCR on throat, nasopharyngeal or urine specimens (most sensitive in the first days after rash onset)'),
    ('measles', 1, 'Serum measles-specific IgM (may be falsely negative if collected very early after rash onset)'),
    ('measles', 2, 'Chest radiograph when pneumonia is suspected'),
    ('measles', 3, 'CBC and electrolytes in moderate-severe illness or dehydration'),
    ('measles', 4, 'Notification to public health authorities for case confirmation and contact tracing'),
    ('acute_gastroenteritis', 0, 'Clinical assessment of dehydration severity is the key initial evaluation'),
    ('acute_gastroenteritis', 1, 'Stool testing (culture or multiplex molecular panel) for fever, bloody or mucoid stools, severe abdominal pain, sepsis, immunosuppression or outbreak settings'),
    ('acute_gastroenteritis', 2, 'Shiga toxin testing in bloody diarrhea'),
    ('acute_gastroenteritis', 3, 'C. difficile testing after recent antibiotic exposure or hospitalization'),
    ('acute_gastroenteritis', 4, 'Serum electrolytes, BUN and creatinine in severe dehydration'),
    ('acute_gastroenteritis', 5, 'Stool microscopy for ova and parasites in persistent diarrhea'),
    ('urinary_tract_infection', 0, 'Urine dipstick: leukocyte esterase and nitrite'),
    ('urinary_tract_infection', 1, 'Urinalysis with microscopy (pyuria, bacteriuria, hematuria)'),
    ('urinary_tract_infection', 2, 'Urine culture with susceptibility testing (pyelonephritis, men, pregnancy, recurrence, treatment failure or complicated UTI)'),
    ('urinary_tract_infection', 3, 'Complete blood count and serum creatinine in suspected pyelonephritis'),
    ('urinary_tract_infection', 4, 'Blood cultures when sepsis is suspected'),
    ('urinary_tract_infection', 5, 'Renal ultrasound or CT when obstruction, abscess or non-response is suspected'),
    ('urinary_tract_infection', 6, 'Pregnancy test in women of reproductive age'),
    ('peptic_ulcer_disease', 0, 'Upper endoscopy (EGD), the diagnostic gold standard, with biopsy of gastric ulcers to exclude malignancy'),
    ('peptic_ulcer_disease', 1, 'H. pylori testing: urea breath test, stool antigen, or endoscopic biopsy (rapid urease test/histology)'),
    ('peptic_ulcer_disease', 2, 'Complete blood count (anemia) and iron studies'),
    ('peptic_ulcer_disease', 3, 'Fasting serum gastrin when Zollinger-Ellison syndrome is suspected (multiple, refractory or atypically located ulcers)'),
    ('peptic_ulcer_disease', 4, 'Upright chest radiograph or CT abdomen when perforation is suspected'),
    ('hypertension', 0, 'Repeated office blood pressure measurement on at least two separate occasions'),
    ('hypertension', 1, 'Home or 24-hour ambulatory blood pressure monitoring (identifies white-coat and masked hypertension)'),
    ('hypertension', 2, '12-lead ECG (left ventricular hypertrophy, arrhythmia)'),
    ('hypertension', 3, 'Serum electrolytes, creatinine and eGFR'),
    ('hypertension', 4, 'Fasting glucose or HbA1c and lipid panel'),
    ('hypertension', 5, 'Urinalysis and urine albumin-to-creatinine ratio'),
    ('hypertension', 6, 'Fundoscopy for hypertensive retinopathy'),
    ('type2_diabetes', 0, 'HbA1c (diagnostic at 6.5% or higher, 48 mmol/mol)'),
    ('type2_diabetes', 1, 'Fasting plasma glucose (diagnostic at 126 mg/dL or higher, 7.0 mmol/L)'),
    ('type2_diabetes', 2, '75-g oral glucose tolerance test (2-hour value 200 mg/dL or higher, 11.1 mmol/L)'),
    ('type2_diabetes', 3, 'Random plasma glucose 200 mg/dL or higher with classic symptoms'),
    ('type2_diabetes', 4, 'Serum creatinine/eGFR and urine albumin-to-creatinine ratio'),
    ('type2_diabetes', 5, 'Lipid profile'),
    ('type2_diabetes', 6, 'Dilated retinal examination and foot examination (monofilament)'),
    ('type2_diabetes', 7, 'Serum or urine ketones and serum osmolality when DKA or hyperosmolar state is suspected'),
    ('asthma', 0, 'Spirometry with bronchodilator responsiveness testing (FEV1 increase of 12% or more and 200 mL or more in adults)'),
    ('asthma', 1, 'Peak expiratory flow variability monitoring'),
    ('asthma', 2, 'Bronchial challenge testing when spirometry is non-diagnostic'),
    ('asthma', 3, 'Fractional exhaled nitric oxide (FeNO) and blood eosinophil count for type 2 inflammation'),
    ('asthma', 4, 'Allergy testing (skin prick or specific IgE) to identify relevant triggers'),
    ('asthma', 5, 'Chest radiograph to exclude alternative diagnoses when atypical'),
    ('asthma', 6, 'Pulse oximetry and arterial blood gas in severe exacerbations'),
    ('copd', 0, 'Post-bronchodilator spirometry (FEV1/FVC below 0.70 confirms persistent airflow limitation; FEV1 % predicted grades severity GOLD 1-4)'),
    ('copd', 1, 'Pulse oximetry and arterial blood gas analysis (hypoxemia, hypercapnia)'),
    ('copd', 2, 'Chest radiograph (hyperinflation; exclusion of pneumonia, pneumothorax, lung cancer)'),
    ('copd', 3, 'Complete blood count including blood eosinophil count (polycythemia, eosinophils guide ICS use)'),
    ('copd', 4, 'Alpha-1 antitrypsin level'),
    ('copd', 5, 'High-resolution chest CT in selected cases (emphysema distribution, bronchiectasis, lung cancer screening)'),
    ('acute_coronary_syndrome', 0, '12-lead ECG within 10 minutes of first medical contact (ST elevation of 1 mm or more in 2 or more contiguous leads defines STEMI), repeated serially'),
    ('acute_coronary_syndrome', 1, 'High-sensitivity cardiac troponin with rise and/or fall above the 99th percentile'),
    ('acute_coronary_syndrome', 2, 'Risk stratification scores (HEART, TIMI, GRACE)'),
    ('acute_coronary_syndrome', 3, 'Transthoracic echocardiography (regional wall motion, LVEF, mechanical complications)'),
    ('acute_coronary_syndrome', 4, 'Coronary angiography (diagnostic and for PCI)'),
    ('acute_coronary_syndrome', 5, 'Complete blood count, electrolytes, renal function, lipid profile and glucose/HbA1c'),
    ('heart_failure', 0, 'Transthoracic echocardiography (initial imaging test; LVEF, chamber size, wall motion, valves, filling pressures)'),
    ('heart_failure', 1, 'BNP or NT-proBNP (differentiates cardiac from noncardiac dyspnea; falsely low in obesity, raised in renal dysfunction and atrial fibrillation)'),
    ('heart_failure', 2, '12-lead ECG (prior infarction, arrhythmia, conduction delay)'),
    ('heart_failure', 3, 'Chest radiograph (cardiomegaly, pulmonary edema, Kerley B lines, pleural effusion)'),
    ('heart_failure', 4, 'Complete blood count, electrolytes, renal and liver function, glucose, lipids, thyroid function'),
    ('heart_failure', 5, 'Coronary angiography or stress imaging to assess ischemic etiology; cardiac MRI for infiltrative or inflammatory disease'),
    ('ischemic_stroke', 0, 'Non-contrast CT head as soon as possible after arrival to exclude hemorrhage'),
    ('ischemic_stroke', 1, 'Point-of-care blood glucose (hypoglycemia is a key stroke mimic)'),
    ('ischemic_stroke', 2, 'CT angiography with or without perfusion imaging to identify large-vessel occlusion and thrombectomy eligibility'),
    ('ischemic_stroke', 3, 'MRI with diffusion-weighted imaging (positive within minutes of infarction)'),
    ('ischemic_stroke', 4, '12-lead ECG, troponin, complete blood count, electrolytes, renal function and coagulation studies'),
    ('ischemic_stroke', 5, 'Cardiac rhythm monitoring and echocardiography, carotid imaging and lipid profile for etiologic work-up'),
    ('migraine', 0, 'Clinical diagnosis using ICHD-3 criteria (5 or more attacks for migraine without aura; 2 or more for migraine with aura)'),
    ('migraine', 1, 'Complete neurological examination, fundoscopy and blood pressure measurement'),
    ('migraine', 2, 'Neuroimaging (MRI or CT) only when red flags are present: thunderclap onset, abnormal examination, atypical or changing pattern, new onset after 50, immunosuppression'),
    ('migraine', 3, 'Headache diary to document frequency and medication use'),
    ('chikungunya', 0, 'RT-PCR for chikungunya virus RNA in the acute phase (first 5 days to first week of illness)'),
    ('chikungunya', 1, 'Chikungunya IgM/IgG serology (ELISA) after the first week; antibodies remain detectable for about two months'),
    ('chikungunya', 2, 'Concurrent dengue testing (and Zika where relevant), because clinical features overlap'),
    ('chikungunya', 3, 'CBC (lymphopenia and mild thrombocytopenia may occur; marked thrombocytopenia favors dengue)'),
    ('hepatitis_b', 0, 'HBsAg (marker of current infection; recommended by WHO for blood donors and pregnant women)'),
    ('hepatitis_b', 1, 'IgM anti-HBc (acute infection; the only marker present in the window period)'),
    ('hepatitis_b', 2, 'HBeAg and quantitative HBV DNA (replication and viral load, guiding treatment decisions)'),
    ('hepatitis_b', 3, 'Anti-HBs (immunity after recovery or vaccination)'),
    ('hepatitis_b', 4, 'Liver function tests (ALT, AST, bilirubin) and markers of liver synthetic function'),
    ('hepatitis_b', 5, 'Liver ultrasound (liver disease assessment and hepatocellular carcinoma surveillance)'),
    ('hepatitis_a', 0, 'IgM anti-HAV (confirms acute infection; usually positive for 4-6 months)'),
    ('hepatitis_a', 1, 'Liver function tests: ALT, AST (often 10-100-fold elevated), total and direct bilirubin, alkaline phosphatase'),
    ('hepatitis_a', 2, 'Prothrombin time/INR in severe illness (assessment for acute liver failure)'),
    ('hepatitis_a', 3, 'HBsAg and IgM anti-HBc to exclude other viral hepatitis, since clinical features alone cannot distinguish the types'),
    ('hepatitis_a', 4, 'HAV RNA by RT-PCR where available'),
    ('cholera', 0, 'Clinical assessment and grading of dehydration'),
    ('cholera', 1, 'Stool culture on selective media (TCBS agar) to isolate toxigenic V. cholerae O1/O139 and test antimicrobial susceptibility'),
    ('cholera', 2, 'Rapid diagnostic test for V. cholerae antigen in stool, mainly for outbreak detection'),
    ('cholera', 3, 'Molecular testing (PCR) where available'),
    ('cholera', 4, 'Serum electrolytes (potassium, bicarbonate) and renal function in moderate to severe dehydration'),
    ('rabies', 0, 'Saliva RT-PCR for rabies virus RNA (part of the CDC antemortem specimen set)'),
    ('rabies', 1, 'Nuchal skin biopsy containing hair follicles, tested by direct fluorescent antibody (DFA) and RT-PCR'),
    ('rabies', 2, 'Cerebrospinal fluid for rabies virus neutralizing antibodies (RFFIT) and indirect fluorescent antibody testing'),
    ('rabies', 3, 'Serum rabies virus neutralizing antibodies (interpreted with vaccination history)'),
    ('rabies', 4, 'Postmortem confirmation by DFA or RT-PCR on brainstem and cerebellum tissue'),
    ('rabies', 5, 'Clinical classification of the exposure by WHO category (I, II or III); no test detects rabies infection before clinical onset'),
    ('schistosomiasis', 0, 'Stool microscopy for S. japonicum eggs by the Kato-Katz technique (the primary diagnostic method used in the Philippines); multiple samples improve sensitivity'),
    ('schistosomiasis', 1, 'CBC with differential (eosinophilia, particularly in acute schistosomiasis; anemia in chronic disease)'),
    ('schistosomiasis', 2, 'Schistosome serology or circulating antigen detection when stool microscopy is negative but suspicion remains'),
    ('schistosomiasis', 3, 'Molecular testing (PCR) of stool or serum where available; more sensitive than Kato-Katz in light infections'),
    ('schistosomiasis', 4, 'Abdominal ultrasound for periportal fibrosis, hepatomegaly and splenomegaly'),
    ('schistosomiasis', 5, 'Repeat stool examination 1-2 months after treatment to confirm cure'),
    ('pertussis', 0, 'Nasopharyngeal swab or aspirate PCR for B. pertussis (first-line; most useful within about the first 4 weeks of cough)'),
    ('pertussis', 1, 'Nasopharyngeal culture on specialized media (highly specific; results take 7-10 days)'),
    ('pertussis', 2, 'Serology from about 3-12 weeks after cough onset; not used in infants under 6 months or recently vaccinated persons'),
    ('pertussis', 3, 'CBC with differential for lymphocytosis and leukocytosis'),
    ('pertussis', 4, 'Pulse oximetry and cardiorespiratory monitoring in infants'),
    ('pertussis', 5, 'Chest radiograph when pneumonia is suspected'),
    ('hfmd', 0, 'Clinical diagnosis based on oral ulcers with vesicular rash on the hands, feet and buttocks'),
    ('hfmd', 1, 'Enterovirus PCR of a vesicle or lesion swab when confirmation or strain identification is needed'),
    ('hfmd', 2, 'Assessment of hydration with serum electrolytes in children with poor oral intake'),
    ('hfmd', 3, 'Cerebrospinal fluid analysis when meningitis or encephalitis is suspected'),
    ('varicella', 0, 'Clinical diagnosis based on the characteristic pruritic vesicular rash with lesions at different stages'),
    ('varicella', 1, 'PCR of vesicle fluid or scabs for laboratory confirmation, particularly in atypical or breakthrough cases'),
    ('varicella', 2, 'Chest X-ray in adolescents and adults with cough or shortness of breath to assess for varicella pneumonia'),
    ('varicella', 3, 'CBC with platelet count in severe or hemorrhagic disease'),
    ('varicella', 4, 'VZV IgG serology to document immunity in exposed pregnant or immunocompromised contacts'),
    ('hiv_infection', 0, 'Rapid HIV tests or fourth-generation antigen/antibody immunoassay (HIV-1/2 antibodies plus p24 antigen), with same-day results; HIV self-tests are also available'),
    ('hiv_infection', 1, 'Confirmatory testing of all reactive results per national algorithm'),
    ('hiv_infection', 2, 'HIV RNA nucleic acid test (detectable as early as 6-8 days after infection) when acute HIV is suspected'),
    ('hiv_infection', 3, 'Baseline CD4+ T-cell count and HIV-1 RNA viral load'),
    ('hiv_infection', 4, 'Genotypic drug-resistance testing where available'),
    ('hiv_infection', 5, 'Hepatitis B and C serology, renal and liver function, and screening for other sexually transmitted infections'),
    ('hiv_infection', 6, 'Tuberculosis symptom screening with further testing (chest X-ray, sputum testing) as indicated');
INSERT INTO public.disease_treatments (disease_id, position, content) VALUES
    ('dengue', 0, 'No specific antiviral therapy exists; management is supportive and based on early risk stratification (WHO 2009: without warning signs, with warning signs, severe dengue)'),
    ('dengue', 1, 'Paracetamol for fever and pain. Aspirin and NSAIDs are avoided because of bleeding risk'),
    ('dengue', 2, 'Hospital admission for warning signs, comorbidities, extremes of age, pregnancy, obesity, unreliable follow-up or inability to maintain oral intake'),
    ('dengue', 3, 'Isotonic crystalloids (0.9% saline, Ringer''s lactate) for established volume depletion/plasma leakage, titrated to clinical status and hematocrit. Hypotonic fluids are avoided'),
    ('dengue', 4, 'Fluids are reduced or stopped after the critical phase to prevent iatrogenic fluid overload. Colloids are considered only in refractory shock'),
    ('dengue', 5, 'Blood products are reserved for clinically significant bleeding. Prophylactic platelet transfusion is not recommended. A falling hematocrit in shock suggests occult bleeding'),
    ('typhoid_fever', 0, 'Uncomplicated disease where fluoroquinolone resistance is common: azithromycin 1 g on day 1, then 500 mg daily for 7 days'),
    ('typhoid_fever', 1, 'Severe disease or high fluoroquinolone resistance: ceftriaxone 2 g IV daily for about 10 days'),
    ('typhoid_fever', 2, 'Fluoroquinolone-susceptible isolates: ciprofloxacin 500 mg orally every 12 hours for 7 days (mild) to 10 days (severe)'),
    ('typhoid_fever', 3, 'XDR S. Typhi: azithromycin (uncomplicated) or a carbapenem such as meropenem'),
    ('typhoid_fever', 4, 'Severe typhoid with CNS involvement (delirium, obtundation, shock): adjunctive high-dose dexamethasone'),
    ('typhoid_fever', 5, 'Surgical management of intestinal perforation. Cholecystectomy is considered for chronic carriers with gallstones (cures 70-90%)'),
    ('leptospirosis', 0, 'Mild disease (outpatient): doxycycline 100 mg orally twice daily for 7 days. Alternatives are amoxicillin or azithromycin'),
    ('leptospirosis', 1, 'Moderate-severe disease (inpatient): IV penicillin G 1.5 million units every 6 hours, or ceftriaxone 1 g IV every 24 hours. Alternatives are ampicillin and cefotaxime'),
    ('leptospirosis', 2, 'Monitoring for a Jarisch-Herxheimer reaction after the first antibiotic doses'),
    ('leptospirosis', 3, 'Fluid and electrolyte management with attention to potassium losses and volume status'),
    ('leptospirosis', 4, 'Renal replacement therapy (dialysis) for severe or oligoanuric acute kidney injury'),
    ('leptospirosis', 5, 'ICU care with mechanical ventilation for pulmonary hemorrhage or respiratory failure'),
    ('tuberculosis', 0, 'Drug-susceptible TB: 2 months isoniazid, rifampicin, pyrazinamide and ethambutol (intensive phase), then 4 months isoniazid and rifampicin (continuation phase), i.e., 2HRZE/4HR'),
    ('tuberculosis', 1, '4-month alternative (CDC 2022): rifapentine, isoniazid, pyrazinamide and moxifloxacin for 8 weeks, then rifapentine, isoniazid and moxifloxacin for 9 weeks, in eligible patients'),
    ('tuberculosis', 2, 'Directly observed therapy / treatment support (DOTS) to ensure adherence and prevent acquired resistance'),
    ('tuberculosis', 3, 'Pyridoxine (vitamin B6) with isoniazid to prevent peripheral neuropathy in at-risk patients'),
    ('tuberculosis', 4, 'Extended continuation phase (total up to 9 months) for cavitary disease with a positive 2-month culture'),
    ('tuberculosis', 5, 'Rifampicin-resistant/MDR TB requires specialist second-line regimens guided by susceptibility testing'),
    ('malaria', 0, 'Uncomplicated P. falciparum: artemisinin-based combination therapy such as artemether-lumefantrine, taken with fatty food. WHO standard is a 3-day (6-dose) course. US CDC guidance was extended to a 5-day (10-dose) course in August 2026'),
    ('malaria', 1, 'Uncomplicated P. vivax: chloroquine where the parasite is chloroquine-sensitive, or an ACT'),
    ('malaria', 2, 'P. vivax radical cure: primaquine (e.g., 30 mg daily for 14 days) or tafenoquine after G6PD testing. Contraindicated in G6PD deficiency and pregnancy'),
    ('malaria', 3, 'Severe malaria: IV artesunate 2.4 mg/kg at 0, 12 and 24 h, then daily until parasitemia is 1% or less and oral intake is possible, followed by a full oral ACT course'),
    ('malaria', 4, 'Supportive care in severe malaria: management of hypoglycemia, fluids, transfusion for severe anemia, seizure control, and renal replacement therapy as needed'),
    ('community_acquired_pneumonia', 0, 'Low-risk CAP without comorbidities (PSMID 2020): amoxicillin 1 g PO three times daily, or clarithromycin 500 mg PO twice daily, or azithromycin 500 mg PO once daily'),
    ('community_acquired_pneumonia', 1, 'Low-risk CAP with stable comorbidities (PSMID 2020): co-amoxiclav or cefuroxime, with or without a macrolide or doxycycline'),
    ('community_acquired_pneumonia', 2, 'Moderate-risk CAP (hospitalized, no MDRO risk): IV non-pseudomonal beta-lactam (e.g., ceftriaxone 1-2 g daily, ampicillin-sulbactam, cefotaxime) plus a macrolide (azithromycin or clarithromycin)'),
    ('community_acquired_pneumonia', 3, 'High-risk CAP (ICU): non-pseudomonal beta-lactam plus macrolide; alternative is beta-lactam plus a respiratory fluoroquinolone (levofloxacin or moxifloxacin)'),
    ('community_acquired_pneumonia', 4, 'Added coverage only with specific risk factors: anti-MRSA agent (vancomycin, linezolid) or antipseudomonal/anti-ESBL beta-lactam per risk profile'),
    ('community_acquired_pneumonia', 5, 'Antibiotic duration: minimum 5 days once clinically stable (PSMID 2020); longer for Pseudomonas, S. aureus, Legionella or complications such as empyema or abscess'),
    ('community_acquired_pneumonia', 6, 'Oseltamivir added when influenza is suspected or confirmed'),
    ('community_acquired_pneumonia', 7, 'Supplemental oxygen for hypoxemia; drainage of complicated parapneumonic effusion or empyema'),
    ('community_acquired_pneumonia', 8, 'Systemic corticosteroids are not used in nonsevere CAP; ATS 2025 conditionally supports them in severe CAP (excluding influenza pneumonia)'),
    ('influenza', 0, 'Oseltamivir 75 mg PO twice daily for 5 days for hospitalized patients, severe or progressive illness, and high-risk outpatients, started as early as possible without waiting for test confirmation'),
    ('influenza', 1, 'Greatest benefit when started within 48 hours of onset; hospitalized patients are treated regardless of illness duration'),
    ('influenza', 2, 'Oseltamivir dose reduced in renal impairment (e.g., 30 mg twice daily for CrCl 31-60 mL/min)'),
    ('influenza', 3, 'Oseltamivir is the preferred antiviral in pregnancy'),
    ('influenza', 4, 'Antiviral treatment may be considered for otherwise healthy outpatients presenting within 2 days of onset'),
    ('influenza', 5, 'Empiric antibiotics when bacterial coinfection is suspected (severe initial illness or deterioration after initial improvement), covering S. pneumoniae and S. aureus'),
    ('influenza', 6, 'Adjunctive corticosteroids are not recommended for influenza, influenza pneumonia or ARDS unless indicated for another reason (IDSA 2018)'),
    ('covid19', 0, 'Non-severe disease at high risk of hospitalization: nirmatrelvir 300 mg + ritonavir 100 mg PO twice daily for 5 days, started within 5 days of symptom onset (150/100 mg if eGFR 30-60; not recommended if eGFR <30 or Child-Pugh C)'),
    ('covid19', 1, 'Remdesivir is an alternative antiviral for eligible patients'),
    ('covid19', 2, 'Severe or critical disease: systemic corticosteroid (dexamethasone 6 mg daily up to 10 days) plus supplemental oxygen'),
    ('covid19', 3, 'Severe or critical disease with progression: IL-6 receptor blocker (tocilizumab) or baricitinib added to corticosteroids'),
    ('covid19', 4, 'Thromboprophylaxis with heparin in hospitalized patients; oxygen, high-flow nasal oxygen, noninvasive or invasive ventilation as required'),
    ('covid19', 5, 'Corticosteroids are not recommended for non-severe COVID-19'),
    ('covid19', 6, 'Ivermectin and hydroxychloroquine are not recommended for COVID-19 treatment (WHO)'),
    ('measles', 0, 'No specific antiviral therapy; management is supportive (antipyretics, fluids, nutrition)'),
    ('measles', 1, 'Vitamin A: two doses 24 hours apart (200,000 IU for age 12 months and older, 100,000 IU for 6-11 months, 50,000 IU under 6 months), with a third dose 4-6 weeks later if signs of deficiency'),
    ('measles', 2, 'Antibiotics directed at secondary bacterial complications such as otitis media and pneumonia'),
    ('measles', 3, 'Airborne isolation until 4 days after rash onset'),
    ('measles', 4, 'Hospital care for pneumonia, encephalitis, severe dehydration or severe malnutrition'),
    ('acute_gastroenteritis', 0, 'Reduced-osmolarity oral rehydration solution is first-line for mild to moderate dehydration'),
    ('acute_gastroenteritis', 1, 'Intravenous isotonic crystalloid for severe dehydration, shock or failure of oral rehydration'),
    ('acute_gastroenteritis', 2, 'Antibiotics are not recommended for most immunocompetent adults with acute watery diarrhea'),
    ('acute_gastroenteritis', 3, 'Empiric antibiotic (azithromycin, or a fluoroquinolone such as ciprofloxacin guided by local susceptibility) for febrile bloody diarrhea suggesting Shigella, travelers with fever >=38.5 C or sepsis, and immunocompromised hosts'),
    ('acute_gastroenteritis', 4, 'Antibiotics are avoided in STEC O157 and Shiga toxin 2-producing E. coli infection because of the risk of hemolytic uremic syndrome'),
    ('acute_gastroenteritis', 5, 'Antibiotics alongside aggressive rehydration in severe cholera (tetracyclines such as doxycycline are active against Vibrio)'),
    ('acute_gastroenteritis', 6, 'Loperamide may be used in immunocompetent adults with acute watery diarrhea but is avoided with fever, bloody or inflammatory diarrhea, or suspected toxic megacolon'),
    ('acute_gastroenteritis', 7, 'Zinc supplementation for children 6 months to 5 years in zinc-deficient settings'),
    ('urinary_tract_infection', 0, 'Acute uncomplicated cystitis in non-pregnant women: short-course nitrofurantoin (NICE: 3 days; StatPearls: 5-7 days), or trimethoprim-based therapy where local resistance is low; fosfomycin single dose or pivmecillinam are alternatives'),
    ('urinary_tract_infection', 1, 'Cystitis in men: 7-day antibiotic course (e.g., trimethoprim or nitrofurantoin per NICE), with urine culture; prostatitis considered'),
    ('urinary_tract_infection', 2, 'Pregnancy: nitrofurantoin for 7 days (avoided at term) or culture-guided beta-lactam; asymptomatic bacteriuria is also treated'),
    ('urinary_tract_infection', 3, 'Uncomplicated pyelonephritis managed as outpatient: fluoroquinolone for 7 days where community resistance is 10% or less, often after an initial parenteral dose of ceftriaxone; therapy adjusted to culture'),
    ('urinary_tract_infection', 4, 'Pyelonephritis with sepsis, persistent vomiting, pregnancy, immunocompromise, obstruction or treatment failure: hospital admission with parenteral antibiotics'),
    ('urinary_tract_infection', 5, 'Nitrofurantoin and fosfomycin are not used for pyelonephritis because of inadequate renal tissue levels'),
    ('urinary_tract_infection', 6, 'Analgesia with paracetamol (ibuprofen as an alternative where suitable)'),
    ('peptic_ulcer_disease', 0, 'Proton pump inhibitor therapy to heal the ulcer and relieve symptoms'),
    ('peptic_ulcer_disease', 1, 'H. pylori eradication: optimized bismuth quadruple therapy (PPI, bismuth, tetracycline, metronidazole) for 14 days is the preferred first-line regimen per ACG 2024'),
    ('peptic_ulcer_disease', 2, 'Vonoprazan-amoxicillin dual therapy is an alternative first-line option (ACG 2024)'),
    ('peptic_ulcer_disease', 3, 'Clarithromycin-based triple therapy is used only when clarithromycin susceptibility has been demonstrated'),
    ('peptic_ulcer_disease', 4, 'Discontinuation of NSAIDs where possible; when continued NSAID or aspirin therapy is required, co-therapy with a PPI'),
    ('peptic_ulcer_disease', 5, 'Bleeding ulcer: resuscitation, endoscopic hemostasis and high-dose PPI therapy'),
    ('peptic_ulcer_disease', 6, 'Surgery or interventional radiology for perforation, uncontrolled bleeding or refractory gastric outlet obstruction'),
    ('hypertension', 0, 'Lifestyle modification for all patients: sodium restriction, DASH-type diet, weight reduction, regular aerobic exercise, limitation of alcohol and smoking cessation'),
    ('hypertension', 1, 'First-line drug classes: ACE inhibitors, angiotensin receptor blockers, dihydropyridine calcium channel blockers and thiazide or thiazide-like diuretics'),
    ('hypertension', 2, 'Initial two-drug combination (RAAS inhibitor plus calcium channel blocker or diuretic), preferably as a single-pill combination, when BP is well above target (Philippine 2020 CPG: above 150/90 mm Hg)'),
    ('hypertension', 3, 'Philippine 2020 CPG target: below 130/80 mm Hg for most adults; below 140/90 mm Hg for adults aged 80 and older'),
    ('hypertension', 4, 'Resistant hypertension: spironolactone is the preferred fourth-line agent'),
    ('hypertension', 5, 'Beta-blockers reserved for compelling indications (heart failure with reduced ejection fraction, post-myocardial infarction, rate control in atrial fibrillation)'),
    ('hypertension', 6, 'Hypertensive emergency: hospital management with controlled BP reduction (generally no more than 25% within the first hour)'),
    ('type2_diabetes', 0, 'Lifestyle therapy (medical nutrition therapy, physical activity, weight management) as the foundation of care'),
    ('type2_diabetes', 1, 'Metformin as the usual initial pharmacological agent'),
    ('type2_diabetes', 2, 'SGLT2 inhibitors (and/or GLP-1 receptor agonists) for patients with established atherosclerotic cardiovascular disease, heart failure or chronic kidney disease, independent of HbA1c'),
    ('type2_diabetes', 3, 'Additional agents (sulfonylureas, DPP-4 inhibitors, pioglitazone, insulin) chosen by efficacy, hypoglycemia risk, weight effect, cost and comorbidities'),
    ('type2_diabetes', 4, 'Insulin when hyperglycemia is severe or symptomatic, or when catabolic features are present'),
    ('type2_diabetes', 5, 'Cardiovascular risk reduction: blood pressure control, statin therapy, and ACE inhibitor or ARB when albuminuria and hypertension coexist'),
    ('type2_diabetes', 6, 'Individualized glycemic targets (an HbA1c below 7% is appropriate for many non-pregnant adults), avoiding hypoglycemia'),
    ('asthma', 0, 'All adults and adolescents receive inhaled corticosteroid (ICS)-containing treatment; SABA-only treatment is not recommended (GINA)'),
    ('asthma', 1, 'GINA Track 1 (preferred): as-needed low-dose ICS-formoterol as reliever, with maintenance-and-reliever ICS-formoterol at higher steps'),
    ('asthma', 2, 'GINA Track 2 (alternative): daily maintenance ICS or ICS-LABA with as-needed SABA or ICS-SABA reliever'),
    ('asthma', 3, 'Step-up options for uncontrolled asthma: higher-dose ICS-LABA, add-on long-acting muscarinic antagonist, and phenotype-directed biologics (anti-IgE, anti-IL-5/5R, anti-IL-4R, anti-TSLP) for severe asthma'),
    ('asthma', 4, 'Acute exacerbation: repeated inhaled SABA (pMDI with spacer) or ICS-formoterol, controlled oxygen to target saturation, and oral prednisolone/prednisone 40-50 mg daily for 5-7 days in adults'),
    ('asthma', 5, 'Management of comorbidities (allergic rhinitis, obesity, GERD, obstructive sleep apnea)'),
    ('copd', 0, 'Smoking cessation (pharmacotherapy plus counseling) is the single most effective intervention to slow disease progression'),
    ('copd', 1, 'Short-acting bronchodilators (SABA or SAMA) as needed for symptom relief'),
    ('copd', 2, 'Long-acting bronchodilators (LABA, LAMA, or LABA+LAMA dual therapy) as maintenance for persistent symptoms'),
    ('copd', 3, 'Inhaled corticosteroid added to long-acting bronchodilators for patients with exacerbations and raised blood eosinophils (e.g., 300 cells/uL or more); triple therapy (ICS/LABA/LAMA) for persistent exacerbations'),
    ('copd', 4, 'Exacerbations: intensified short-acting bronchodilators, a short course of systemic corticosteroid (e.g., prednisone 40 mg for 5 days), and antibiotics when sputum becomes purulent or increases in volume'),
    ('copd', 5, 'Controlled oxygen targeting SpO2 88-92% and noninvasive ventilation for acute hypercapnic respiratory failure'),
    ('copd', 6, 'Long-term oxygen therapy for chronic resting hypoxemia; prophylactic azithromycin or roflumilast in selected frequent exacerbators'),
    ('copd', 7, 'Pulmonary rehabilitation and vaccination (influenza, pneumococcal, COVID-19, RSV, Tdap)'),
    ('acute_coronary_syndrome', 0, 'Aspirin 162-325 mg chewed at presentation, then low-dose maintenance'),
    ('acute_coronary_syndrome', 1, 'Dual antiplatelet therapy with a P2Y12 inhibitor, typically for 12 months in standard-risk patients'),
    ('acute_coronary_syndrome', 2, 'Parenteral anticoagulation (e.g., unfractionated heparin) during the acute phase and PCI'),
    ('acute_coronary_syndrome', 3, 'STEMI: primary PCI with first medical contact-to-device time of 90 minutes or less; fibrinolysis within 30 minutes of arrival when PCI cannot be performed within 120 minutes'),
    ('acute_coronary_syndrome', 4, 'NSTEMI/unstable angina: invasive strategy for intermediate- and high-risk patients guided by risk scores'),
    ('acute_coronary_syndrome', 5, 'Sublingual nitroglycerin for ongoing ischemic pain unless hypotension, right ventricular infarction or recent phosphodiesterase-5 inhibitor use'),
    ('acute_coronary_syndrome', 6, 'Oral beta-blocker within 24 hours in hemodynamically stable patients without heart failure or shock; high-intensity statin for all'),
    ('acute_coronary_syndrome', 7, 'ACE inhibitor (or ARB) particularly with reduced LVEF, hypertension, diabetes or chronic kidney disease; cardiac rehabilitation referral'),
    ('heart_failure', 0, 'HFrEF: combination guideline-directed medical therapy with ARNI (preferred) or ACE inhibitor/ARB, evidence-based beta-blocker (carvedilol, bisoprolol or metoprolol succinate), mineralocorticoid receptor antagonist and SGLT2 inhibitor'),
    ('heart_failure', 1, 'Loop diuretics for relief of congestion, with a thiazide added for diuretic resistance'),
    ('heart_failure', 2, 'SGLT2 inhibitors also reduce HF hospitalization in HFmrEF and HFpEF'),
    ('heart_failure', 3, 'Hydralazine-isosorbide dinitrate for self-identified African American patients or RAAS-inhibitor intolerance; ivabradine or vericiguat in selected patients'),
    ('heart_failure', 4, 'ICD for primary prevention with LVEF 35% or less despite therapy, and cardiac resynchronization for LBBB with wide QRS'),
    ('heart_failure', 5, 'Treatment of underlying causes (revascularization, valve intervention, rate or rhythm control of atrial fibrillation)'),
    ('heart_failure', 6, 'Advanced HF (stage D): inotropes, mechanical circulatory support, transplantation or palliative care'),
    ('heart_failure', 7, 'Avoidance of drugs that worsen HF: NSAIDs, non-dihydropyridine calcium channel blockers (in HFrEF) and thiazolidinediones'),
    ('ischemic_stroke', 0, 'IV thrombolysis with alteplase or tenecteplase within 4.5 hours of last known well for disabling deficits regardless of NIHSS score; selected patients up to 9 hours with advanced imaging'),
    ('ischemic_stroke', 1, 'Mechanical thrombectomy for large-vessel occlusion, within 6 hours and up to 24 hours in selected patients on imaging criteria, including some with large cores and basilar occlusion'),
    ('ischemic_stroke', 2, 'Blood pressure lowered to below 185/110 mmHg before and kept at or below 180/105 mmHg for 24 hours after thrombolysis; intensive lowering below 140 mmHg systolic is not recommended'),
    ('ischemic_stroke', 3, 'Aspirin within 24-48 hours of onset (generally deferred 24 hours after thrombolysis); short-term dual antiplatelet therapy for minor non-disabling stroke'),
    ('ischemic_stroke', 4, 'High-intensity statin; anticoagulation for atrial fibrillation typically started within days depending on infarct size'),
    ('ischemic_stroke', 5, 'Glucose kept 140-180 mg/dL, treatment of fever, swallow screening, DVT prophylaxis with intermittent pneumatic compression'),
    ('ischemic_stroke', 6, 'Stroke unit care with early multidisciplinary rehabilitation'),
    ('migraine', 0, 'Acute mild-to-moderate attacks: NSAIDs (e.g., ibuprofen 400-600 mg, naproxen, high-dose aspirin) or paracetamol'),
    ('migraine', 1, 'Moderate-to-severe attacks or NSAID failure: triptans (e.g., sumatriptan), which work best when taken early in the headache phase'),
    ('migraine', 2, 'Antiemetics (metoclopramide or prochlorperazine) for nausea and vomiting'),
    ('migraine', 3, 'Gepants (rimegepant, ubrogepant) or other options when triptans are ineffective or contraindicated'),
    ('migraine', 4, 'Prophylaxis for frequent or disabling attacks: beta-blockers (propranolol, metoprolol), topiramate, valproate, amitriptyline, venlafaxine, flunarizine or verapamil'),
    ('migraine', 5, 'CGRP monoclonal antibodies (erenumab, fremanezumab, galcanezumab) and onabotulinumtoxinA for chronic migraine'),
    ('migraine', 6, 'Limitation of acute medication days to prevent medication-overuse headache'),
    ('chikungunya', 0, 'No specific antiviral therapy; management is supportive with rest and fluids'),
    ('chikungunya', 1, 'Paracetamol for fever and pain until dengue is excluded; NSAIDs and aspirin are withheld until then because of bleeding risk'),
    ('chikungunya', 2, 'After dengue is excluded, NSAIDs may be used for arthralgia'),
    ('chikungunya', 3, 'Persistent inflammatory arthritis in the chronic phase may be treated with hydroxychloroquine or methotrexate under specialist care'),
    ('hepatitis_b', 0, 'Acute hepatitis B: supportive care; antivirals (tenofovir or entecavir) are reserved for severe acute disease'),
    ('hepatitis_b', 1, 'Chronic hepatitis B: oral tenofovir or entecavir when HBV DNA is elevated with evidence of liver inflammation; both have a high barrier to resistance'),
    ('hepatitis_b', 2, 'Antiviral therapy slows progression to cirrhosis and reduces the incidence of liver cancer; most patients need lifelong treatment'),
    ('hepatitis_b', 3, 'Surveillance for hepatocellular carcinoma with ultrasound in at-risk patients'),
    ('hepatitis_a', 0, 'No specific antiviral therapy; supportive care with rest, nutrition and hydration'),
    ('hepatitis_a', 1, 'Avoidance of unnecessary medications that can harm the liver and of alcohol; paracetamol dosing is limited'),
    ('hepatitis_a', 2, 'Severe cholestatic pruritus may be treated with cholestyramine, rifampicin or ondansetron'),
    ('hepatitis_a', 3, 'Hospitalization for severe symptoms, and urgent assessment at a center capable of liver transplantation for acute liver failure'),
    ('cholera', 0, 'Rehydration is the cornerstone: oral rehydration solution for most patients'),
    ('cholera', 1, 'Severe dehydration: intravenous fluids (e.g., Ringer''s lactate) plus ORS and antibiotics (WHO)'),
    ('cholera', 2, 'Adults (Philippine CPG): azithromycin 1 g single dose or ciprofloxacin; doxycycline 100 mg twice daily for 3 days as an alternative'),
    ('cholera', 3, 'Children (Philippine CPG): azithromycin, or doxycycline 300 mg single dose for children over 8 years; co-trimoxazole among the alternatives'),
    ('cholera', 4, 'Zinc supplementation for children older than 6 months (Philippine CPG: 20 mg/day for 10-14 days)'),
    ('cholera', 5, 'Loperamide is not recommended in acute infectious diarrhea (Philippine CPG)'),
    ('rabies', 0, 'Wound management after exposure: thorough washing with soap and water for at least 15 minutes as soon as possible, followed by virucidal irrigation if available'),
    ('rabies', 1, 'Rabies vaccine for WHO category II and III exposures; CDC intramuscular schedule on days 0, 3, 7 and 14 (plus day 28 if immunocompromised); WHO dose-sparing intradermal regimens are used widely, including at Philippine Animal Bite Treatment Centers'),
    ('rabies', 2, 'Rabies immunoglobulin (human 20 IU/kg or equine 40 IU/kg) or rabies monoclonal antibodies for category III exposures (and for immunocompromised patients with category II exposures), infiltrated into and around the wound, given no later than 7 days after the first vaccine dose'),
    ('rabies', 3, 'Previously vaccinated persons: two vaccine doses (days 0 and 3) without rabies immunoglobulin, unless immunocompromised'),
    ('rabies', 4, 'Clinical rabies: no proven curative therapy; vaccine and immunoglobulin have no role once symptoms begin. Management is supportive and palliative (sedation for agitation, anticholinergics for secretions, opioid analgesia, intravenous fluids, antipyretics)'),
    ('schistosomiasis', 0, 'Praziquantel is the treatment of choice; for S. japonicum the CDC regimen is 60 mg/kg per day orally in three divided doses for one day'),
    ('schistosomiasis', 1, 'In travelers, treatment is timed at least 6-8 weeks after the last freshwater exposure, when adult worms are mature and most susceptible'),
    ('schistosomiasis', 2, 'Repeat treatment after 2-4 weeks may be needed in lightly infected patients with persistent eggs'),
    ('schistosomiasis', 3, 'Praziquantel can be given to children from about 2 years of age, and WHO supports its use in pregnancy and lactation in mass drug administration settings'),
    ('schistosomiasis', 4, 'Management of complications of portal hypertension (variceal bleeding, ascites) follows standard hepatology and gastroenterology care'),
    ('pertussis', 0, 'Azithromycin is the preferred antibiotic for all ages, including infants under 1 month despite a small association of macrolides with infantile hypertrophic pyloric stenosis'),
    ('pertussis', 1, 'Clarithromycin is an alternative macrolide; erythromycin is generally avoided in infants under 1 month'),
    ('pertussis', 2, 'Trimethoprim-sulfamethoxazole is an alternative for macrolide intolerance or resistance in patients aged 2 months and older'),
    ('pertussis', 3, 'Antibiotics are most effective in the first 1-2 weeks; treatment is recommended within 3 weeks of cough onset for persons aged 1 year and older and within 6 weeks for infants and pregnant women, mainly to reduce transmission'),
    ('pertussis', 4, 'Treatment may start before test results when clinical suspicion is high or the patient is high risk or in contact with infants or pregnant women'),
    ('pertussis', 5, 'Supportive care with hospitalization for infants under 6 months or those with apnea, hypoxia, pneumonia or pulmonary hypertension (oxygen, suctioning, hydration and nutrition support)'),
    ('hfmd', 0, 'No specific antiviral therapy; management is supportive'),
    ('hfmd', 1, 'Paracetamol or an NSAID such as ibuprofen for fever and pain from mouth sores'),
    ('hfmd', 2, 'Maintenance of hydration with oral fluids, with IV fluids if oral intake is inadequate'),
    ('hfmd', 3, 'Topical oral analgesia; StatPearls notes that an ibuprofen/diphenhydramine gargle mixture may ease ulcer pain in older children'),
    ('hfmd', 4, 'Hospital-based supportive care for neurologic or cardiopulmonary complications of enterovirus A71'),
    ('varicella', 0, 'Oral aciclovir or valacyclovir, started ideally within 24 hours of rash onset, for healthy people older than 12 years and for those with chronic skin or lung disease, long-term salicylate therapy or corticosteroid courses (CDC); routine use in healthy children is not recommended'),
    ('varicella', 1, 'Intravenous aciclovir for severe or disseminated disease (pneumonia, encephalitis, thrombocytopenia) and for immunocompromised patients'),
    ('varicella', 2, 'Paracetamol for fever and discomfort; aspirin is avoided because of the risk of Reye syndrome'),
    ('varicella', 3, 'Antihistamines, calamine lotion and cool compresses for pruritus'),
    ('varicella', 4, 'Ibuprofen is avoided unless advised by a clinician because it may be associated with serious skin infections (NHS)'),
    ('varicella', 5, 'Antibiotic treatment of secondary bacterial skin and soft-tissue infection when present'),
    ('hiv_infection', 0, 'Lifelong antiretroviral therapy (ART) started as soon as possible after diagnosis, regardless of CD4 count or clinical stage'),
    ('hiv_infection', 1, 'Dolutegravir-based ART is WHO''s preferred first- and second-line treatment for all populations, including pregnant women and women of childbearing potential; the fixed-dose combination tenofovir + lamivudine + dolutegravir (TLD) is a standard first-line regimen; in the Philippines, TLD is the DOH''s recommended first-line ARV regimen'),
    ('hiv_infection', 2, 'Co-trimoxazole prophylaxis when CD4 is below 200 cells/mm3 to prevent Pneumocystis pneumonia, with additional protection against toxoplasmosis and some bacterial infections'),
    ('hiv_infection', 3, 'Screening for and treatment of tuberculosis; with rifampicin-based TB treatment the dolutegravir dose is given twice daily because of a drug interaction'),
    ('hiv_infection', 4, 'Diagnosis and treatment of opportunistic infections, with attention to immune reconstitution inflammatory syndrome when ART is started during a severe opportunistic infection'),
    ('hiv_infection', 5, 'Care through DOH-designated HIV treatment hubs and primary HIV care facilities, which provide ART, testing, clinical management and monitoring');
INSERT INTO public.disease_home_care (disease_id, position, content) VALUES
    ('dengue', 0, 'Adequate oral fluid intake (water, oral rehydration solution, juices) in patients managed as outpatients'),
    ('dengue', 1, 'Rest and paracetamol for fever and myalgia, without NSAIDs or aspirin'),
    ('dengue', 2, 'Daily clinical review through the critical phase for warning signs and falling platelet count'),
    ('dengue', 3, 'Mosquito net and repellent use during the febrile period to limit onward transmission via local mosquitoes'),
    ('typhoid_fever', 0, 'Maintenance of oral fluid and nutritional intake during the febrile illness'),
    ('typhoid_fever', 1, 'Paracetamol for fever and headache'),
    ('typhoid_fever', 2, 'Completion of the full prescribed antibiotic course'),
    ('typhoid_fever', 3, 'Strict hand hygiene after toilet use. Exclusion from food handling until bacterial clearance is confirmed'),
    ('leptospirosis', 0, 'Rest and adequate oral fluid intake in mild disease managed as outpatient'),
    ('leptospirosis', 1, 'Paracetamol for fever and myalgia'),
    ('leptospirosis', 2, 'Monitoring of urine output, skin/eye yellowing and breathing, with early return if these change'),
    ('leptospirosis', 3, 'Avoidance of further floodwater exposure during recovery'),
    ('tuberculosis', 0, 'Daily adherence to the full regimen without interruption, with treatment-partner support'),
