    ('tuberculosis', 2, 'Adequate nutrition to support recovery and weight regain'),
    ('tuberculosis', 3, 'Avoidance of alcohol (added hepatotoxicity) and smoking cessation'),
    ('malaria', 0, 'Completion of the full antimalarial course, with artemether-lumefantrine taken with fatty food or milk'),
    ('malaria', 1, 'Paracetamol and oral fluids for fever'),
    ('malaria', 2, 'Sleeping under an insecticide-treated net during illness to prevent onward transmission'),
    ('malaria', 3, 'Early return for persistent fever, vomiting of doses or new warning signs'),
    ('community_acquired_pneumonia', 0, 'Adequate oral fluid intake to prevent dehydration from fever and tachypnea'),
    ('community_acquired_pneumonia', 1, 'Rest and gradual return to activity as fatigue resolves'),
    ('community_acquired_pneumonia', 2, 'Antipyretic use for fever and pleuritic discomfort'),
    ('community_acquired_pneumonia', 3, 'Completion of the prescribed antibiotic course with reassessment if fever persists beyond 48-72 hours'),
    ('community_acquired_pneumonia', 4, 'Smoking cessation and avoidance of second-hand smoke during recovery'),
    ('influenza', 0, 'Rest and maintenance of oral fluid intake'),
    ('influenza', 1, 'Antipyretic/analgesic use for fever, headache and myalgia'),
    ('influenza', 2, 'Staying home and limiting contact with others while febrile to reduce transmission'),
    ('influenza', 3, 'Covering coughs and sneezes, hand hygiene and mask use around high-risk household members'),
    ('covid19', 0, 'Rest, oral hydration and antipyretics for fever and myalgia'),
    ('covid19', 1, 'Isolation from others while symptomatic, mask use and good ventilation to limit transmission'),
    ('covid19', 2, 'Home monitoring of breathing and, where available, pulse oximetry'),
    ('covid19', 3, 'Particular attention to high-risk household members'),
    ('measles', 0, 'Isolation at home away from unvaccinated persons, infants and pregnant women until 4 days after rash onset'),
    ('measles', 1, 'Maintenance of fluid and nutritional intake, including continued breastfeeding in infants'),
    ('measles', 2, 'Antipyretic use for fever'),
    ('measles', 3, 'Cleaning of eye discharge and avoidance of bright light for ocular comfort'),
    ('acute_gastroenteritis', 0, 'Frequent small volumes of oral rehydration solution matched to ongoing losses'),
    ('acute_gastroenteritis', 1, 'Early resumption of a normal diet and continued breastfeeding in infants'),
    ('acute_gastroenteritis', 2, 'Handwashing with soap and water after toilet use and before food preparation; alcohol hand rubs are less effective against norovirus'),
    ('acute_gastroenteritis', 3, 'Disinfection of contaminated surfaces with chlorine bleach solution'),
    ('acute_gastroenteritis', 4, 'Avoidance of preparing food for others while symptomatic'),
    ('urinary_tract_infection', 0, 'Adequate oral fluid intake to avoid dehydration during infection'),
    ('urinary_tract_infection', 1, 'Simple analgesia for dysuria and suprapubic discomfort'),
    ('urinary_tract_infection', 2, 'Completion of the prescribed antibiotic course and clinical review if no improvement within 48 hours'),
    ('urinary_tract_infection', 3, 'Voiding after sexual intercourse is commonly advised in recurrent UTI'),
    ('peptic_ulcer_disease', 0, 'Smoking cessation and limitation of alcohol intake'),
    ('peptic_ulcer_disease', 1, 'Avoidance of over-the-counter NSAIDs; paracetamol is the usual alternative analgesic'),
    ('peptic_ulcer_disease', 2, 'Adherence to the full course of eradication therapy'),
    ('peptic_ulcer_disease', 3, 'Recognition of bleeding warning signs such as black stools or vomiting blood'),
    ('hypertension', 0, 'Reduced salt intake and a diet rich in fruits, vegetables and low-fat dairy (DASH pattern)'),
    ('hypertension', 1, 'At least 150 minutes per week of moderate-intensity physical activity'),
    ('hypertension', 2, 'Weight reduction in overweight individuals'),
    ('hypertension', 3, 'Smoking cessation and moderation of alcohol intake'),
    ('hypertension', 4, 'Home blood pressure monitoring with a validated device'),
    ('hypertension', 5, 'Long-term adherence to prescribed antihypertensive therapy'),
    ('type2_diabetes', 0, 'Healthy eating pattern with portion control and limitation of added sugars and refined carbohydrates'),
    ('type2_diabetes', 1, 'At least 150 minutes per week of moderate-intensity physical activity'),
    ('type2_diabetes', 2, 'Weight reduction in overweight individuals'),
    ('type2_diabetes', 3, 'Smoking cessation'),
    ('type2_diabetes', 4, 'Self-monitoring of blood glucose when indicated, and recognition of hypoglycemia symptoms'),
    ('type2_diabetes', 5, 'Daily foot inspection and appropriate footwear'),
    ('asthma', 0, 'Correct inhaler technique, checked at every opportunity, with use of a spacer for pMDIs where appropriate'),
    ('asthma', 1, 'Written asthma action plan for recognizing and responding to worsening symptoms'),
    ('asthma', 2, 'Avoidance of tobacco smoke and identified allergen or occupational triggers'),
    ('asthma', 3, 'Regular physical activity'),
    ('asthma', 4, 'Up-to-date respiratory vaccinations (influenza, COVID-19, pneumococcal and others per GINA)'),
    ('copd', 0, 'Complete avoidance of tobacco smoke and reduction of indoor biomass smoke exposure (cleaner fuels, ventilation) are central supportive measures'),
    ('copd', 1, 'Regular physical activity and structured exercise training as part of pulmonary rehabilitation improve dyspnea and exercise capacity'),
    ('copd', 2, 'Correct inhaler technique and adherence to maintenance inhalers are associated with fewer exacerbations'),
    ('copd', 3, 'Breathing techniques (e.g., pursed-lip breathing) are used to ease breathlessness'),
    ('copd', 4, 'Adequate nutrition is emphasized because weight loss and muscle wasting worsen prognosis'),
    ('copd', 5, 'A written action plan for recognizing and responding early to exacerbations is part of self-management education'),
    ('acute_coronary_syndrome', 0, 'Complete smoking cessation is associated with a substantial reduction in recurrent coronary events'),
    ('acute_coronary_syndrome', 1, 'Structured cardiac rehabilitation with progressive supervised exercise is part of recovery'),
    ('acute_coronary_syndrome', 2, 'Heart-healthy diet rich in fruits and vegetables with limited saturated fat and sodium'),
    ('acute_coronary_syndrome', 3, 'Weight reduction and blood pressure, glucose and lipid control to targets'),
    ('acute_coronary_syndrome', 4, 'Limiting alcohol intake and managing psychosocial stress'),
    ('heart_failure', 0, 'Daily weight monitoring is used to detect fluid retention early'),
    ('heart_failure', 1, 'Sodium restriction is part of standard dietary counseling'),
    ('heart_failure', 2, 'Regular exercise training or cardiac rehabilitation improves functional capacity'),
    ('heart_failure', 3, 'Adherence to guideline-directed medications is linked to fewer hospitalizations'),
    ('heart_failure', 4, 'Avoidance of over-the-counter NSAIDs, which cause sodium and fluid retention'),
    ('heart_failure', 5, 'Limiting alcohol and smoking cessation'),
    ('ischemic_stroke', 0, 'Long-term rehabilitation (physiotherapy, occupational and speech therapy) supports functional recovery'),
    ('ischemic_stroke', 1, 'Blood pressure control, smoking cessation and diabetes management are core secondary-prevention measures'),
    ('ischemic_stroke', 2, 'Dietary modification, regular physical activity as tolerated and limited alcohol'),
    ('ischemic_stroke', 3, 'Swallowing strategies and positioning reduce aspiration risk in dysphagia'),
    ('ischemic_stroke', 4, 'Caregiver education on recognizing recurrent stroke symptoms (BE-FAST: balance, eyes, face, arm, speech, time)'),
    ('migraine', 0, 'Rest in a quiet, dark room during attacks is commonly used to reduce sensory stimulation'),
    ('migraine', 1, 'Regular sleep schedule, regular meals and adequate hydration are standard lifestyle measures'),
    ('migraine', 2, 'Identifying and avoiding personal triggers with the help of a headache diary'),
    ('migraine', 3, 'Regular aerobic exercise and stress-management techniques as adjunctive prevention'),
    ('migraine', 4, 'Limiting caffeine and alcohol when these act as triggers'),
    ('chikungunya', 0, 'Rest and adequate oral fluid intake during the acute febrile phase'),
    ('chikungunya', 1, 'Paracetamol for fever and joint pain, without NSAIDs or aspirin until dengue has been excluded'),
    ('chikungunya', 2, 'Mosquito nets and repellent during the febrile illness to limit bites and onward transmission'),
    ('hepatitis_b', 0, 'Rest and adequate nutrition and fluids during symptomatic acute infection'),
    ('hepatitis_b', 1, 'Abstinence from alcohol'),
    ('hepatitis_b', 2, 'Daily adherence to prescribed antiviral therapy without unsupervised interruption'),
    ('hepatitis_b', 3, 'Not sharing razors, toothbrushes or needles, and covering open cuts, to limit blood exposure of household contacts'),
    ('hepatitis_a', 0, 'Rest, a balanced diet and plenty of fluids'),
    ('hepatitis_a', 1, 'Avoidance of alcohol and of unnecessary medicines, including high doses of paracetamol'),
    ('hepatitis_a', 2, 'Careful handwashing after toilet use and before preparing food, to limit spread to household contacts'),
    ('cholera', 0, 'Oral rehydration solution started early and continued to replace ongoing losses in mild cases'),
    ('cholera', 1, 'Boiling drinking water for five minutes when its safety is uncertain, or household chlorination (DOH)'),
    ('cholera', 2, 'Handwashing with soap after toilet use and before handling food'),
    ('cholera', 3, 'Early consultation for worsening diarrhea, vomiting or signs of dehydration'),
    ('rabies', 0, 'Immediate washing of any bite or scratch with soap and running water for at least 15 minutes, before travel to an Animal Bite Treatment Center'),
    ('rabies', 1, 'Same-day presentation to an Animal Bite Treatment Center or emergency department for PEP assessment after any animal bite or scratch'),
    ('rabies', 2, 'Completion of every scheduled vaccine dose on the assigned days, with the vaccination card kept for future exposures'),
    ('schistosomiasis', 0, 'Completion of the full praziquantel dose on the treatment day, taken with food'),
    ('schistosomiasis', 1, 'Avoidance of wading, bathing, swimming or washing in streams, ponds and rice fields in endemic areas'),
    ('schistosomiasis', 2, 'Use of sanitary toilets so that feces do not reach water sources'),
    ('schistosomiasis', 3, 'Return for follow-up stool examination after treatment'),
    ('pertussis', 0, 'Completion of the full antibiotic course as prescribed'),
    ('pertussis', 1, 'Small, frequent feeds or meals, especially after coughing fits with vomiting, with attention to fluid intake'),
    ('pertussis', 2, 'Limiting close contact with infants and pregnant women while infectious, particularly before effective antibiotic therapy'),
    ('pertussis', 3, 'Avoidance of smoke and other airway irritants that may trigger paroxysms'),
    ('hfmd', 0, 'Frequent small amounts of fluid to prevent dehydration while mouth sores make swallowing painful'),
    ('hfmd', 1, 'Paracetamol for fever and oral pain at weight-appropriate doses'),
    ('hfmd', 2, 'Home isolation for 7-10 days or until the fever resolves, with absence from school or daycare (DOH)'),
    ('hfmd', 3, 'Handwashing with soap and water for at least 20 seconds, and cleaning of frequently touched surfaces and toys'),
    ('varicella', 0, 'Paracetamol for fever and discomfort, avoiding aspirin in children and adolescents'),
    ('varicella', 1, 'Antihistamine and calamine lotion or cool compresses to relieve itching and limit scratching'),
    ('varicella', 2, 'Adequate fluid intake to prevent dehydration'),
    ('varicella', 3, 'Staying home and away from newborns, pregnant women and immunocompromised people until all lesions have crusted'),
    ('hiv_infection', 0, 'Taking ART every day as prescribed; adherence is the main determinant of viral suppression'),
    ('hiv_infection', 1, 'Keeping scheduled treatment-hub visits for viral load, CD4 and medication refills'),
    ('hiv_infection', 2, 'Condom use to prevent other sexually transmitted infections; people with an undetectable viral load do not transmit HIV sexually'),
    ('hiv_infection', 3, 'Prompt reporting of new cough, fever, night sweats or weight loss for tuberculosis and opportunistic-infection evaluation');
