INSERT INTO public.disease_prevention (disease_id, position, content, tier) VALUES
    ('dengue', 0, 'DOH 4S strategy: Search and destroy mosquito breeding sites, Self-protection measures, Seek early consultation, Support fogging/spraying only in hotspot areas.', 'primary'),
    ('dengue', 1, 'Personal protection with repellents (DEET, picaridin, IR3535), long-sleeved clothing, mosquito nets and screened windows, particularly during daytime Aedes biting hours.', 'primary'),
    ('dengue', 2, 'Vaccination: WHO recommends TAK-003 (Qdenga) for ages 6-16 in high-transmission settings. CYD-TDV (Dengvaxia) is restricted to individuals with documented prior dengue infection.', 'primary'),
    ('dengue', 3, 'Early consultation and serial CBC during the febrile and critical phases so that warning signs and plasma leakage are detected before shock develops.', 'secondary'),
    ('dengue', 4, 'Fluid therapy matched to the illness phase, plus intensive care for severe dengue, to prevent prolonged shock, organ failure and fluid overload.', 'tertiary'),
    ('typhoid_fever', 0, 'Safe drinking water, adequate sanitation, food hygiene and handwashing with soap.', 'primary'),
    ('typhoid_fever', 1, 'Vaccination: single-dose typhoid conjugate vaccine (TCV) from 6 months of age (79-95% effective in the first 2 years). Older options are Vi polysaccharide (IM, age 2 years and older) and oral Ty21a vaccines.', 'primary'),
    ('typhoid_fever', 2, 'Early blood culture and appropriate antibiotic therapy for prolonged fever, plus public health follow-up of contacts and implicated food handlers.', 'secondary'),
    ('typhoid_fever', 3, 'Identification and treatment of chronic carriers, prompt surgical care of perforation, and susceptibility-guided therapy to limit resistance spread.', 'tertiary'),
    ('leptospirosis', 0, 'Avoiding wading in floodwater. Protective boots and gloves for unavoidable exposure, covering of wounds, rodent control and proper garbage disposal.', 'primary'),
    ('leptospirosis', 1, 'Doxycycline prophylaxis per the Philippine guideline: low-risk exposure 200 mg single dose within 24-72 h; moderate-risk 200 mg daily for 3-5 days; high-risk (continuous exposure) 200 mg once weekly until exposure ends.', 'primary'),
    ('leptospirosis', 2, 'Early consultation for fever after exposure, with prompt antibiotic therapy to reduce progression to severe disease.', 'secondary'),
    ('leptospirosis', 3, 'Timely dialysis and ICU support for renal failure and pulmonary hemorrhage, with follow-up of renal function after recovery.', 'tertiary'),
    ('tuberculosis', 0, 'BCG vaccination of infants, which protects young children against severe forms such as TB meningitis and miliary TB but gives limited protection in adults.', 'primary'),
    ('tuberculosis', 1, 'Airborne infection control: early case detection, ventilation, and masks for infectious patients.', 'primary'),
    ('tuberculosis', 2, 'Contact investigation, active case finding with chest radiography, and TB preventive treatment (e.g., 3HP or isoniazid regimens) for infected high-risk people.', 'secondary'),
    ('tuberculosis', 3, 'Completion of therapy under DOTS to prevent relapse, drug resistance and progressive lung damage.', 'tertiary'),
    ('malaria', 0, 'Vector control with insecticide-treated nets and indoor residual spraying, plus repellents (DEET) and permethrin-treated clothing.', 'primary'),
    ('malaria', 1, 'Chemoprophylaxis for travelers to endemic areas (atovaquone-proguanil, doxycycline or mefloquine). WHO-recommended RTS,S/AS01 and R21/Matrix-M vaccines are for children in P. falciparum endemic regions.', 'primary'),
    ('malaria', 2, 'Prompt parasitological diagnosis (microscopy or RDT) and treatment of every suspected case, plus surveillance and case investigation under the DOH Malaria Control and Elimination Program.', 'secondary'),
    ('malaria', 3, 'Radical cure of P. vivax to prevent relapse, and monitoring for post-artesunate delayed hemolysis after severe malaria.', 'tertiary'),
    ('community_acquired_pneumonia', 0, 'Pneumococcal vaccination (PCV and/or PPSV) for adults aged 50 years and above and younger adults with risk factors, together with annual influenza vaccination (PSMID 2020); COVID-19 vaccination as recommended.', 'primary'),
    ('community_acquired_pneumonia', 1, 'Smoking cessation, reduction of aspiration risk and optimal control of chronic cardiopulmonary disease and diabetes.', 'primary'),
    ('community_acquired_pneumonia', 2, 'Early clinical recognition, chest radiography and risk stratification so that empiric antibiotics are started promptly at the correct site of care.', 'secondary'),
    ('community_acquired_pneumonia', 3, 'Reassessment for clinical stability, timely treatment of complications (empyema, abscess) and post-recovery vaccination to prevent recurrence.', 'tertiary'),
    ('influenza', 0, 'Annual influenza vaccination, prioritized for older adults, pregnant women, young children, people with chronic disease and health-care workers.', 'primary'),
    ('influenza', 1, 'Respiratory hygiene, hand hygiene and staying home when ill; antiviral chemoprophylaxis for selected high-risk exposed persons and institutional outbreaks.', 'primary'),
    ('influenza', 2, 'Early testing and prompt antiviral treatment of high-risk and hospitalized patients to shorten illness and reduce complications.', 'secondary'),
    ('influenza', 3, 'Monitoring for and early treatment of secondary bacterial pneumonia and decompensation of chronic diseases.', 'tertiary'),
    ('covid19', 0, 'COVID-19 vaccination with revaccination for high-risk groups per national and WHO recommendations.', 'primary'),
    ('covid19', 1, 'Masks in crowded settings, hand hygiene, improved indoor ventilation and staying home when symptomatic.', 'primary'),
    ('covid19', 2, 'Early testing of symptomatic persons and prompt nirmatrelvir-ritonavir for high-risk patients within 5 days of onset.', 'secondary'),
    ('covid19', 3, 'Thromboprophylaxis and corticosteroids in hospitalized severe disease; rehabilitation and follow-up for post-COVID-19 condition.', 'tertiary'),
    ('measles', 0, 'Two doses of measles-containing vaccine; in the Philippines MCV1 is given at 9 months and MCV2 at 12 months, with vaccination from 6 months of age during outbreaks.', 'primary'),
    ('measles', 1, 'Post-exposure prophylaxis for susceptible contacts: measles vaccine within 72 hours of exposure, or immune globulin within 6 days for those who cannot be vaccinated (infants, pregnant, immunocompromised).', 'primary'),
    ('measles', 2, 'Early case recognition, laboratory confirmation, prompt vitamin A and airborne isolation to limit spread and complications.', 'secondary'),
    ('measles', 3, 'Management of pneumonia, diarrhea and eye complications, nutritional rehabilitation, and awareness of long-term immune amnesia and SSPE.', 'tertiary'),
    ('acute_gastroenteritis', 0, 'Safe drinking water, improved sanitation, handwashing with soap and safe food handling.', 'primary'),
    ('acute_gastroenteritis', 1, 'Rotavirus vaccination in infants, exclusive breastfeeding for the first 6 months, and oral cholera vaccine in outbreak or high-risk settings.', 'primary'),
    ('acute_gastroenteritis', 2, 'Early oral rehydration at the onset of diarrhea and prompt recognition of dehydration and dysentery.', 'secondary'),
    ('acute_gastroenteritis', 3, 'Targeted stool testing and pathogen-directed therapy, monitoring for hemolytic uremic syndrome after STEC, and recognition of post-infectious complications such as reactive arthritis and Guillain-Barre syndrome after Campylobacter.', 'tertiary'),
    ('urinary_tract_infection', 0, 'Adequate fluid intake, post-coital voiding, avoidance of spermicides in women with recurrent infection, and minimizing unnecessary urinary catheter use.', 'primary'),
    ('urinary_tract_infection', 1, 'Early urine testing and prompt treatment of symptomatic infection; screening and treatment of asymptomatic bacteriuria in pregnancy to prevent pyelonephritis.', 'secondary'),
    ('urinary_tract_infection', 2, 'For recurrent UTI: vaginal estrogen in postmenopausal women, cranberry products or D-mannose (modest evidence), and low-dose antibiotic prophylaxis in selected patients; correction of anatomical or functional abnormalities.', 'tertiary'),
    ('peptic_ulcer_disease', 0, 'Avoidance of unnecessary NSAID use; PPI co-therapy for high-risk patients who require NSAIDs or low-dose aspirin; testing for and treating H. pylori in appropriate patients.', 'primary'),
    ('peptic_ulcer_disease', 1, 'Endoscopic evaluation of dyspepsia with alarm features, and H. pylori test-and-treat in dyspeptic patients.', 'secondary'),
    ('peptic_ulcer_disease', 2, 'Confirmation of H. pylori eradication, long-term PPI co-therapy when antiplatelet or anticoagulant therapy must continue after ulcer bleeding, and follow-up endoscopy of selected gastric ulcers.', 'tertiary'),
    ('hypertension', 0, 'Population-wide salt reduction, healthy diet, regular physical activity, healthy body weight, and avoidance of tobacco and harmful alcohol use.', 'primary'),
    ('hypertension', 1, 'Regular blood pressure screening of adults to detect the large proportion of people unaware of their hypertension, with confirmation by repeated or out-of-office readings.', 'secondary'),
    ('hypertension', 2, 'Sustained BP control to target, management of coexisting cardiovascular risk factors (diabetes, dyslipidemia, smoking), and monitoring for target-organ damage to prevent stroke, heart failure and kidney disease.', 'tertiary'),
    ('type2_diabetes', 0, 'Maintenance of healthy weight, regular physical activity and healthy diet; structured lifestyle programs in people with prediabetes can prevent or delay type 2 diabetes.', 'primary'),
    ('type2_diabetes', 1, 'Screening of at-risk adults (e.g., overweight adults with risk factors, adults 35 years or older) with HbA1c, fasting glucose or OGTT for early detection.', 'secondary'),
    ('type2_diabetes', 2, 'Glycemic, blood pressure and lipid control, and regular screening of eyes, kidneys and feet to prevent or slow retinopathy, nephropathy, neuropathy, amputation and cardiovascular events.', 'tertiary'),
    ('asthma', 0, 'Avoidance of tobacco smoke exposure in pregnancy and early life, reduction of air pollution exposure, and control of occupational sensitizer exposure.', 'primary'),
    ('asthma', 1, 'Early objective diagnosis with spirometry in people with recurrent wheeze, cough or dyspnea, and early initiation of ICS-containing therapy.', 'secondary'),
    ('asthma', 2, 'Regular ICS-containing controller or anti-inflammatory reliever therapy, trigger avoidance, written action plans, vaccination and prompt treatment of exacerbations to prevent severe attacks and airway remodeling.', 'tertiary'),
    ('copd', 0, 'Tobacco control, prevention of smoking initiation, clean household fuels and ventilation, occupational dust and fume controls, and reduction of ambient air pollution.', 'primary'),
    ('copd', 1, 'Spirometry in adults over 35-40 with risk exposures and chronic respiratory symptoms to detect airflow limitation early, followed by smoking cessation.', 'secondary'),
    ('copd', 2, 'Vaccination, optimized inhaled therapy, pulmonary rehabilitation, long-term oxygen when indicated, and early treatment of exacerbations to reduce hospitalization and mortality.', 'tertiary'),
    ('acute_coronary_syndrome', 0, 'Population measures against tobacco use, unhealthy diet, physical inactivity and harmful alcohol use; detection and treatment of hypertension, diabetes and dyslipidemia.', 'primary'),
    ('acute_coronary_syndrome', 1, 'Rapid recognition of ischemic symptoms, early ECG and troponin testing, and timely reperfusion to limit infarct size.', 'secondary'),
    ('acute_coronary_syndrome', 2, 'Long-term antiplatelet therapy, high-intensity statin, beta-blocker and RAAS inhibition where indicated, cardiac rehabilitation and risk-factor control to prevent reinfarction, heart failure and death.', 'tertiary'),
    ('heart_failure', 0, 'Control of hypertension, diabetes, obesity and coronary risk factors in at-risk (stage A) individuals; SGLT2 inhibitors in type 2 diabetes with cardiovascular risk; avoidance or monitoring of cardiotoxins.', 'primary'),
    ('heart_failure', 1, 'ACE inhibitor and beta-blocker in asymptomatic LV dysfunction (stage B), statin and beta-blocker after MI, and ICD when LVEF is 30% or less, to prevent progression to symptomatic HF.', 'secondary'),
    ('heart_failure', 2, 'Full guideline-directed medical therapy, device therapy, patient education and early post-discharge follow-up to reduce readmission and mortality.', 'tertiary'),
    ('ischemic_stroke', 0, 'Control of hypertension, diabetes and dyslipidemia, smoking cessation, physical activity, and anticoagulation for atrial fibrillation according to stroke risk.', 'primary'),
    ('ischemic_stroke', 1, 'Rapid public recognition of stroke symptoms and emergency transport to stroke-capable centers enabling thrombolysis or thrombectomy; urgent evaluation of transient ischemic attack.', 'secondary'),
    ('ischemic_stroke', 2, 'Antiplatelet or anticoagulant therapy by etiology, high-intensity statin, blood pressure control, carotid revascularization when indicated, rehabilitation and prevention of complications (aspiration, DVT, depression).', 'tertiary'),
    ('migraine', 0, 'No proven primary prevention of the disorder itself; attack prevention focuses on trigger management, regular sleep and meals, and stress reduction.', 'primary'),
    ('migraine', 1, 'Accurate early diagnosis with ICHD-3 criteria and prompt effective acute treatment to reduce disability and prevent progression.', 'secondary'),
    ('migraine', 2, 'Preventive medication for frequent or disabling migraine and avoidance of acute medication overuse to prevent chronic migraine and medication-overuse headache.', 'tertiary'),
    ('chikungunya', 0, 'Reduction of Aedes breeding sites (removal of containers holding standing water) and community vector control.', 'primary'),
    ('chikungunya', 1, 'Personal protection with repellents (DEET, IR3535 or icaridin), protective clothing and window screens, particularly during daytime biting hours.', 'primary'),
    ('chikungunya', 2, 'Two chikungunya vaccines have received regulatory approval, but availability and use remain limited (WHO).', 'primary'),
    ('chikungunya', 3, 'Early laboratory confirmation with concurrent dengue testing, so that NSAIDs and aspirin are withheld until dengue is excluded.', 'secondary'),
    ('chikungunya', 4, 'Follow-up of persistent joint symptoms and specialist management of chronic inflammatory arthritis (e.g., hydroxychloroquine or methotrexate).', 'tertiary'),
    ('hepatitis_b', 0, 'Hepatitis B vaccination of all infants as soon as possible after birth (within 24 hours), followed by further doses; protection lasts at least 20 years and probably lifelong (WHO). Philippine law has required a hepatitis B birth dose within 24 hours since 2011.', 'primary'),
    ('hepatitis_b', 1, 'Screening of donated blood, safe injection practices and safer sex.', 'primary'),
    ('hepatitis_b', 2, 'HBsAg testing of pregnant women to identify infection and prevent mother-to-child transmission (WHO).', 'secondary'),
    ('hepatitis_b', 3, 'Testing of people at higher risk so that chronic infection is found before complications develop.', 'secondary'),
    ('hepatitis_b', 4, 'Long-term tenofovir or entecavir therapy to slow progression to cirrhosis and reduce hepatocellular carcinoma.', 'tertiary'),
    ('hepatitis_b', 5, 'Ultrasound surveillance for hepatocellular carcinoma in patients with chronic infection at risk.', 'tertiary'),
    ('hepatitis_a', 0, 'Safe drinking water, proper sewage disposal and handwashing (WHO).', 'primary'),
    ('hepatitis_a', 1, 'Hepatitis A vaccination with inactivated injectable vaccines; no vaccine is approved for children under 1 year (WHO).', 'primary'),
    ('hepatitis_a', 2, 'Safer sex practices to reduce sexual transmission.', 'primary'),
    ('hepatitis_a', 3, 'Post-exposure prophylaxis with hepatitis A vaccine or immune globulin within 2 weeks of exposure for close contacts (CDC).', 'secondary'),
    ('hepatitis_a', 4, 'Monitoring for relapsing or cholestatic courses and early recognition of acute liver failure, with avoidance of alcohol and hepatotoxic drugs during recovery.', 'tertiary'),
    ('cholera', 0, 'Access to safe water, basic sanitation and hygiene (WASH), the essential measure against cholera (WHO).', 'primary'),
    ('cholera', 1, 'Household water treatment (boiling for five minutes, chlorine or water purification tablets), regular cleaning of storage tanks, washing of fruits and vegetables with clean water and avoidance of street-vended food (DOH).', 'primary'),
    ('cholera', 2, 'Oral cholera vaccines (WHO-prequalified Dukoral, Euvichol-Plus and Euvichol-S) used in outbreak and mass vaccination campaigns.', 'primary'),
    ('cholera', 3, 'Early detection through stool culture or rapid tests and surveillance of acute watery diarrhea clusters, with early ORS for cases.', 'secondary'),
    ('cholera', 4, 'Prompt, aggressive rehydration with frequent reassessment and antibiotics for severe cases to prevent death from hypovolemic shock and kidney injury.', 'tertiary'),
    ('rabies', 0, 'Mass dog vaccination, including puppies, is the most cost-effective strategy for preventing human rabies because it stops transmission at its source (WHO). The DOH program targets elimination of human rabies by 2027 and a rabies-free Philippines by 2030.', 'primary'),
    ('rabies', 1, 'Public education on dog behaviour and bite prevention, what to do after a bite or scratch, and responsible pet ownership.', 'primary'),
    ('rabies', 2, 'Pre-exposure prophylaxis with rabies vaccine for people at high occupational risk and for those living in remote endemic areas with limited access to PEP.', 'primary'),
    ('rabies', 3, 'Post-exposure prophylaxis by WHO category: category I (touching or feeding animals, licks on intact skin) needs wound washing only; category II (nibbling of uncovered skin, minor scratches or abrasions without bleeding) needs wound washing and immediate vaccination; category III (transdermal bites or scratches, saliva contact with mucous membranes or broken skin, direct bat contact) needs wound washing, vaccination and rabies immunoglobulin or monoclonal antibodies.', 'secondary'),
    ('rabies', 4, 'PEP delivered through government Animal Bite Treatment Centers run by the DOH and local government units under the Anti-Rabies Act of 2007 (RA 9482), with PhilHealth coverage for category II and III exposures.', 'secondary'),
    ('rabies', 5, 'Once symptoms emerge, WHO recommends comprehensive and compassionate palliative care, including sedation, analgesia, hydration and management of secretions.', 'tertiary'),
    ('schistosomiasis', 0, 'Access to safe water, improved sanitation (toilets) and hygiene education to interrupt contamination of freshwater with eggs (WHO WASH strategy).', 'primary'),
    ('schistosomiasis', 1, 'One Health snail control (habitat modification such as weed clearance, and molluscicides) together with management of infected animal reservoir hosts such as carabao.', 'primary'),
    ('schistosomiasis', 2, 'Avoiding contact with infested freshwater in endemic areas, especially for school-aged children who swim or fish.', 'primary'),
    ('schistosomiasis', 3, 'Large-scale preventive chemotherapy (mass drug administration) with praziquantel for preschool-aged children, school-aged children and at-risk adults in endemic areas, repeated yearly in high-transmission areas; in the Philippines, control under the DOH Schistosomiasis Control and Elimination Program has centered on preventive chemotherapy with praziquantel.', 'secondary'),
    ('schistosomiasis', 4, 'Stool surveillance (Kato-Katz) in endemic barangays to detect and treat infected persons before hepatosplenic disease develops.', 'secondary'),
    ('schistosomiasis', 5, 'Treatment reverses anemia, stunting and reduced learning ability in children; ultrasound follow-up and management of portal hypertension complications limit morbidity in advanced disease.', 'tertiary'),
    ('pertussis', 0, 'Routine infant vaccination with a DTP-containing vaccine (the pentavalent DPT-HepB-Hib vaccine of the Philippine Expanded Program on Immunization) as a 3-dose primary series at 6, 10 and 14 weeks, with DTP boosters at 12-18 months and 4-6 years and Tdap at 7-18 years (PIDSP 2026 schedule; PIDS 2022 EPI assessment).', 'primary'),
    ('pertussis', 1, 'Maternal Tdap vaccination at 27-36 weeks of gestation in each pregnancy, which reduces pertussis hospitalization in early infancy by more than 90% and deaths by about 95%.', 'primary'),
    ('pertussis', 2, 'Antibiotic post-exposure prophylaxis (same macrolide regimens as treatment) for household contacts and high-risk contacts such as infants, pregnant women and immunocompromised persons, ideally within 21 days of the index case''s cough onset.', 'secondary'),
    ('pertussis', 3, 'Early testing and antibiotic treatment of suspected cases, with droplet precautions, to limit spread to infants and other vulnerable contacts.', 'secondary'),
    ('pertussis', 4, 'Hospital care for high-risk infants with monitoring for apnea and hypoxia and management of complications such as pneumonia, seizures and pulmonary hypertension.', 'tertiary'),
    ('hfmd', 0, 'Handwashing with soap and water for at least 20 seconds has been shown to reduce HFMD transmission (StatPearls, CDC, DOH).', 'primary'),
    ('hfmd', 1, 'Cleaning and disinfection of frequently touched surfaces, and avoidance of close contact with infected persons.', 'primary'),
    ('hfmd', 2, 'Strain-specific inactivated enterovirus A71 vaccines are approved in China (about 94.7% efficacy over roughly 2 years); no HFMD vaccine is in routine use in the Philippines.', 'primary'),
    ('hfmd', 3, 'Early recognition and home isolation of cases for 7-10 days or until afebrile to limit spread in schools and daycare centers during outbreaks.', 'secondary'),
    ('hfmd', 4, 'Close monitoring of hydration and neurologic status, with early hospital referral for dehydration or signs of meningitis, encephalitis or cardiopulmonary involvement.', 'tertiary'),
    ('varicella', 0, 'Two doses of varicella vaccine for children, adolescents and adults without evidence of immunity (CDC); vaccination prevents about 70-90% of infections and most severe disease.', 'primary'),
    ('varicella', 1, 'Post-exposure vaccination of susceptible contacts within 3-5 days (72-120 hours) of exposure can prevent or modify disease.', 'primary'),
    ('varicella', 2, 'Varicella-zoster immune globulin (VariZIG) within 10 days of exposure for high-risk contacts who cannot be vaccinated, such as immunocompromised people, susceptible pregnant women and exposed newborns.', 'primary'),
    ('varicella', 3, 'Isolation of cases from 1-2 days before rash onset until all lesions have crusted, and early antiviral treatment within 24 hours in those at risk of severe disease.', 'secondary'),
    ('varicella', 4, 'Early recognition and treatment of complications, including bacterial skin and soft-tissue infection, varicella pneumonia, encephalitis and cerebellar ataxia.', 'tertiary'),
    ('hiv_infection', 0, 'Correct and consistent condom use, pre-exposure prophylaxis (PrEP) for people at ongoing risk, and post-exposure prophylaxis (PEP) started promptly after a possible exposure.', 'primary'),
    ('hiv_infection', 1, 'Voluntary medical male circumcision, and harm-reduction services such as sterile injecting equipment for people who inject drugs.', 'primary'),
    ('hiv_infection', 2, 'Prevention of mother-to-child transmission through HIV testing in pregnancy and ART for pregnant and breastfeeding women with HIV.', 'primary'),
    ('hiv_infection', 3, 'Expanded HIV testing, including rapid tests and self-testing, with same-day or rapid ART initiation; viral suppression on ART also prevents onward sexual transmission (undetectable = untransmittable).', 'secondary'),
    ('hiv_infection', 4, 'Co-trimoxazole prophylaxis at CD4 below 200 cells/mm3, routine TB screening and TB preventive treatment, and viral load monitoring to prevent opportunistic infections and AIDS-related deaths.', 'tertiary');
INSERT INTO public.disease_differentials (disease_id, position, condition, distinguishing_feature) VALUES
    ('dengue', 0, 'Chikungunya', 'Arthralgia more prominent. Bleeding and marked thrombocytopenia are relatively more specific for dengue'),
    ('dengue', 1, 'Leptospirosis', 'Floodwater or animal-urine exposure, conjunctival suffusion, calf tenderness, jaundice and acute kidney injury'),
    ('dengue', 2, 'Typhoid fever', 'Stepwise, prolonged fever with abdominal symptoms. Blood culture positive for Salmonella Typhi'),
    ('dengue', 3, 'Malaria', 'Exposure in an endemic area (e.g., Palawan), paroxysmal fever with rigors. Positive blood smear or RDT'),
    ('dengue', 4, 'Measles', 'Cough, coryza, conjunctivitis and Koplik spots preceding a cephalocaudal maculopapular rash'),
    ('dengue', 5, 'COVID-19 / influenza', 'Respiratory symptoms predominate. Confirmed by viral testing'),
    ('typhoid_fever', 0, 'Malaria', 'Paroxysmal fever with rigors after exposure in an endemic area. Parasites on smear or positive RDT'),
    ('typhoid_fever', 1, 'Dengue', 'Abrupt high fever with retro-orbital pain, thrombocytopenia and hemoconcentration. Incubation of 10 days or less'),
    ('typhoid_fever', 2, 'Leptospirosis', 'Floodwater or animal exposure, conjunctival suffusion, calf tenderness, jaundice with acute kidney injury'),
    ('typhoid_fever', 3, 'Scrub typhus / murine typhus', 'Eschar (scrub typhus), rural/vegetation or rodent-flea exposure. Responds to doxycycline'),
    ('typhoid_fever', 4, 'Viral hepatitis', 'Jaundice with markedly raised transaminases. Fever typically settles as jaundice appears'),
    ('typhoid_fever', 5, 'Acute gastroenteritis', 'Diarrhea-dominant, short illness without prolonged stepwise fever or bacteremia'),
    ('leptospirosis', 0, 'Dengue', 'Retro-orbital pain, hemoconcentration with thrombocytopenia and plasma leakage. Acute kidney injury and prominent calf tenderness are uncommon'),
    ('leptospirosis', 1, 'Malaria', 'Cyclic fever with rigors after exposure in an endemic area. Parasites on blood smear'),
    ('leptospirosis', 2, 'Typhoid fever', 'Gradual stepwise fever with abdominal symptoms. Salmonella Typhi on blood culture'),
    ('leptospirosis', 3, 'Viral hepatitis', 'Transaminases markedly elevated relative to bilirubin. Myalgia, conjunctival suffusion and AKI usually absent'),
    ('leptospirosis', 4, 'Influenza', 'Prominent respiratory symptoms. No jaundice or renal involvement'),
    ('leptospirosis', 5, 'Scrub typhus', 'Eschar at the chigger bite site and regional lymphadenopathy'),
    ('tuberculosis', 0, 'Community-acquired pneumonia', 'Acute onset over days with lobar consolidation and response to standard antibiotics'),
    ('tuberculosis', 1, 'Lung cancer', 'Older smoker, mass lesion, negative mycobacterial studies. Diagnosed by tissue biopsy'),
    ('tuberculosis', 2, 'COPD', 'Chronic progressive dyspnea with obstructive spirometry, usually without fever or cavitation'),
    ('tuberculosis', 3, 'Nontuberculous mycobacterial lung disease', 'Acid-fast bacilli present, but molecular testing or culture speciation is negative for M. tuberculosis'),
    ('tuberculosis', 4, 'COVID-19', 'Acute course with anosmia or viral symptoms. Positive SARS-CoV-2 test'),
    ('malaria', 0, 'Dengue', 'Retro-orbital pain, rash, hemoconcentration with thrombocytopenia. Negative smear/RDT, positive NS1'),
    ('malaria', 1, 'Typhoid fever', 'Stepwise sustained fever with abdominal symptoms. Salmonella Typhi on blood culture'),
    ('malaria', 2, 'Leptospirosis', 'Floodwater exposure, conjunctival suffusion, calf tenderness, AKI with jaundice. Negative smear'),
    ('malaria', 3, 'Bacterial sepsis / meningitis', 'Focal source or meningeal signs. Positive blood or CSF culture, no parasites'),
    ('malaria', 4, 'Influenza', 'Respiratory symptoms predominate, with no hemolysis or parasitemia'),
    ('malaria', 5, 'Scrub typhus', 'Eschar and lymphadenopathy. Responds to doxycycline'),
    ('community_acquired_pneumonia', 0, 'Pulmonary tuberculosis', 'Subacute cough over 2 weeks with weight loss, night sweats and upper-lobe or cavitary lesions; highly relevant in the Philippines'),
    ('community_acquired_pneumonia', 1, 'Acute bronchitis', 'Cough without focal chest signs or new infiltrate on chest radiograph'),
    ('community_acquired_pneumonia', 2, 'Congestive heart failure', 'Orthopnea, edema, raised JVP, bilateral interstitial/alveolar edema and cardiomegaly rather than focal consolidation'),
    ('community_acquired_pneumonia', 3, 'Pulmonary embolism', 'Sudden dyspnea and pleuritic pain with risk factors for thrombosis, often with a clear chest radiograph'),
    ('community_acquired_pneumonia', 4, 'COVID-19 or influenza viral pneumonia', 'Bilateral ground-glass or interstitial pattern and positive viral testing'),
    ('community_acquired_pneumonia', 5, 'Lung malignancy with post-obstructive pneumonia', 'Recurrent or non-resolving infiltrate in the same lobe, smoking history, weight loss'),
    ('influenza', 0, 'COVID-19', 'Clinically overlapping; loss of smell or taste favors COVID-19 and laboratory testing is needed to distinguish them'),
    ('influenza', 1, 'Dengue', 'Retro-orbital pain, rash, leukopenia and falling platelets with minimal respiratory symptoms; common in the Philippines'),
    ('influenza', 2, 'Common cold (rhinovirus and other viruses)', 'Gradual onset, prominent nasal symptoms, low or no fever and mild systemic symptoms'),
    ('influenza', 3, 'Bacterial community-acquired pneumonia', 'Productive cough, focal chest signs and lobar consolidation on chest radiograph'),
    ('influenza', 4, 'Leptospirosis', 'Flood or animal-urine exposure, calf muscle tenderness and conjunctival suffusion'),
    ('covid19', 0, 'Influenza', 'Very similar presentation; distinguished by laboratory testing, loss of smell or taste favors COVID-19'),
    ('covid19', 1, 'Bacterial community-acquired pneumonia', 'Purulent sputum and focal lobar consolidation rather than bilateral peripheral ground-glass opacities'),
    ('covid19', 2, 'Dengue', 'Retro-orbital pain, rash, bleeding tendency and thrombocytopenia with little respiratory involvement'),
    ('covid19', 3, 'Pulmonary embolism', 'Sudden pleuritic pain and dyspnea with thrombotic risk factors; also a complication of COVID-19'),
    ('covid19', 4, 'Acute heart failure', 'Orthopnea, edema, cardiomegaly and response to diuresis'),
    ('measles', 0, 'Rubella', 'Milder illness with postauricular and suboccipital lymphadenopathy, low fever, no Koplik spots'),
    ('measles', 1, 'Dengue', 'Retro-orbital pain, bleeding manifestations and thrombocytopenia; lacks the 3 Cs and Koplik spots'),
    ('measles', 2, 'Kawasaki disease', 'Young children with fever of 5 days or more, strawberry tongue, cracked lips, extremity changes, nonexudative conjunctivitis'),
    ('measles', 3, 'Scarlet fever', 'Exudative pharyngitis with a fine sandpaper-like rash and circumoral pallor'),
    ('measles', 4, 'Meningococcemia', 'Rapidly progressive petechial or purpuric rash with signs of sepsis'),
    ('measles', 5, 'Drug eruption', 'Recent new drug exposure, no respiratory prodrome or Koplik spots'),
    ('acute_gastroenteritis', 0, 'Typhoid fever', 'Stepwise sustained fever, relative bradycardia, abdominal pain and constipation as often as diarrhea'),
    ('acute_gastroenteritis', 1, 'Acute appendicitis', 'Periumbilical pain migrating to the right lower quadrant with localized tenderness; diarrhea is minimal'),
    ('acute_gastroenteritis', 2, 'Clostridioides difficile infection', 'Recent antibiotic use or hospitalization; positive C. difficile toxin/PCR'),
    ('acute_gastroenteritis', 3, 'Inflammatory bowel disease', 'Chronic or relapsing bloody diarrhea, weight loss and extraintestinal features'),
    ('acute_gastroenteritis', 4, 'Dengue', 'High fever with myalgia, retro-orbital pain and thrombocytopenia; abdominal pain and vomiting can be warning signs'),
    ('acute_gastroenteritis', 5, 'Leptospirosis', 'Flood exposure, calf tenderness, conjunctival suffusion, and possible jaundice or renal failure'),
    ('urinary_tract_infection', 0, 'Vaginitis', 'Vaginal discharge, odor or itching with external dysuria; frequency and urgency are less prominent'),
    ('urinary_tract_infection', 1, 'Urethritis / sexually transmitted infection', 'Urethral or vaginal discharge, new sexual partner; pyuria with negative routine urine culture'),
    ('urinary_tract_infection', 2, 'Nephrolithiasis', 'Colicky flank-to-groin pain with hematuria, often without fever or pyuria unless infected'),
    ('urinary_tract_infection', 3, 'Acute prostatitis', 'Men with perineal or pelvic pain, obstructive voiding symptoms and a tender prostate'),
    ('urinary_tract_infection', 4, 'Overactive bladder / interstitial cystitis (bladder pain syndrome)', 'Chronic frequency, urgency or bladder pain with sterile urine and no pyuria'),
    ('peptic_ulcer_disease', 0, 'Gastroesophageal reflux disease', 'Retrosternal heartburn and regurgitation, often postural; endoscopy shows esophagitis rather than ulcer'),
    ('peptic_ulcer_disease', 1, 'Gastritis / functional dyspepsia', 'Similar dyspepsia but no mucosal break on endoscopy'),
    ('peptic_ulcer_disease', 2, 'Gastric cancer', 'Older age, weight loss, anemia, early satiety; malignant histology on ulcer biopsy'),
    ('peptic_ulcer_disease', 3, 'Acute pancreatitis', 'Severe epigastric pain radiating to the back with elevated serum lipase or amylase'),
    ('peptic_ulcer_disease', 4, 'Acute coronary syndrome (inferior myocardial ischemia)', 'Epigastric discomfort with cardiovascular risk factors, ischemic ECG changes and elevated troponin'),
    ('peptic_ulcer_disease', 5, 'Biliary colic / cholecystitis', 'Right upper quadrant pain after fatty meals, Murphy sign and gallstones on ultrasound'),
    ('hypertension', 0, 'White-coat hypertension', 'Elevated office readings with normal home or ambulatory blood pressure'),
    ('hypertension', 1, 'Secondary hypertension (e.g., primary aldosteronism, renovascular disease, pheochromocytoma, obstructive sleep apnea)', 'Young or abrupt onset, resistant hypertension, unprovoked hypokalemia, episodic symptoms or suggestive clinical features'),
    ('hypertension', 2, 'Drug-induced hypertension', 'Temporal association with NSAIDs, corticosteroids, decongestants or other pressor agents'),
    ('hypertension', 3, 'Transient elevation from pain or anxiety', 'Resolves when the provoking stimulus is removed; normal repeat readings'),
    ('type2_diabetes', 0, 'Type 1 diabetes / latent autoimmune diabetes in adults', 'Often leaner, prone to ketosis, positive islet autoantibodies and low C-peptide'),
    ('type2_diabetes', 1, 'Drug-induced hyperglycemia', 'Temporal relation to glucocorticoids, antipsychotics or other diabetogenic drugs'),
    ('type2_diabetes', 2, 'Endocrinopathies (Cushing syndrome, acromegaly, hyperthyroidism)', 'Accompanying hormonal features such as cushingoid habitus or acral growth'),
    ('type2_diabetes', 3, 'Pancreatogenic diabetes (chronic pancreatitis, cystic fibrosis, hemochromatosis)', 'History of pancreatic disease, steatorrhea or iron overload'),
    ('type2_diabetes', 4, 'Monogenic diabetes (MODY)', 'Young onset, strong autosomal dominant family history, often without obesity'),
    ('asthma', 0, 'Chronic obstructive pulmonary disease', 'Older smoker or exposure history, progressive dyspnea and post-bronchodilator airflow limitation that is not fully reversible'),
    ('asthma', 1, 'Heart failure', 'Orthopnea, peripheral edema, basal crackles, elevated natriuretic peptides and cardiac dysfunction on echocardiography'),
    ('asthma', 2, 'Vocal cord dysfunction (inducible laryngeal obstruction)', 'Inspiratory stridor and throat tightness with normal lung function between episodes'),
    ('asthma', 3, 'Bronchiectasis', 'Chronic daily purulent sputum and recurrent chest infections; dilated airways on CT'),
    ('asthma', 4, 'Foreign body aspiration', 'Sudden onset after choking episode with localized, often unilateral wheeze'),
    ('asthma', 5, 'Community-acquired pneumonia', 'Fever, focal crackles and consolidation on chest radiograph'),
    ('copd', 0, 'Bronchial asthma', 'Earlier onset, variable symptoms, marked bronchodilator reversibility and often atopy; airflow limitation is largely reversible between episodes.'),
    ('copd', 1, 'Heart failure', 'Orthopnea, paroxysmal nocturnal dyspnea, basal crackles, raised natriuretic peptides and reduced or abnormal ventricular function on echocardiography; spirometry usually shows restriction rather than obstruction.'),
    ('copd', 2, 'Bronchiectasis', 'Large volumes of purulent sputum, recurrent infections and dilated, thickened bronchi on high-resolution CT.'),
    ('copd', 3, 'Pulmonary tuberculosis', 'Fever, night sweats, weight loss, hemoptysis, upper-lobe infiltrates or cavitation, and positive sputum microbiology.'),
    ('copd', 4, 'Interstitial lung disease', 'Fine inspiratory crackles, restrictive spirometry with reduced diffusing capacity, and reticular or fibrotic changes on CT.'),
    ('acute_coronary_syndrome', 0, 'Aortic dissection', 'Abrupt tearing pain radiating to the back, pulse or blood pressure differential between arms, widened mediastinum; confirmed by CT angiography.'),
    ('acute_coronary_syndrome', 1, 'Pulmonary embolism', 'Pleuritic pain, dyspnea and tachycardia with DVT risk factors; hypoxemia and filling defects on CT pulmonary angiography.'),
    ('acute_coronary_syndrome', 2, 'Acute pericarditis', 'Sharp pain relieved by sitting forward, pericardial friction rub, diffuse concave ST elevation with PR depression.'),
    ('acute_coronary_syndrome', 3, 'Gastroesophageal reflux disease / peptic ulcer disease', 'Burning pain related to meals or lying down, relieved by antacids, with normal ECG and troponin.'),
    ('acute_coronary_syndrome', 4, 'Costochondritis', 'Pain reproducible by palpation of costochondral junctions, normal ECG and troponin.'),
    ('acute_coronary_syndrome', 5, 'Takotsubo cardiomyopathy', 'Often follows emotional or physical stress; apical ballooning without obstructive coronary disease on angiography.'),
    ('heart_failure', 0, 'Chronic obstructive pulmonary disease', 'Smoking or biomass exposure history, obstructive spirometry, hyperinflation on chest radiograph; natriuretic peptides not markedly raised.'),
    ('heart_failure', 1, 'Acute coronary syndrome', 'Ischemic chest pain with dynamic ECG changes and rising troponin; may precipitate acute HF.'),
    ('heart_failure', 2, 'Pulmonary embolism', 'Sudden dyspnea, pleuritic pain, tachycardia and hypoxemia with clear lung fields; filling defects on CT pulmonary angiography.'),
    ('heart_failure', 3, 'Nephrotic syndrome or renal failure', 'Heavy proteinuria and hypoalbuminemia or markedly raised creatinine with normal cardiac function.'),
    ('heart_failure', 4, 'Liver cirrhosis', 'Ascites, jaundice, stigmata of chronic liver disease and low albumin without jugular venous distension.'),
    ('heart_failure', 5, 'Community-acquired pneumonia', 'Fever, productive cough and focal consolidation on chest radiograph.'),
    ('ischemic_stroke', 0, 'Intracerebral hemorrhage', 'Often severe headache, vomiting and rapidly reduced consciousness; hyperdense blood on non-contrast CT.'),
    ('ischemic_stroke', 1, 'Hypoglycemia', 'Low fingerstick glucose with deficits that resolve after glucose correction.'),
    ('ischemic_stroke', 2, 'Migraine with aura (complicated migraine)', 'Gradually spreading positive symptoms (scintillations, tingling) over 5 minutes or more, followed by headache, with full reversal; history of similar attacks.'),
    ('ischemic_stroke', 3, 'Seizure with postictal (Todd) paralysis', 'Witnessed seizure activity and transient postictal weakness that resolves within hours.'),
    ('ischemic_stroke', 4, 'Brain tumor', 'Subacute progressive deficits, often with headache, and a mass lesion on imaging.'),
    ('ischemic_stroke', 5, 'Sepsis or metabolic encephalopathy', 'Global confusion without a consistent focal vascular pattern, with fever or metabolic derangement.'),
    ('migraine', 0, 'Tension-type headache', 'Bilateral pressing or band-like pain of mild-to-moderate intensity, not aggravated by routine activity, without nausea.'),
    ('migraine', 1, 'Cluster headache', 'Strictly unilateral severe orbital pain lasting 15-180 minutes with ipsilateral tearing, nasal congestion and restlessness; more common in men.'),
    ('migraine', 2, 'Subarachnoid hemorrhage (ruptured aneurysm)', 'Thunderclap onset reaching maximum within a minute, often with neck stiffness or reduced consciousness.'),
    ('migraine', 3, 'Acute ischemic stroke or TIA', 'Sudden negative symptoms (weakness, visual loss) without gradual spread, in a vascular territory, often in older patients with vascular risk factors.'),
    ('migraine', 4, 'Meningitis', 'Fever, neck stiffness and altered mental status with abnormal cerebrospinal fluid.'),
    ('migraine', 5, 'Giant cell (temporal) arteritis', 'New headache after 50 with scalp tenderness, jaw claudication and raised ESR/CRP.'),
    ('chikungunya', 0, 'Dengue', 'Retro-orbital pain, bleeding manifestations, marked thrombocytopenia and plasma leakage; arthralgia is less prominent. Laboratory testing is needed to separate them'),
    ('chikungunya', 1, 'Zika virus infection', 'Same Aedes vectors; usually milder fever with rash and conjunctivitis, less severe arthralgia'),
    ('chikungunya', 2, 'Leptospirosis', 'Floodwater or animal-urine exposure, calf tenderness, conjunctival suffusion, jaundice and acute kidney injury'),
    ('chikungunya', 3, 'Rheumatoid arthritis', 'Gradual onset without an acute febrile illness; relevant when chronic post-chikungunya arthritis persists'),
    ('hepatitis_b', 0, 'Hepatitis A', 'Fecal-oral spread, shorter incubation, IgM anti-HAV positive; does not become chronic'),
    ('hepatitis_b', 1, 'Leptospirosis', 'Floodwater or animal-urine exposure, high fever, calf tenderness, conjunctival suffusion and acute kidney injury with jaundice'),
    ('hepatitis_b', 2, 'Drug-induced liver injury', 'Temporal link to a hepatotoxic drug (e.g., antituberculosis agents); HBV serology negative'),
    ('hepatitis_b', 3, 'Alcohol-associated liver disease', 'History of heavy alcohol use; HBsAg negative'),
    ('hepatitis_a', 0, 'Hepatitis B', 'Perinatal, blood or sexual transmission, longer incubation, HBsAg and IgM anti-HBc positive; can become chronic'),
    ('hepatitis_a', 1, 'Leptospirosis', 'Floodwater or animal-urine exposure, calf tenderness, conjunctival suffusion and acute kidney injury; transaminases usually only modestly raised'),
    ('hepatitis_a', 2, 'Drug-induced liver injury', 'Temporal link to a hepatotoxic drug (e.g., antituberculosis agents); IgM anti-HAV negative'),
    ('hepatitis_a', 3, 'Biliary obstruction (e.g., choledocholithiasis)', 'Colicky right upper quadrant pain with dilated bile ducts on ultrasound and a predominantly cholestatic liver test pattern'),
    ('cholera', 0, 'Acute infectious gastroenteritis (e.g., enterotoxigenic E. coli, norovirus)', 'Usually smaller stool volumes and slower dehydration; stool culture does not grow V. cholerae'),
    ('cholera', 1, 'Bacillary dysentery (shigellosis)', 'Bloody, mucoid stools with fever and tenesmus; cholera stools are watery without blood'),
    ('cholera', 2, 'Typhoid fever', 'Prolonged step-ladder fever and systemic illness; diarrhea is not the dominant feature'),
    ('cholera', 3, 'Preformed-toxin food poisoning (Staphylococcus aureus, Bacillus cereus)', 'Onset within hours of a shared meal, vomiting-predominant and short-lived'),
    ('rabies', 0, 'Tetanus', 'Trismus and generalized muscle rigidity with spasms and preserved consciousness; no hydrophobia or encephalopathy'),
    ('rabies', 1, 'Guillain-Barre syndrome', 'Ascending symmetric weakness with areflexia and CSF albuminocytologic dissociation; mimics paralytic rabies but without bite-site paresthesia or progression to encephalitis'),
    ('rabies', 2, 'Other viral encephalitis (e.g., Japanese encephalitis, herpes simplex encephalitis)', 'No animal exposure history and no hydrophobia or aerophobia; different viral testing and imaging findings'),
    ('rabies', 3, 'Acute psychosis or delirium', 'No fever, hypersalivation, pharyngeal spasms or progressive neurological deficits'),
    ('schistosomiasis', 0, 'Amoebic colitis (Entamoeba histolytica)', 'Trophozoites or cysts rather than schistosome eggs on stool examination; liver abscess rather than periportal fibrosis'),
    ('schistosomiasis', 1, 'Chronic hepatitis B or other causes of cirrhosis', 'Hepatocellular dysfunction and cirrhotic nodular liver, with viral markers; schistosomal periportal fibrosis causes presinusoidal portal hypertension with relatively preserved liver function'),
    ('schistosomiasis', 2, 'Typhoid fever', 'May resemble acute schistosomiasis with fever and hepatosplenomegaly, but shows positive blood culture and lacks eosinophilia'),
    ('schistosomiasis', 3, 'Colorectal neoplasia or inflammatory bowel disease', 'Blood in stool without freshwater exposure or schistosome eggs; diagnosed by colonoscopy and biopsy'),
    ('pertussis', 0, 'Viral respiratory infections (e.g., RSV bronchiolitis, adenovirus)', 'Shorter course, often with fever and wheeze; lacks prolonged paroxysms with whoop and post-tussive vomiting'),
    ('pertussis', 1, 'Mycoplasma pneumoniae infection', 'Prolonged cough in older children and adults with fever, headache and radiographic infiltrates; PCR distinguishes'),
    ('pertussis', 2, 'Bordetella parapertussis infection', 'Pertussis-like but usually milder illness without marked lymphocytosis; identified by species-specific PCR'),
    ('pertussis', 3, 'Foreign body aspiration', 'Sudden onset of cough or choking without a catarrhal prodrome; focal findings on examination or imaging'),
    ('pertussis', 4, 'Asthma', 'Recurrent wheeze and variable airflow limitation responsive to bronchodilators; no whoop or post-tussive vomiting'),
    ('hfmd', 0, 'Herpangina', 'Also enteroviral, but ulcers are confined to the posterior oropharynx and soft palate without a vesicular rash on the hands and feet'),
    ('hfmd', 1, 'Herpetic gingivostomatitis (HSV-1)', 'Prominent gingivitis and anterior oral and perioral lesions, without acral vesicles'),
    ('hfmd', 2, 'Chickenpox (Varicella)', 'Intensely itchy vesicles in successive crops on the trunk and face, with lesions at all stages at once; palms and soles are not the main sites'),
    ('hfmd', 3, 'Erythema multiforme', 'Target lesions on the extremities, often following HSV infection or a drug'),
    ('hfmd', 4, 'Mpox', 'Deep-seated, often umbilicated lesions progressing in synchrony, with prominent lymphadenopathy'),
    ('varicella', 0, 'Hand, Foot and Mouth Disease', 'Painful oral ulcers with non-pruritic vesicles concentrated on the palms, soles and buttocks in young children'),
    ('varicella', 1, 'Mpox or smallpox', 'Deeper lesions that progress in synchrony (all at the same stage), with a centrifugal distribution and, in mpox, prominent lymphadenopathy'),
    ('varicella', 2, 'Disseminated herpes simplex or eczema herpeticum', 'Clustered, punched-out vesicles on areas of pre-existing eczema; HSV PCR positive'),
    ('varicella', 3, 'Impetigo', 'Localized honey-colored crusted lesions, usually around the nose and mouth, without fever or crops of new vesicles'),
    ('varicella', 4, 'Insect bites (papular urticaria)', 'Grouped itchy papules on exposed skin without fever or evolution through vesicles to crusts'),
    ('hiv_infection', 0, 'Infectious mononucleosis (EBV) or CMV infection', 'Similar fever, pharyngitis and lymphadenopathy, but heterophile or EBV/CMV serology positive and HIV antigen/antibody and RNA negative; mucocutaneous ulcers favor acute HIV'),
    ('hiv_infection', 1, 'Pulmonary Tuberculosis', 'Chronic cough, fever, night sweats and weight loss with sputum or radiographic evidence of TB; frequently coexists with HIV, so both are tested'),
    ('hiv_infection', 2, 'Acute viral hepatitis', 'Jaundice and markedly raised transaminases with positive hepatitis serology'),
    ('hiv_infection', 3, 'Secondary immunodeficiency (malnutrition, chemotherapy)', 'Low CD4 counts and infections with a clear alternative cause and negative HIV testing');
